import java.util.Scanner

object Main extends App {
  val scanner = new Scanner(System.in)
  val w = scanner.nextLine()

  def uni: String => Boolean = {
    case s if s.length == 0 => true
    case s => s.forall {
      _ == s.head
    }
  }

  def calcKmp(s: String): Seq[Int] = {
    val kmp = new Array[Int](s.length() + 1)
    var j = -1

    kmp(0) = -1

    for (i <- 0 until s.length()) {
      while (j > -1 && s(j) != s(i))
        j = kmp(j)

      j += 1
      kmp(i + 1) = j
    }

    kmp
  }

  def calcPeriod(s: String): Seq[Int] = {
    val kmp = calcKmp(s: String)
    (1 to s.length(), kmp.tail).zipped.map(_ - _)
  }

  def calcGood(s: String): (Int, Int) = {
    if (uni(s)) return (w.length, 1)
    val p = calcPeriod(s).last
    if (p == s.length || s.length % p != 0) return (1, 1)

    val pattern = (calcPeriod(s).init, calcPeriod(s.reverse).init.reverse, 1 until s.length).zipped.count {
      case (l: Int, r: Int, length: Int) =>
        val rLength = s.length - length
        val leftIsGood = length == l || length % l != 0
        val rightIsGood = rLength == r ||  rLength % r != 0
        leftIsGood && rightIsGood
    }
    (2, pattern)

  }

  val (cut, pattern) = calcGood(w)
  println(cut)
  println(pattern)
}

