        for(int i=0;i<div.size();i++){//div[i]個の文字からなる周期を持つのかチェックする。
            string tmp=str.substr(0,div[i]);
            int j=0;
            bool fla=true;
            while(j+div[i]<=sz){
                string hikaku=str.substr(j,div[i]);
                if(tmp!=hikaku){
                    fla=false;
                    break;
                }
                j+=div[i];
            }
            if(fla){
                syuuki=div[i];
                break;
            }
        }
        if(syuuki==sz){
            cout<<1<<endl;
            cout<<1<<endl;
        }else{
            cout<<2<<endl;
            bool bad1[500001]={};
            for(int i=1;i<=sz/2;i++){
                if(!bad1[2*i]){
                    string tmp=str.substr(0,i);
                    int j=i;
                    while( tmp==str.substr(j,i) ){
                        bad1[j+i]=true;
                        j+=i;
