void build(){
  bs[ 0 ] = 1;
  for( int i = 1 ; i < N ; i ++ )
    bs[ i ] = mul( bs[ i - 1 ] , BS );
  for( int i = 2 ; i < N ; i ++ )
    for( int j = 1 ; j < i ; j ++ )
      if( i % j == 0 )
        divv[ i - j ].push_back( j );
}
inline void make_hash(){
  for( int i = 1 ; i <= n ; i ++ )
    hs[ i ] = add( mul( hs[ i - 1 ] , BS ) , c[ i ] );
}
inline int hs_vl( int l , int r ){
  return sub( hs[ r ] , mul( hs[ l - 1 ] , bs[ r - l + 1 ] ) );
}
bool ng[ N ][ N ];
void init(){
  scanf( "%s" , c + 1 );
  n = strlen( c + 1 );
  make_hash();
}
vector< PII > v[ N ];
int sv[ N ];
int mn_num[ N ] , way[ N ];
void go_dp(){
  for( int i = 1 ; i <= n ; i ++ )
    mn_num[ i ] = n + 1;
  way[ 0 ] = 1;
  for( int i = 1 ; i <= n ; i ++ )
    for( int j = 1 ; j <= i ; j ++ ){
      if( ng[ j ][ i ] ) continue;
      int tnum = mn_num[ j - 1 ] + 1;
      if( tnum == mn_num[ i ] )
        way[ i ] = add( way[ i ] , way[ j - 1 ] );
      else if( tnum < mn_num[ i ] ){
        mn_num[ i ] = tnum;
        way[ i ] = way[ j - 1 ];
      }
    }
}
void solve(){
  for( int i = 1 ; i <= n ; i ++ ){
    for( int j = i + 1 ; j <= n ; j ++ )
      v[ j - i + 1 ].push_back( { hs_vl( i , j ) , i } );
    if( i < n && c[ i ] == c[ i + 1 ] )
      ng[ i ][ i + 1 ] = true;
  }
  for( int i = 2 ; i <= n ; i ++ ){
    sort( ALL( v[ i ] ) );
    for( size_t l = 0 , r = 0 ; l < v[ i ].size() ; l = r ){
      while( r < v[ i ].size() && v[ i ][ l ].FI == v[ i ][ r ].FI )
        r ++;
      for( size_t j = l ; j < r ; j ++ )
        sv[ v[ i ][ j ].SE ] = v[ i ][ j ].FI;
      for( size_t j = l ; j < r ; j ++ ){
        int nowid = v[ i ][ j ].SE;
