          if( sv[ nowid + tdiv ] == v[ i ][ j ].FI )
            ng[ nowid ][ nowid + tdiv + i - 1 ] = true;
        }
      }
    }
  }
  go_dp();
  printf( "%d\n%d\n" , mn_num[ n ] , way[ n ] );
}
