struct SA : public vi{
  int n, k;
  vi rank, tmp;

  bool compare( int i , int j ){
    if( rank[i] != rank[j] ) return rank[i] < rank[j];

    int ri = i + k <= n ? rank[i+k] : -1;
    int rj = j + k <= n ? rank[j+k] : -1;
    return ri < rj;
  }

  struct Compare_SA{
    SA *sa;
    Compare_SA( SA *s ) : sa(s) {}
    bool operator() ( const int &i , const int &j ){
      return sa->compare( i , j );
    }
  };

  void init( string S ){
    n = S.length();

    resize( n+1 );
    rank = tmp = vi( n+1 );
    REP( i , n+1 ){
      at(i) = i;
      rank[i] = i < n ? S[i] : -1;
    }

    for( k = 1; k <= n; k *= 2 ){
      sort( begin() , end() , Compare_SA(this) );

      tmp[at(0)] = 0;
      FOR( i , 1 , n+1 )
	tmp[at(i)] = tmp[at(i-1)] + (compare(at(i-1),at(i))?1:0);

      REP( i , n+1 ) rank[i] = tmp[i];
    }
  }
};

struct LCP : public vi{
  void init( string S , const SA &sa ){
    int n = S.length();

    vi rank(n+1);
    REP( i , n+1 ) rank[sa[i]] = i;

    int h = 0;
    resize( n , 0 );
    REP( i , n ){
      int j = sa[rank[i]-1];

      if( h > 0 ) h--;
      for( ; j+h < n && i+h < n; h++ ) if( S[j+h] != S[i+h] ) break;

      at(rank[i]-1) = h;
    }
  }
};

template<class T>
class MinOp{
public:
  T operator () ( T a , T b ){ return min( a , b ); }
};
template<class T>
class MaxOp{
public:
  T operator () ( T a , T b ){ return max( a , b ); }
};

template<typename T, class OpFunc>
struct Segtree{
  T ID;
  vector<T> node;
  int size;
  OpFunc op;
  void init( int n , OpFunc opfunc , T identity ){
    op = opfunc;
    ID = identity;
    size = 1;
    while( size < n ) size *= 2;
    node = vector<T>( size*2-1 , ID );
  }
  void update( int k , T x ){
    k += size-1;
    node[k] = x;
    while( k > 0 ){
      k = (k-1)/2;
      node[k] = op( node[k*2+1] , node[k*2+2] );
    }
  }
  T query( int a , int b , int k , int l , int r ){
    if( a <= l && r <= b ){
      return node[k];
    } else if( b <= l || r <= a ){
      return ID;
    } else {
      T chl = query( a , b , k*2+1 , l , (l+r)/2 );
      T chr = query( a , b , k*2+2 , (l+r)/2 , r );
      return op( chl , chr );
    }
  }
  T query( int a , int b ){
    return query( a , b , 0 , 0 , size );
  }
  T get( int a ){
    return node[a+size-1];
  }
};

struct RangeLCP{
  SA sa;
  LCP lcp;
  Segtree<int,MinOp<int> > seg;
  void init( string s ){
    sa.init( s );
    lcp.init( s , sa );
    seg.init( SZ(s) , MinOp<int>() , INF );
    REP( i , SZ(s) ){
      seg.update( i , lcp[i] );
    }
  }
  int sa_query( int l , int r ){
    return seg.query( l , r );
  }
  int pos_query( int l , int r ){
    int a = sa.rank[l];
    int b = sa.rank[r];
    if( a > b ){
      swap( a , b );
    }
    return seg.query( a , b );
  }
};

int n;
string s, rs;
int p;

RangeLCP lcp, rlcp;

bool ng[1000010];

int main(){

  rs = s = stin();
  n = SZ(s);
  REVERSE( rs );

  lcp.init( s );
  rlcp.init( rs );

  FOR( i , 1 , n+1 ){
    if( n % i != 0 ){
      continue;
    }
    if( lcp.pos_query( 0 , i ) == n-i ){
      p = i;
      break;
    }
  }

  if( p == 1 ){
    cout << n << endl;
    cout << 1 << endl;
  } else if( p == n ){
    cout << 1 << endl;
    cout << 1 << endl;
  } else {
    FOR( i , 1 , n+1 ){
      int r = lcp.pos_query( 0 , i );
      for( int j = i; j <= r; j += i ){
	ng[i+j] = true;
      }
    }

    FOR( i , 1 , n+1 ){
      int r = rlcp.pos_query( 0 , i );
      for( int j = i; j <= r; j += i ){
	ng[n-(i+j)] = true;
      }
    }

    int ans = 0;
    FOR( i , 1 , n ){
      if( !ng[i] ){
	ans++;
      }
    }
    cout << 2 << endl;
