using Hash = __int128;

const Hash A = 1e9 + 7;
const Hash B = 1e12 + 39;
const Hash C = 1e6 + 3;
const Hash MOD = 1e18;
int main(){
    string w;
    cin >> w;
    int n = w.size();
    vector<Hash> h(n + 1);
    vector<Hash> powA(n + 1);
    map<char, Hash> dict;
    dict['a'] = B;
    for (char x = 'a'; x != 'z'; x++){
        dict[x + 1] = (dict[x] * C + B) % MOD;
    }

    powA[0] = 1;
    for (int i = 0; i < n; i++){
        h[i + 1] = (h[i] * A + dict[w[i]]) % MOD;
        powA[i + 1] = (powA[i] * A) % MOD;
    }
    auto getHash = [&](int l, int r) {
        return ((h[r] - (h[l] * powA[r - l]) % MOD) % MOD + MOD) % MOD;
    };

    vector<int> ok(n + 1, 1);
    for (int i = 1; i <= n; i++){
        //s[0:i)
        Hash oh = getHash(0, i);
        for (int j = 1; (j + 1) * i <= n; j++){
            Hash nh = getHash(j * i, (j + 1) * i);
            if (oh == nh){
                ok[(j + 1) * i] = 0;
            }
            else{
                break;
            }
        }
    }
    for (int i = 1; i <= n; i++){
        //s[n-i:n)
        Hash oh = getHash(n - i, n);
        for (int j = 1; n - (j + 1) * i >= 0; j++){
            Hash nh = getHash(n - (j + 1) * i, n - j * i);
            if (oh == nh){
                ok[n - (j + 1) * i] = 0;
            }
            else{
                break;
            }
        }
    }
    int cnt=accumulate(ok.begin(),ok.end(),0);
    if(ok[0]){
        cout<<1<<endl;
        cout<<1<<endl;
    }
    else if(cnt==0){
        cout<<n<<endl;
        cout<<1<<endl;
    }
    else{
        cout<<2<<endl;
        cout<<cnt<<endl;
    }

    return 0;
}

