void build(){
	fi(0, n+1) p[i] = s[i] = 1;
	fi(1, n+1){
		vector<int> h = Hash::gethash(0, i-1);
		for(int j=i+i;j<=n;j+=i){
			vector<int> h0 = Hash::gethash(j-i, j-1);
			if(h != h0) break;
			p[j-1] = 0;
		}
	}
	fi(1, n+1){
		vector<int> h = Hash::gethash(n-i, n-1);
		for(int j=i+i;j<=n;j+=i){
			vector<int> h0 = Hash::gethash(n-j, n-j+i-1);
			if(h != h0) break;
			s[n-j] = 0;
		}
	}
}

