struct RollingHash{
  typedef unsigned long long ull;
  string S;
  ull B;
  Int len;
  vector<ull> hash,p;
  RollingHash(){}
  RollingHash(string S_,ull B_=1000000007LL):
    S(S_),B(B_),len(S.length()),hash(len+1),p(len+1){
    hash[0]=0;p[0]=1;
    for(Int i=0;i<len;i++){
      hash[i+1]=hash[i]*B+S[i];
      p[i+1]=p[i]*B;
    }
  }
  //S[l,r)
  ull find(Int l,Int r){
    return hash[r]-hash[l]*p[r-l];
  }
};

struct RollingHash2{
  typedef unsigned long long ull;
  string S;
  ull B;
  Int len;
  vector<ull> hash,p;
  const ull MOD = 1000000007LL;
  RollingHash2(){}
  RollingHash2(string S_,ull B_=177771):
    S(S_),B(B_),len(S.length()),hash(len+1),p(len+1){
    hash[0]=0;p[0]=1;
    for(Int i=0;i<len;i++){
      hash[i+1]=(hash[i]*B+S[i])%MOD;
      p[i+1]=p[i]*B%MOD;
    }
  }
  //S[l,r)
  ull find(Int l,Int r){
    return (hash[r]+MOD-hash[l]*p[r-l]%MOD)%MOD;
  }
};

