T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


vector<int> prefixFunction(const string& s) {
    int n = (int)s.length();
    vector<int> res(n);
    for (int i = 1; i < n; ++i) {
        int j = res[i - 1];
        while (j > 0 && s[i] != s[j]) {
            j = res[j - 1];
        }
        if (s[i] == s[j]) {
            ++j;
        }
        res[i] = j;
    }
    return res;
}


bool isCyclic(int p, int n) {
  int k = n - p;
  if(k > 0 && k < n && n % k == 0) {
    return true;
  }
  return false;
}

void solve(istream& in, ostream& out) {
  auto s = next<string>(in);
  bool allEq = true;
  FOR(i, s.length()) if (s[i] != s[0]) {
    allEq = false;
      break;
  }
  if (allEq) {
    out << s.length() << "\n";
    out << 1 << "\n";
    return;
  }

  auto rs = s;
  reverse(all(rs));
  auto n = (int)s.length();

  auto ps = prefixFunction(s);
  auto rps = prefixFunction(rs);
  int k = n - ps[n-1];
  if (k > 0 && k < n && n % k == 0) {
    out << 2 << "\n";
    int res = 0;
    for (int i = 0; i < n-1; ++i) {
      int rn = n - (i + 1);
      int j = n - 1 - i - 1;
      if (isCyclic(ps[i], i + 1) || isCyclic(rps[j], rn)) {
        continue;
      } else {
        ++res;
      }
    }
    out << res << "\n";
  } else {
    out << 1 << "\n" << 1 << "\n";
  }
}

