const int root = 1000;

string w;
vector<int> primes;

void init_primes() {
    vector<int> sieve((int)w.size(), 1);
    sieve[0] = sieve[1] = 0;

    for (int i = 2; i < root && i < w.size(); ++i) 
        if (sieve[i]) 
            for (int j = i*i; j < sieve.size(); j += i)
                sieve[j] = 0;

    for (int i = 2; i < sieve.size(); ++i)
        if (sieve[i]) primes.push_back(i);
}

bool check(int p) {
    for (int i = p; i < w.size(); i += p)
        for (int j = 0; j < p; ++j)
            if (w[j] != w[i+j]) {
                return 0;
            }

    return 1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> w;
    init_primes();
    vector<int> divisors;
    if (check(1)) {
        cout << w.size() << endl << 1 << endl;
        return 0;
    }

    for (int p: primes) {
        if (w.size() % p == 0 && check(p)) divisors.push_back(p);
    }

    if (divisors.empty()) {
        cout << 1 << endl << 1 << endl;
        return 0;
    }
    if (divisors.back()*2 == w.size()) divisors.pop_back();

    int ans = 0;
    for (int i = 1; i < w.size(); ++i) {
        int flag = 1;
        for (int x: divisors) {
            if (i % x == 0) {
                flag = 0; break;
            }
        }
        ans += flag;
    }

    cout << 2 << endl << ans << endl;

    return 0;
}

