void cal_next(int *z,int n,int *nxt)
{
	memset(buc,0x3f,sizeof(int)*(2*n+2));
	for(int i=n;i>=2;--i)buc[z[i]+i]=i;
	for(int i=2*n;i;--i)buc[i]=min(buc[i],buc[i+1]);
	for(int i=2;i<=n;++i)if(buc[i+1]<=i)nxt[i]=i-buc[i+1]+1;
}
