const int N = 500000 + 5;

int n;
char s[N];
int f[N];

void KMP() {
	for (int i = 2, j = 0; i <= n; i++) {
		while (j && s[j + 1] != s[i]) j = f[j];
		if (s[j + 1] == s[i]) j++;
		f[i] = j;
	}
}

int main() {
	scanf("%s", s + 1);
	n = strlen(s + 1);
	KMP();
	if (f[n] == 0 || n % (n - f[n])) {
		printf("1\n1\n");
		return 0;
	} else {
		int d = n / (n - f[n]);
		if (d == n) {
			printf("%d\n%d\n", n, 1);
			return 0;
		}
		if (d == 2) n++;
		printf("2\n%d\n", n - d);
	}
	return 0;
}

