vector<int> z_algorithm(string s) {
	vector<int> res(s.size());

	res[0] = s.size();

	int i = 1, j = 0;

	while (i < s.size()) {
		while (i + j < s.size() && s[j] == s[i + j]) j++;
		res[i] = j;
		if (j == 0) { i++; continue; }
		int k = 1;
		while (i + k < s.size() && k + res[k] < j) res[i + k] = res[k], k++;
		i += k;
		j -= k;
	}

	return res;
}

string w;
bool cut[512345], rcut[512345];
vector<int> z, rz;

int main() {
	string w; cin >> w;
	int N = w.size();

	z = z_algorithm(w);
	fill(cut, cut + N + 1, true);
	FOR(i, 1, N) {
		if (!cut[i]) continue;
		for (int j = i; j <= z[i]; j += i) cut[j + i] = false;
	}

	reverse(ALL(w));

	rz = z_algorithm(w);
	fill(rcut, rcut + N + 1, true);
	FOR(i, 1, N) {
		if (!rcut[i]) continue;
		for (int j = i; j <= rz[i]; j += i) rcut[j + i] = false;
	}

	int cnt = 0;
	FOR(i, 1, N) if (cut[i] && rcut[N - i]) cnt++;

	bool same = count(ALL(w), w[0]) == N;
	bool good = cut[N];

	int a, b;
	if (same) a = N, b = 1;
	else if (good) a = 1, b = 1;
	else a = 2, b = cnt;

	printf("%d\n%d\n", a, b);

	return 0;
}

