struct Hash {
  random_device rnd;
  mt19937 mt;
  uniform_int_distribution<LL> dist;
  vector<long long> prime, base;
  vector<vector<long long>> value, memo;
  int n;
  Hash(const vector<long long> &primes) : mt(rnd()), dist(1000, 1e7), prime(primes), n(primes.size()) {
    for (int i = 0; i < n; ++i) base.push_back(dist(mt));
    value.push_back({0LL, 0LL, 0LL});
    memo.push_back({1LL, 1LL, 1LL});
  };
  Hash() : Hash({999999937LL, 1000000007LL}){};
  void push_back(long long x) {
    int l = value.size();
    value.push_back(vector<long long>(n));
    memo.push_back(vector<long long>(n));
    for (int i = 0; i < n; ++i) {
      value[l][i] = (value[l - 1][i] * base[i] + x) % prime[i];
      memo[l][i] = memo[l - 1][i] * base[i] % prime[i];
    }
  }
  vector<long long> get(int l, int r) {
    //get the hash of inteval [l,r)
    auto R = value[r];
    auto L = value[l];
    for (int i = 0; i < n; ++i) {
      L[i] = L[i] * memo[r - l][i] % prime[i];
      R[i] = (R[i] - L[i]) % prime[i];
      if (R[i] < 0) R[i] += prime[i];
      //R[i] *= modpow(base[i], (r - l) * (prime[i] - 2) % (prime[i] - 1), prime[i]);
    }
    return R;
  }
  bool equals(int l, int r, int l2, int r2) {
    return get(l, r) == get(l2, r2);
  }
};
class Solver {
 public:
  string s;
  int n;
  Solver(string s) : s(s), n(s.length()){};
  int minPeriod(string str) {
    int l = str.length();
    for (int i = 1; i < l; ++i) {
      if (l % i == 0) {
        string tmp = str;
        rotate(tmp.begin(), tmp.begin() + i, tmp.end());
        if (tmp == str) return i;
      }
    }
    return n;
  }
  void solve() {
    int p = minPeriod(s);
    if (p == n) {
      cout << 1 << endl;
      cout << 1 << endl;
    } else if (p == 1) {
      cout << n << endl;
      cout << 1 << endl;
    } else {
      cout << 2 << endl;
      string rev = s;
      reverse(rev.begin(), rev.end());
      Hash hs, rhs;
      vector<int> isGood(n, 1);
      for (int i = 0; i < n; ++i) {
        hs.push_back(s[i] - 'a');
        rhs.push_back(rev[i] - 'a');
      }
      for (int i = 1; i < n; ++i) {
        auto hash0i = hs.get(0, i);
        for (int j = i * 2; j < n; j += i) {
          if (hs.get(j - i, j) != hash0i) break;
          isGood[j] = 0;
        }
      }
      for (int i = 1; i < n; ++i) {
        auto hash0i = rhs.get(0, i);
        for (int j = i * 2; j < n; j += i) {
          if (rhs.get(j - i, j) != hash0i) break;
          isGood[n - j] = 0;
        }
      }
      cout << accumulate(isGood.begin() + 1, isGood.end(), 0) << endl;
    }
  }
};
