class RollingHash{
public:
  typedef long long ll;
  ll B, mod;  //B: ハッシュ基数
  Int n;
  string s;
  vector<ll> hash;
  vector<ll> k;

  RollingHash():n(-1){};
  RollingHash(string s,ll B = 1777771,ll mod = 1e9 + 7):
    B(B),mod(mod),n(s.size()),s(s),hash(n+1),k(n+1)
  {
    for(Int i=0;i<n;i++) hash[i+1] = (hash[i] * B % mod + s[i]) % mod;
    k[0] = 1;
    for(Int i=1;i<=n;i++) k[i] = (k[i-1] * B) % mod;
  }

  ll get(Int l,Int r){ //[l, r)
    assert(0<=l && r<=n && l<=r);
    return (mod + hash[r] - hash[l] * k[r-l] % mod) % mod;
  }

  //hash[a]とB.hash[b]からみて何文字一致してるか。
  Int count(Int a, RollingHash &B, Int b){
    Int L = 0, R = min( n - a, B.n - b ) + 1;
    while( L + 1 < R ){
      Int M = ( L + R ) / 2;
      get( a, a + M ) != B.get( b, b + M ) ? R = M : L = M;
    }
    return L;
  }
};
typedef unsigned long long ull;
RollingHash R;
Int n;
string str;

bool can(Int l,Int r){//[l,r)
  Int len = r - l;
  if(len == 1) return 1;
  for(Int i=1;i<len;i++){
    if(len % i) continue;
    ull a = R.get(l+i, r);
    ull b = R.get(l, r - i);
    if(a == b) return 0;
  }
  return 1;
}

Int dfs(Int idx){
    static Int used[10000]={}, mem[10000] = {};
    if(idx == n) return 0;
    if(used[idx]++) return mem[idx];

    Int res = INF;
    for(Int nidx = idx+1; nidx <= n; nidx++){
      if(!can(idx, nidx)) continue;
      Min(res, 1+dfs(nidx));
    }
    return mem[idx] = res;
}

Int count(Int idx){
  static Int used[10000]={}, mem[10000];
  if(idx == n) return 1;
  if(used[idx]++) return mem[idx];

  Int res = 0;
  Int mn = dfs(idx);
  for(Int nidx = idx+1; nidx <= n; nidx++){
    if(!can(idx, nidx)) continue;
    if(mn != 1 + dfs(nidx)) continue;
    res = (res + count(nidx)) % mod;
  }
  return res;
}

