vector<ll> z_algo(string S) {//0-index
	ll N = S.size();

	vector<ll> A(N, 0);


	ll c = 0;
	repn(i, N - 1) {
		if (c > 0 && i - c + A[i - c] < A[c]) { A[i] = A[i - c]; }
		else {
			ll j = max(0, c + A[c] - i);
			while (i + j < N && S[j] == S[i + j]) { j++; }
			A[i] = j;
			c = i;
		}
	}

	A[0] = N;

	return A;
}

