using namespace std;

const int maxw = 500000;

template <class T, class U = int>
struct KnuthMorrisPratt {
	static const int maxn = maxw;

	int n;
	T p[maxn];
	U f[maxn + 1];

	KnuthMorrisPratt() : n(0) {

	}

	U & operator [] (const int & x) {
		return f[x];
	}

	void build(const T * first, const T * last) {
		const T * & p = first;
		n = last - first;
		memcpy(this->p, p, sizeof p[0] * n);
		f[0] = f[1] = 0;
		for (int i = 1, k; i < n; i++) {
			for (k = f[i]; k > 0 && p[k] != p[i]; k = f[k]);
			if (p[k] == p[i])
				k++;	
			f[i + 1] = k;
		}
	}
};

char w[maxw + 1];
KnuthMorrisPratt<char> KMP, KMPr;

inline bool valid(const int & n, const int & l) {
	return n % l > 0 || n == l;
}

pair<int, int> answer() {
	int n = strlen(w);
	KMP.build(w, w + n);
	reverse(w, w + n);
	KMPr.build(w, w + n);

	int l = n - KMP[n];
	if (valid(n, l))
		return make_pair(1, 1);
	else if (l > 1) {
		int ans = (n / l - 2) * (l - 1);
		for (int i = 1; i < l; i++) {
			for (int j = 0; j < 2; j++) {
				int z = j ? n - i : i;
				int x = z - KMP[z], y = n - z - KMPr[n - z];
				if (valid(z, x) && valid(n - z, y))
					ans++;
			}
		}
		if (n == l * 2) {
			int r = l - KMP[l];
			if (valid(l, r))
				ans++;
		}
		return make_pair(2, ans);
	} else
		return make_pair(n, 1);
}

