vector<int> z_func(string &s) {
  vector<int> z(len(s), 0);
  int l = 0, r = 1;

  rep(i, 1, sz(z) - 1) {
    if (i >= r) {
      l = r = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    } else if (z[i - l] < r - i) {
      z[i] = z[i - l];
    } else {
      z[i] = r - i;
      l = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    }
  }

  return z;
}

bool can_divide(vector<int> &z, int &prefix_len, int end) {
  for (int i = prefix_len; i < end; i += prefix_len)
    if (z[i] < prefix_len) 
      return false;
  return true;
}

void solve() {
  string s;
  cin >> s;

  string rev_s = s;
  reverse(all(rev_s));

  auto z = z_func(s);
  auto rev_z = z_func(rev_s);

  per(i, sz(z) - 1, 0) {
    if (i + z[i] != len(s)) continue;

    bool can = can_divide(z, z[i], sz(z));

    if (can && z[i] == 1) {
      cout << len(s) << nl << 1;
      return;
    } 

    if (can) {
      int res = 0;

      rep(j, 1, len(s) - 1) {
        bool can_left = false, can_right = false;
        per(k, j - 1, 0) {
          if (k + z[k] != j) continue;
          can_left |= can_divide(z, z[k], j);
        }
        per(k, len(s) - j - 1, 0) {
          if (k + rev_z[k] != len(s) - j) continue;
          can_right |= can_divide(rev_z, rev_z[k], len(s) - j);
        }
        if (!can_left && !can_right) {
          res++;
        }
      }

      cout << 2 << nl << res;
      return;
    }
  }

  cout << 1 << nl << 1;
}

