int n;
string s, t;
vector<int> vec[500005];
int z[500005], z2[500005];

void z_algorithm(string &s, int z[])
{
	z[0] = s.size();

	int x = 0, y = 0;
	for(int i = 1; i < s.size(); i++){
		if(i > y){
			z[i] = 0;
			for(int j = 0; j < s.size(); j++){
				if(i+j > s.size() || s[i+j] != s[j]) break;
				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
		else if(i + z[i-x] <= y) z[i] = z[i-x];
		else{
			z[i] = y-i+1;
			for(int j = y-i+1; j < s.size(); j++){
				if(i+j > s.size() || s[i+j] != s[j]) break;
				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
	}
}

bool pre(int r, int p)
{
	return z[p] >= (r+1)-p;
}
bool suf(int l, int p)
{
	l = n-1-l;
	return z2[p] >= (l+1)-p;
}

bool check(int x, bool f)
{
	int len = x+1;
	if(!f) len = n-x;
	if(len == 1) return true;
	for(int i = 0; i < vec[len].size(); i++){
		int d = vec[len][i];
		if(d == len) continue;
		if(f && pre(x, d) || !f && suf(x, d)) return false;
	}
	return true;
}


int main(void)
{
	cin >> s;
	n = s.size();
	z_algorithm(s, z);

	t = s;
	reverse(t.begin(), t.end());
	z_algorithm(t, z2);

	int cyc = n;
	for(int i = 1; i < n; i++){
		if(n % i == 0 && pre(n-1, i)){
			cyc = i;
			break;
		}
	}
	if(cyc == 1){
		cout << n << endl;
		cout << 1 << endl;
		return 0;
	}
	if(cyc == n){
		cout << 1 << endl;
		cout << 1 << endl;
		return 0;
	}

	for(int i = 1; i <= n; i++){
		for(int j = 1; i*j <= n; j++) vec[i*j].push_back(i);
	}

	cout << 2 << endl;
	int ans = 0;
	for(int i = 1; i < n; i++) if(check(i-1, 1) && check(i, 0)) ans++;
	cout << ans << endl;

	return 0;
}

