vector<int> getFail(const string& s) {
	vector<int> fail = {-1};
	for (int i = 0; i < int(s.size()); i++) {
		int cur = fail.back();
		while (cur != -1 && s[i] != s[cur]) {
			cur = fail[cur];
		}
		fail.push_back(cur + 1);
	}
	return fail;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	string s; cin >> s;
	int N = int(s.size());

	vector<int> fail = getFail(s);

	if (fail.back() == N-1) {
		cout << N << '\n';
		cout << 1 << '\n';
		exit(0);
	}

	int len = N - fail.back();
	// whether s[0...i) is cyclic
	auto isCyclic = [&len](int i) -> bool {
//		return i > 1 && f[i] != 0 && i % (i - f[i]) == 0;
		return i != len && i % len == 0;
	};

	if (fail.back() == 0 || N % (N - fail.back()) != 0) {
		cout << 1 << '\n';
		cout << 1 << '\n';
		exit(0);
	}

	int ways = 0;
	for (int i = 1; i < N; i++) {
		if (!isCyclic(i) && !isCyclic(N - i)) {
			ways++;
		}
	}

	cout << 2 << '\n';
	cout << ways << '\n';

	return 0;
}

