			if (S.substr(i - 2 * d, d) != S.substr(i - d, d)) { break; }
			a[i] = 1;
		}

		for (ll i = N - 2 * d; i >= 0; i -= d) {
			if (S.substr(i, d) != S.substr(i + d, d)) { break; }
			a[i] = 1;
		}
	}

	if (!a[0]) {
		cout << 1 << endl;
		cout << 1 << endl;
		return 0;
	}

	cout << 2 << endl;
	ll ans = 0;
	repn(i, N - 1) { if (!a[i]) { ans++; } }

	cout << ans << endl;


}

