struct RollingHash {
    const int base = 10007;
    static const int M = 2;
    const vector<int> mod = {999999937, 1000000007};
    vector<long long> hash[M], power[M];
    RollingHash(const string &s, int base = 9973) : base(base) {
        int n = s.size();
        for (int iter = 0; iter < M; iter++) {
            hash[iter].assign(n + 1, 0);
            power[iter].assign(n + 1, 1);
            for (int i = 0; i < n; ++i) {
                hash[iter][i + 1] = (hash[iter][i] * base + s[i]) % mod[iter];
                power[iter][i + 1] = power[iter][i] * base % mod[iter];
            }
        }
    }
    long long get(int l, int r, int id = 0) {   // [l, r)
        long long ret = hash[id][r] - hash[id][l] * power[id][r - l] % mod[id];
        return ret < 0 ? ret + mod[id] : ret;
    }
};
bool match(RollingHash &rh1, int s1, RollingHash &rh2, int s2, int len) {
    for (int iter = 0; iter < RollingHash::M; iter++)
        if (rh1.get(s1, s1 + len, iter) != rh2.get(s2, s2 + len, iter))
            return false;
    return true;
}

vector<vector<int>> divisors_table(int n) {     // except for n
    vector<vector<int>> divisors(n + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = i + i; j <= n; j += i) divisors[j].emplace_back(i);;
    }
    return divisors;
}

int main() {
    string s; cin >> s;
    int n = s.length();
    if (s == string(n, s[0])) return !(cout << n << endl << 1 << endl);
    RollingHash rh(s);
    auto ds = divisors_table(n);
    auto check = [&](int l, int r) {
        int len = r - l;
        for (int d: ds[len]) if (match(rh, l, rh, l + d, len - d)) return false;
        return true;
    };
    if (check(0, n)) return !(cout << 1 << endl << 1 << endl);
    int cnt = 0;
    for (int i = 1; i < n; i++) cnt += check(0, i) && check(i, n);
    cout << 2 << endl << cnt << endl;
    return 0;
}

