namespace Hash{
	static int const K = 5;
	int h[K][N], d[K][N];
	static int const P[K] = {63, 61, 59, 57, 55};
	static int const MOD[K] = {1000001531, 1000002187, 1000002193, 1000000007, 1000002277};

	int mul(int a, int b, int mod){
		return (ll) a * b % mod;
	}

	int sum(int a, int b, int mod){
		a %= mod;
		while(a < 0) a += mod;
		b %= mod;
		while(b < 0) b += mod;
		return (a + b) % mod;
	}

	void build(){
		fi(0, K) d[i][0] = 1;
		fi(1, N) fj(0, K){
			d[j][i] = mul(d[j][i-1], P[j], MOD[j]);
		}
