using namespace std;

class Hash {
    public:

    Hash(const char *s, long long base = 1009, long long m = 1000000007) : MOD(m) {
        int n = strlen(s);

        hash = (long long *)malloc(sizeof(long long) * (n + 1));
        pow = (long long *)malloc(sizeof(long long) * (n + 1));

        hash[0] = 0;
        pow[0] = 1;

        for (int i = 0; i < n; i++) {
            hash[i + 1] = (hash[i] * base + s[i]) % MOD;
            pow[i + 1] = pow[i] * base % MOD;
        }
    }

    ~Hash() {
        free(hash);
        free(pow);
    }

    //x銇嬨倝y鏂囧瓧銇儚銉冦偡銉ュ€?
    long long get(int x, int y) {
        return (hash[x + y] - hash[x] * pow[y] % MOD + MOD) % MOD;
    }

    private:

    long long MOD;
    long long *hash;
    long long *pow;
};

char s[500001];
int b[500001];
vector <int> v[500001];

bool check(int x, int y, Hash &h1, Hash &h2) {
    int c = y - x, i, j;

    if (c == 1) return true;

    for (i = 0; i < v[c].size(); i++) {
        int z = (y - x) / v[c][i];

        for (j = 1; j * 2 <= v[c][i]; j *= 2) {
            if (h1.get(x, z * j) != h1.get(x + z * j, z * j)) break;
        }

        if (j * 2 <= v[c][i]) continue;

        if (h1.get(x, z * j) != h1.get(y - z * j, z * j)) continue;

        for (j = 1; j * 2 <= v[c][i]; j *= 2) {
            if (h2.get(x, z * j) != h2.get(x + z * j, z * j)) break;
        }

        if (j * 2 <= v[c][i]) continue;

        if (h2.get(x, z * j) != h2.get(y - z * j, z * j)) continue;

        return false;
    }

    return true;
}

