std::vector<int> longest_common_prefix(const std::string& str) {
	std::vector<int> result(str.size(), 0);
	result[0] = str.size();
	int r{ 0 };
	for (auto l = 1; l < str.size();) {
		for (; r + l < str.size() && str[r] == str[l + r]; ++r);
		if (r == 0) {
			++l; continue;
		}
		result[l] = r;
		int d{ 1 };
		for (; result[d] + d < r; ++d) {
			result[l + d] = result[d];
		};
		r -= d;
		l += d;
	}
	return result;
}
std::vector<bool> good_prefix(const std::string& str) {
	const auto common_prefix = longest_common_prefix(str);
	std::vector<bool> result(str.size(), true);
	for (auto i = 1; i < str.size(); ++i) {
		if (!result[i - 1]) continue;
		for (auto k = 1; k * i <= common_prefix[i]; ++k) {
			result[k * i + i - 1] = false;
		}
 	}
	return result;
}
int main() {
	std::string str; std::cin >> str;
	const auto forward = good_prefix(str);
	std::reverse(str.begin(), str.end());
	const auto backward = good_prefix(str);
	if (forward.back()) {
		std::cout << "1\n1\n";
		return 0;
	}
	if (std::distance(str.begin(), std::unique(str.begin(), str.end())) == 1) {
		std::cout << str.size() << "\n1\n";
		return 0;
	}
	int count{ 0 };
	for (auto i = 1; i < str.size(); ++i) {
		if (forward[i - 1] && backward[str.size() - i - 1]) ++count;
	}
	std::cout << "2\n" << count << '\n';
}

