int *buildZ(const string &s){
	int n = s.size();
	int *z = new int[n];
	int l = 0, r = 0;

	memset(z, 0, sizeof(int)*n);
	for(int i = 1; i < n; i++){
		if(i <= r) z[i] = min(z[i - l], r - i + 1);
		while(i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
		if(i + z[i] - 1 > r){
			l = i;
			r = i + z[i] - 1;
		}
	}
	return z;
}

