int nxt[MAXN],suf[MAXN];
bool vis[MAXN];
int gcd(int a,int b) {
    return b == 0 ? a : gcd(b,a % b);
}
void Solve() {
    scanf("%s",s + 1);
    N = strlen(s + 1);
    for(int i = 2 ; i <= N ; ++i) {
	int p = nxt[i - 1];
	while(p && s[p + 1] != s[i]) p = nxt[p];
	if(s[p + 1] == s[i]) nxt[i] = p + 1;
	else nxt[i] = 0;
    }
    if(nxt[N] == N - 1) {
	out(N);enter;puts("1");
    }
    else if(nxt[N] < N - nxt[N] || gcd(N,N - nxt[N]) == 1) {
	puts("1");puts("1");
    }
    else {
	int cnt = 0,l = N - nxt[N];
	suf[N] = N + 1;
	for(int i = N - 1 ; i >= 1 ; --i) {
	    int p = suf[i + 1];
	    while(p <= N && s[p - 1] != s[i]) p = suf[p];
	    if(s[p - 1] == s[i]) suf[i] = p - 1;
	    else suf[i] = N + 1;
	}
	for(int i = N - 1 ; i > 1 ; --i) {
	    if(2 * (N + 1 - suf[i]) >= (N + 1 - i) && gcd(N + 1 - i,N + 1 - suf[i]) != 1) vis[i - 1] = 1;
	}
	for(int i = 1 ; i <= N ; ++i) {
	    if(2 * nxt[i] >= i && gcd(nxt[i],i) != 1) vis[i] = 1;
	}
	for(int i = 1 ; i < N ; ++i) {
	    if(!vis[i]) ++cnt;
	}
	puts("2");out(cnt);enter;
    }
}

