int Gao ()
{
	dp[1] = 0;
	for ( int i = 2; i <= n; ++i )
	{
		int nc = dp[i - 1];
		while ( nc && s[nc + 1] != s[i] )
			nc = dp[nc];
		dp[i] = s[nc + 1] == s[i] ? nc + 1 : 0;
	}
	if ( dp[n] == n - 1 )
		return n;
	if ( !dp[n] || n % ( n - dp[n] ) )
		return 0;
	return 2;
}

void Rn()
{
	for ( int i = 1; i <= n; ++i )
		r[i] = s[n - i + 1];
	rdp[1] = 0;
	for ( int i = 2; i <= n; ++i )
	{
		int nc = rdp[i - 1];
		while ( nc && r[nc + 1] != r[i] )
			nc = rdp[nc];
		rdp[i] = r[nc + 1] == r[i] ? nc + 1 : 0;
	}
}

