const Hash A=1e9+7;
const Hash B=1e12+1;
const Hash C=1e5+7;
const Hash MOD=1e18+9;
int main(){
    string w;
    cin>>w;
    int n=w.size();
    vector<Hash> h(n+1);
    vector<Hash> powA(n+1);
    map<char,Hash> dict;    
    dict['a']=B;
    for(char x='a';x!='z';x++){
        dict[x+1]=(dict[x]*C+B)%MOD;
    }

    powA[0]=1;
    for(int i=0;i<n;i++){
        h[i+1]=(h[i]*A+dict[w[i]])%MOD;
        powA[i+1]=(powA[i]*A)%MOD;
    }
    auto getHash=[&](int l,int r){
        return ((h[r]-(h[l]*powA[r-l])%MOD)%MOD+MOD)%MOD;
    };
    int div=1;
    for(int i=1;i<=n;i++){
        if(n%i!=0) continue;
        bool isbad=true;
        for(int j=1;j<i;j++){
            int pack=n/i;
            int l0=(j-1)*pack;
            int r0=l0+pack;
            Hash h0=getHash(l0,r0);
            int l1=r0;
            int r1=l1+pack;
            Hash h1=getHash(l1,r1);
            isbad&=(h0==h1);
        }
        if(isbad) div=i;
    }


    int res;
    int pat;
    if(div==n){
        res=n;
        pat=1;
    }
    else if(div==1){
        res=1;
        pat=1;
    }
    else{
        res=2;
        pat=0;
        vector<int> ok(n+1,1);
        ok[0]=0,ok[n]=0;
        for(int i=1;i<=n;i++){
            //s[0:i)
            Hash oh=getHash(0,i);
            for(int j=1;j<n/i;j++){
                Hash nh=getHash(j*i,(j+1)*i);
                if(oh==nh){
                    ok[(j+1)*i]=0;
                }
                else{
                    break;
                }
            }
        }
        for(int i=1;i<=n;i++){
            //s[n-i:n)
            Hash oh=getHash(n-i,n);
            for(int j=1;j<n/i;j++){
                Hash nh=getHash(n-(j+1)*i,n-j*i);
                if(oh==nh){
                    ok[n-(j+1)*i]=0;
                }
                else{
                    break;
                }
            }
        }
        pat=accumulate(ok.begin(),ok.end(),0);
    }
    cout<<res<<endl;
    cout<<pat<<endl;

    return 0;
}

