vector<ll> diviser(ll A){

  vector<ll> res;

  for(ll i=1;i*i<=A;i++)
    if(A%i==0){
      res.push_back(i);
      if(i*i!=A) res.push_back(A/i);
    }

  sort(res.begin(), res.end());

  res.pop_back();

  return res;
}

bool check(int l, int r, int d, RollingHash rh){
  if( r - l == 1 ) return true;
  return rh.get( l, r - d ) == rh.get( l + d, r );
}

