template<class Iter> vector<int>Z_Algorithm(Iter a, Iter a_end) {
    int n = a_end - a;
    vector<int>z(n);
    int l = 0, r = 0;
    for (int i=1; i<n; i++) {
	if (i > r) {
	    l = r = i;
	    while (r<n && a[r-l] == a[r]) r++;
	    z[i] = r-l; r--;
	} else {
	    int k = i-l;
	    if (z[k] < r-i+1) z[i] = z[k];
	    else {
		l = i;
		while (r<n && a[r-l] == a[r]) r++;
		z[i] = r-l; r--;
	    }
	}
    }
    return z;
}

