  REP(i, 1, 1000000) {
    prime[i] = 1;
  }
  REP(i, 2, 1001) {
    if (! prime[i]) {
      continue;
    }
    REP(j, 2, 999999 / i + 1) {
      prime[i * j] = 0;
    }
  }
