      good[st][st + i] = 1;
    }
    REP(i, 1, n) {
      bool ok = 0;
      REP(j, 2, n / i + 1) {
	if (za[i * (j - 1)] < i) {
	  ok = 1;
	}
	good[st][st + i * j] &= ok;
      }
    }
  }
  dp[0] = 0;
  REP(i, 1, len + 1) {
    dp[i] = i;
    REP(j, 0, i) {
      if (good[j][i]) {
