inline hash_t get_hash(int l, int r)
{
    return hash_t(
        (h[l].first - h[r + 1].first + HMOD1) * HBASE1_POW[n - r] % HMOD1,
        (h[l].second - h[r + 1].second + HMOD2) * HBASE2_POW[n - r] % HMOD2
    );
}

inline int period(int offset, int len)
{
    static std::vector<int> div;
    div.clear();
    for (int i = 1; i * i <= len; ++i) if (len % i == 0) {
        div.push_back(i);
        if (i != 1 && i * i != len) div.push_back(len / i);
    }
    for (std::vector<int>::iterator d = div.begin(); d != div.end(); ++d) {
        if (get_hash(offset, offset + len - *d - 1) == get_hash(offset + *d, offset + len - 1))
            return *d;
    }
    return len;
}

