    HBASE1_POW[0] = HBASE2_POW[0] = 1;
    for (int i = 1; i <= n; ++i) HBASE1_POW[i] = HBASE1_POW[i - 1] * HBASE1 % HMOD1;
    for (int i = 1; i <= n; ++i) HBASE2_POW[i] = HBASE2_POW[i - 1] * HBASE2 % HMOD2;

    h[0] = hash_t(0, 0);
    for (int i = 0; i < n; ++i) {
        h[i + 1] = hash_t(
            (h[i].first + HBASE1_POW[i] * s[i]) % HMOD1,
            (h[i].second + HBASE2_POW[i] * s[i]) % HMOD2
        );
    }

