vector<int> GetZ(const string& s) {
    const int n = s.length();
    vector<int> z(n);
    z[0] = 0;
    for (int i = 1, l = -1, r = -1; i < n; ++i) {
        if (i <= r) {
            z[i] = min(z[i - l], r - i + 1);
        } else {
            z[i] = 0;
        }
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            ++z[i];
        }
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    return z;
}

bool IsGoodString(const string& s) {
    const int n = s.length();
    if (n == 1) {
        return true;
    }
    vector<int> z = GetZ(s);
    for (int i = 1; i < n; ++i) {
        if (z[i] == n - i && (n % i == 0)) {
            return false;
        }
    }
    return true;
}

vector<bool> BuildGoodPrefix(const string& s) {
    const int n = s.length();
    vector<int> z = GetZ(s);
    vector<bool> result(n, true);

    for (int d = 1; d < n; ++d) {
        for (int k = 2 * d; k <= n; k += d) {
            if (z[d] >= k - d) {
                result[k - 1] = false;
            }
        }
    }

    return result;
}

