    string s;
    cin >> s;

    const int n = s.length();

    {
        bool ok = true;
        for (int i = 1; i < n; ++i) {
            if (s[i] != s[i - 1]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            cout << n << endl << 1 << endl;
            return 0;
        }
    }

    if (IsGoodString(s)) {
        cout << 1 << endl << 1 << endl;
        return 0;
    }

    string rs = s;
    reverse(rs.begin(), rs.end());

    vector<bool> goodPrefix = BuildGoodPrefix(s);

    vector<bool> goodSuffix = BuildGoodPrefix(rs);
    reverse(goodSuffix.begin(), goodSuffix.end());

    int count = 0;
    for (int i = 0; i + 1 < n; ++i) {
        if (goodPrefix[i] && goodSuffix[i + 1]) {
            ++count;
        }
    }

    if (count > 0) {
        cout << 2 << endl << count << endl;
        return 0;
    }

    assert(false);

