	for (int j = 0; j < 3; ++ j){
		for (int i = 1; i <= n; ++ i){
			pw[j][i] = pw[j][i - 1] * base % mod[j];
			inv[j][i] = inv[j][i - 1] * Inv[j] % mod[j];
			part[j][i] = (part[j][i - 1] + (s[i] - 'a') * pw[j][i] % mod[j]) % mod[j];
		}
	}
	for (int i = 1; i <= n; ++ i){
		mp[i][i] = true;
		for (int x : adj[i]){
			mp[i][x] = (mp[i - x][x] & check(i - x + 1, i, i - x - x + 1, i - x));
			flag[0][i] |= mp[i][x];
		}
	}
	if (mp[n][1]){
		cout << n << endl << 1 << endl;
		return 0;
	}
	if (!flag[0][n]){
		cout << 1 << endl << 1 << endl;
		return 0;
	}
	for (int i = 1; i <= n; ++ i) mp[i].clear();
	for (int i = n; i >= 1; -- i){
		int t = n - i + 1;
		mp[i][t] = true;
		for (int x : adj[t]){
			mp[i][x] = (mp[i + x][x] & check(i, i + x - 1, i + x, i + x + x - 1));
			flag[1][i] |= mp[i][x];
		}
	}
	cout << 2 << endl;
	for (int i = 1; i < n; ++ i) ans += (!flag[0][i] && !flag[1][i + 1]);
	cout << ans << endl;

    return 0;
}

