const int N = 500005;
string w, wRev;
long long int forwardPeriod[N];
long long int reversePeriod[N];

vector<int> buildZFunction(string s) {
	int n = s.length();
	vector<int> z(n);
	z[0] = n;
	for(int i = 1, l = 0, r = 0; i < n; i++) {
		z[i] = (i < r)? max(z[i-l], r-i):0;
		while(i + z[i] < n && s[z[i]] == s[i+z[i]]) z[i]++;
		if(i+z[i]>r) l = i, r = i+z[i];
	}
	return z;
}

int main() {
	cin >> w;
	wRev = "";
	for(int i = w.length()-1; i >= 0; i--) wRev += w[i];
	vector<int> z = buildZFunction(w);
	vector<int> zRev = buildZFunction(wRev);

	int period = 0;
	for(int i = 1; i < w.length(); i++) {
		if(i + z[i] == w.length()) {
			period = i; break;
		}
	}
	if(period == 0) period = w.length();

	if(period == 1) {
		cout << w.length() << endl << 1 << endl;
	} else if(w.length() == period || w.length() % period) {
		cout << 1 << endl << 1 << endl;
	} else {
		forwardPeriod[1] = 1;
		for(int i = 2; i < w.length(); i++) {
			for(int j = forwardPeriod[i-1]; j <= i; j++) {
				if(j + z[j] >= i) {
					forwardPeriod[i] = j; break;
				}
			}
		}

		reversePeriod[1] = 1;
		for(int i = 2; i < w.length(); i++) {
			for(int j = reversePeriod[i-1]; j <= i; j++) {
				if(j + zRev[j] >= i) {
					reversePeriod[i] = j; break;
				}
			}
		}

		int ans = 0;
		for(int i = 1; i < w.length(); i++) {
			if((i % forwardPeriod[i] != 0 || i == forwardPeriod[i]) && ((w.length()-i) % reversePeriod[w.length()-i] != 0 || w.length()-i == reversePeriod[w.length()-i])) ans++;
		}
		cout << 2 << endl << ans << endl;
	}

	return 0;
}

