vector<ll> ZAlgorithm(string s) {
  int N = s.length();
  vector<ll> result(N); result[0] = N;
  int i = 1, j = 0;
  while (i<N) {
    while (i+j<N&&s[j]==s[i+j]) j++;
    result[i] = j;
    if (j==0) { i++; continue; }
    int k = 1;
    while (k<j&&k+result[k]<j) {
      result[i+k] = result[k];
      k++;
    }
    i+=k; j-=k;
  }
  return result;
}

