std::vector<int> Make_MP_table(const std::string& key) {
	const int length = key.size();
	std::vector<int> ret(length + 1);

	ret[0] = -1;
	int matched = -1;
	for (int i = 0; i < length; ++i) {
		while (matched >= 0 && key[matched] != key[i]) {
			matched = ret[matched];
		}
		++matched;
		ret[i + 1] = matched;
	}
	return ret;
}

bool periodic(const vector<int>& arr, int i) {
  return arr[i] > 0 && i % (i - arr[i]) == 0;
}

int main() {
  cin >> s;
  const int n = s.size();
  if (count(s.begin(), s.end(), s[0]) == n) {
    cout << n << endl << 1 << endl;
  } else {
    auto arr = Make_MP_table(s);
    if (periodic(arr, n)) {
      reverse(s.begin(), s.end());
      auto rev = Make_MP_table(s);

      int cnt = n - 1;
      for (int i = 1; i < n; ++i) {
        if (periodic(arr, i) || periodic(rev, n - i)) {
          --cnt;
        }
      }
      cout << 2 << endl << cnt << endl;
    } else {
      cout << 1 << endl << 1 << endl;
    }
  }
}

