bool can(Int l,Int r){//[l,r)
  Int len = r - l;
  if(len == 1) return 1;

  auto check=[&](Int i){
    ull a = R.get(l+i, r);
    ull b = R.get(l, r - i);
    return a != b;
  };

  for(Int i:Div[len]){
    //if(len%i) continue;
    if(i!=1 && check(len/i) == false) return 0;
    if(check(i) == false) return 0;
  }
  return 1;
}

Int dfs(Int idx){
    static Int used[10000]={}, mem[10000] = {};
    if(idx == n) return 0;
    if(used[idx]++) return mem[idx];

    Int res = INF;
    for(Int nidx = idx+1; nidx <= n; nidx++){
      if(!can(idx, nidx)) continue;
      Min(res, 1+dfs(nidx));
    }
    return mem[idx] = res;
}

Int count(Int idx){
  static Int used[10000]={}, mem[10000];
  if(idx == n) return 1;
  if(used[idx]++) return mem[idx];

  Int res = 0;
  Int mn = dfs(idx);
