long long modpow(long long a, long long b, long long m) {
	if (a == 256 && b < 1000000)return power256[b];
	long long p = 1, q = a;
	for (int i = 0; i < 40; i++) { if ((b / (1LL << i)) % 2 == 1) { p *= q; p %= m; }q *= q; q %= m; }
	return p;
}
long long Div(long long a, long long b, long long m) { return (a*modpow(b, m - 2, m)) % m; }
long long Hush(long long s, long long t, long long m) { return Div((hush[t] - hush[s] + m) % m, modpow(256, s, m), m); }
vector<long long>solve(string U) {
	vector<long long>cnt;
	for (int i = 0; i <= U.size(); i++)OK[i] = true;
	long long r3 = 0, r4 = 1;
	for (int i = 1; i <= U.size(); i++) { r3 += r4*U[i - 1]; r3 %= hushmod; hush[i] = r3; r4 *= 256; r4 %= hushmod; }
	for (int i = 0; i < U.size() - 1; i++) {
		int E = i + 1; bool T = false;
		for (int j = 0; j < y[E].size(); j++) {
			long long n1 = Hush(E - y[E][j], E, mod);
			long long n2 = 0; if (E != y[E][j]) n2 = Hush(E - y[E][j] * 2, E - y[E][j], mod);
			if (E != y[E][j] && n1 != n2)OK[y[E][j]] = false;
			if (OK[y[E][j]] == true && E != y[E][j])T = true;
		}
		if (T == true)cnt.push_back(i);
	}
	return cnt;
}
