                // index of repeating string
                for(int j = s+i; j <= e; j += k){
                    if(w[j] != w[s+i]){
                        valid = false;
                        break;
                    }
                }
                if(!valid){
                    break;
                }
            }
            if(valid){
                // There is a repeating string
                //printf("Repeating length of %d exists\n", k);
                return false;
            }
        }
    }
    return true;
}

int main(){
    scanf(" %s", w);

    int N = strlen(w);
    //printf("N=%d\n", N);

    // Editorial says the length of best representation is either 1, 2 or N

    // If and only if all characters are the same, the first answer is N
    bool answerIsN = true;
    for(int i = 0; i < N; i ++){
        if(w[i] != w[0]){
            answerIsN = false;
            break;
        }
    }

    // If first answer is N, there is only 1 partition
    if(answerIsN){
        printf("%d\n1\n", N);
        return 0;
    }

    // To check if answer is 1, the whole string must be good
    bool stringIsGood = isGood(0, N-1);

    // If first answer is N, there is only 1 partition
    if(stringIsGood){
        printf("1\n1\n");
        return 0;
    }

    // Otherwise, the string is bad, with the smallest repeating length at least 2.
    // If we take the first character, and the remaining string (without the first character),
    // this forms a good representation since the existing concatenation will be destroyed.
    printf("2\n");

    // There are at most N ways to partition, hence the mod step is essentially useless.
    // One can check every single possible prefix and suffix and check whether the substring is good.
    // This yields a slightly worse than quadratic solution.

    throw;

    return 0;
}

