bool isgood(ll x, ll y) {
	ll k=y-x;
	set<ll> divs;
	ll dlim=sqrt(k)+1;
	dlim=min(dlim,k);
	for (ll d=1;d<=dlim;d++) {
		if (k%d==0) {
			divs.insert(d);divs.insert(k/d);
		}
	}
	ll actual=gethash(x,y);
	for (auto &d:divs) {
		if(d==k) continue;
		ll small=gethash(x,x+d);
		ll num=k/d;
		ll len=d;
		ll big=powup(small, num, len);
		if (big==actual) {
			return false;
		}
	}
	return true;
}
