int Z[N];
string str;
int build()
{
    int n=str.size();
    fill(Z,Z+n,0);
    int L=0,R=0;
    int i,k;
    for(i=1;i<n;i++)
    {
        if(i>R)
        {
            L=i,R=i;
            while(R<n && str[R-L]==str[R])R++;
            Z[i]=R-L,R--;
        }
        else
        {
            k=i-L;
            if(Z[k]<R-i+1)
                Z[i]=Z[k];
            else
            {
                L=i;
                while(R<n && str[R-L]==str[R])R++;
                Z[i]=R-L,R--;
            }
        }
    }
    lp(i,1,n)
    {
        if(Z[i]==n-i && (n%i)==0)
            return i;
    }
    return n;
}
