bool isGood(int s, int e){
    int M = (e-s+1);
    //printf("M=%d\n", M);
    for(int k = 1; k < M; k ++){
        bool valid = true;
        if(M%k == 0){
            // repeating string length
            for(int i = 0; i < k; i ++){
                // index of repeating string
                for(int j = s+i; j <= e; j += k){
                    if(w[j] != w[s+i]){
                        valid = false;
                        break;
                    }
                }
                if(!valid){
                    break;
                }
            }
            if(valid){
                // There is a repeating string
                //printf("Repeating length of %d exists\n", k);
                shortestRepeatingUnit = k;
                return false;
            }
        }
    }
    return true;
}

