// ローリングハッシュ
// 二分探索で LCP を求める機能つき
struct RollingHash {
    static const int base1 = 1007, base2 = 2009;
    static const int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;

    // construct
    RollingHash(const string &S) {
        int n = (int)S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for(int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    // get hash of S[left:right]
    inline pair<long long, long long> get(int l, int r) const {
        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if(res1 < 0) res1 += mod1;
        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if(res2 < 0) res2 += mod2;
        return {res1, res2};
    }

    // get lcp of S[a:] and T[b:]
    inline int getLCP(int a, int b) const {
        int len = min((int)hash1.size() - a, (int)hash1.size() - b);
        int low = 0, high = len;
        while(high - low > 1) {
            int mid = (low + high) >> 1;
            if(get(a, a + mid) != get(b, b + mid))
                high = mid;
            else
                low = mid;
        }
        return low;
    }
};

VL divisor(ll n) {
    VL res;
    for(ll i = 1; i * i <= n; i++) {
        if(n % i == 0) {
            res.push_back(i);
            if(i != n / i) res.push_back(n / i);
        }
    }
    return res;
}

signed main() {
    SCIN(S);
    ll N = S.length();
    VL divs = divisor(N);
    RollingHash rh(S);
    ll mi = LINF;
    for(auto d : divs) {
        bool ok = true;
        for(int j = 0; j + d < N; ++j) {
            if(S[j] != S[j + d]) ok = false;
        }
        if(ok) mi = min(mi, d);
    }
    if(mi == 1)
        cout << N << "\n" << 1 << "\n";
    else if(mi == N)
        cout << 1 << "\n" << 1 << "\n";
    else {
        string SS = S;
        reverse(All(SS));
        RollingHash rh2(SS);
        VB ok(N, true);
        FOR(d, 1, N) {
            if(!ok[d]) continue;
            //繰り返し判定
            for(ll cut = d; cut < N - d; cut += d) {
                if(rh.get(0, d) != rh.get(cut, cut + d)) break;
                ok[cut + d] = false;
            }
            for(ll cut = d; cut < N - d; cut += d) {
                if(rh2.get(0, d) != rh2.get(cut, cut + d)) break;
                ok[N - cut - d] = false;
            }
        }
        ll cnt = 0;
        FOR(i, 1, N) if(ok[i]) cnt++;
        printf("%lld\n%lld\n", 2, cnt);
    }
}

