void init_hash(){
	for(int t = 0; t < M; t++){
		hash[t][0] = 0;
		rep(i, n){
			hash[t][i+1] = ((hash[t][i]*base[t])+s[i])%hmod[t];
		}
		mypow[t][0] = 1;
		rep(i, n) mypow[t][i+1] = (mypow[t][i]*base[t])%hmod[t];
	}
}

bool same(int x1, int x2, int k){
	for(int t = 0; t < M; t++){
		ll r1 = ((hash[t][x1+k]-hash[t][x1]+hmod[t])%hmod[t])*mypow[t][n-x1]%hmod[t];
		ll r2 = ((hash[t][x2+k]-hash[t][x2]+hmod[t])%hmod[t])*mypow[t][n-x2]%hmod[t];
		if(r1!=r2) return false;
	}
	return true;
}

