typedef long long ll;
const ll MOD=1e9+7;
const ll base=1123;
const int MAXN=5e5+5;

string s;
int n;
ll pow[MAXN],hash[MAXN];
bool l[MAXN],r[MAXN];

void Init(){
    s=' '+s;
    n=s.length();
    pow[0]=1;
    for(int i=1;i<=n;i++) pow[i]=(1ll*pow[i-1]*base)%MOD;
    for(int i=1;i<=n;i++) hash[i]=(1ll*hash[i-1]*base+s[i]-'a')%MOD;
}

ll get(int l,int r){
    return ((1ll*hash[r]-1ll*hash[l-1]*pow[r-l+1])%MOD+MOD)%MOD;
}

int main(){
    cin >> s;
    bool same=1;
    for(int i=1;i<s.length();i++) if(s[i]!=s[i-1]){same=0;break;}
    if(same) return printf("%d\n1",s.length()),0;
    Init();
    for(int i=1;i<=n;i++)
        for(int j=i*2;j<=n;j+=i){
            if(get(1,i)==get(j-i+1,j)) l[j]=1;
            else break;
        }
    for(int i=1;i<=n;i++)
        for(int j=n-i*2+1;j>=1;j-=i){
            if(get(j,j+i-1)==get(n-i+1,n)) r[j]=1;
            else break;
        }
    if(l[n]) return printf("1\n1"),0;
    int ans=0;
    for(int i=1;i<n;i++) if(!l[i]&&!r[i+1]) ans++;
    printf("2\n%d",ans);
}

#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

typedef pair <int, int> pii;

const int MAXN = 500005;
const int MOD = 1000000007;
const int BASE = 10007;

int N;
char s[MAXN];
int hash[MAXN];
int pot[MAXN];
bool pref[MAXN], suff[MAXN];

void load() {
    scanf("%s", s + 1);
}

inline int add(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    else if (x < 0) x += MOD;
    return x;
}

inline int mul(int x, int y) {
    return (long long)x * y % MOD;
}

int get(int lo, int hi) {
    return add(hash[hi], -mul(hash[lo - 1], pot[hi - lo + 1]));
}

pii solve() {
    N = strlen(s + 1);
    pot[0] = 1;
    for (int i = 1; i <= N; i++) {
        hash[i] = add(mul(hash[i - 1], BASE), s[i]);
        pot[i] = mul(pot[i - 1], BASE);
    }

    bool f = true;
    for (int i = 1; i <= N; i++)
        f &= s[i] == s[1];
    if (f) return pii(N, 1);

    for (int i = 1; i <= N; i++) {
        int p = get(1, i), s = get(N - i + 1, N);
        bool ok_p = true, ok_s = true;
        for (int j = 2; j <= N / i; j++) {
            ok_p &= get((j - 1) * i + 1, j * i) == p;
            pref[j * i] |= ok_p;
            ok_s &= get(N - j * i + 1, N - (j - 1) * i) == s;
            suff[N - j * i + 1] |= ok_s;
        }
    }

    if (!pref[N]) return pii(1, 1);

    int cnt = 0;
    for (int i = 1; i < N; i++)
        cnt += !pref[i] && !suff[i + 1];

    return pii(2, cnt);
}

int main() {
    load();
    pii sol = solve();
    printf("%d\n%d\n", sol.first, sol.second);
    return 0;
}

