pair<int,int> solve() {
  string s;
  cin >> s;
  const int n = s.size();
  string t = s;
  reverse(ALL(t));

  vector<int> bad1(n + 1), bad2(n + 1);
  LCP lcp1(s), lcp2(t);
  for (int cycle = 1; cycle < n; ++cycle) {
    const int len = lcp1.query(0, cycle) + cycle;
    for (int j = cycle * 2; j <= len; j += cycle) bad1[j] = 1;
  }
  for (int cycle = 1; cycle < n; ++cycle) {
    const int len = lcp2.query(0, cycle) + cycle;
    for (int j = cycle * 2; j <= len; j += cycle) bad2[j] = 1;
  }
  if (!bad1[n]) return make_pair(1, 1);
  if (lcp1.query(0, 1) == n - 1) return make_pair(n, 1);
  int res = 0;
  for (int i = 1; i < n; ++i) {
    const int j = n - i;
    if (!bad1[i] && !bad2[j]) ++res;
  }
  return make_pair(2, res);
}

