template<typename T, class OpFunc>
struct Segtree{
  T ID;
  vector<T> node;
  int size;
  OpFunc op;
  void init( int n , OpFunc opfunc , T identity ){
    op = opfunc;
    ID = identity;
    size = 1;
    while( size < n ) size *= 2;
    node = vector<T>( size*2-1 , ID );
  }
  void update( int k , T x ){
    k += size-1;
    node[k] = x;
    while( k > 0 ){
      k = (k-1)/2;
      node[k] = op( node[k*2+1] , node[k*2+2] );
    }
  }
  T query( int a , int b , int k , int l , int r ){
    if( a <= l && r <= b ){
      return node[k];
    } else if( b <= l || r <= a ){
      return ID;
    } else {
      T chl = query( a , b , k*2+1 , l , (l+r)/2 );
      T chr = query( a , b , k*2+2 , (l+r)/2 , r );
      return op( chl , chr );
    }
  }
  T query( int a , int b ){
    return query( a , b , 0 , 0 , size );
  }
  T get( int a ){
    return node[a+size-1];
  }
};

struct RangeLCP{
  SA sa;
  LCP lcp;
  Segtree<int,MinOp<int> > seg;
  void init( string s ){
    sa.init( s );
    lcp.init( s , sa );
    seg.init( SZ(s) , MinOp<int>() , INF );
    REP( i , SZ(s) ){
      seg.update( i , lcp[i] );
    }
  }
  int sa_query( int l , int r ){
    return seg.query( l , r );
  }
  int pos_query( int l , int r ){
    int a = sa.rank[l];
    int b = sa.rank[r];
    if( a > b ){
      swap( a , b );
    }
    return seg.query( a , b );
  }
};

