pii isgood(string W) {
    int N = W.size();
    if (N == 1) return {1,1};

    bool diff = false;
    for (int i = 1; i < N && !diff; i++) {
        diff |= (W[0] != W[i]); 
    }
    if (!diff) return {N,1};

    for (int i = 2; i < N; i++) {
        if (N % i != 0) continue;
        bool diff = false;
        for (int j = i; j < N && !diff; j+=i) {
            for (int k = 0; k < i && !diff; k++) {
                diff |= W[k] != W[j+k];
