int main() {
	cin >> s;
	int n = s.length();
	int k = sqrt(n + 0.1);
	rep1(i, k) {
		if (n%i != 0)continue;
		d.push_back(i);
		d.push_back(n / i);
	}
	sort(d.begin(), d.end());
	int len = unique(d.begin(), d.end()) - d.begin();
	int m = n;
	rep(i, len) {
		int l = d[i];
		int r = n / l;
		bool valid = true;
		rep(j, r - 1) {
			string le = s.substr(j*l, l);
			string ri = s.substr((j + 1)*l, l);
			if (le != ri) {
				valid = false; break;
			}
		}
		if (valid) {
			m = l; break;
		}
	}
	if (m == 1) {
		cout << n << endl << 1 << endl;
	}
	else if (m == n) {
		cout << 1 << endl << 1 << endl;
	}
	else {
		for (int i = 2 * m; i <= n; i += m) {
			leok[i] = false;
		}
		for (int i = n - 2 * m; i >= 0; i -= m) {
			riok[i] = false;
		}
		fill(leok, leok + n + 1, true);
		fill(riok, riok + n + 1, true);
		rep1(i, n) {
			if (!leok[i])continue;
			else {
				int le = 0, ri = i;
				while (ri+i <= n) {
					bool valid = true;
					rep(j, i) {
						if (s[le+j] != s[ri+j]) {
							valid = false; break;
						}
					}
					if (valid) {
						ri += i; le += i;
						leok[ri] = false;
					}
					else break;
				}
			}
		}
		rep1(i, n) {
			if (!leok[n-i])continue;
			if (!riok[i])continue;
			else {
				int le = n - i, ri = n;
				while (le - i >= 0) {
					bool valid = true;
					rep(j, i) {
						if (s[le + j] != s[le + j - i]) {
							valid = false; break;
						}
					}
					if (valid) {
						le -= i; ri -= i;
						riok[le] = false;
					}
					else break;
				}
			}
		}
		int cnt = 0;
		rep1(i, n) {
			if (leok[i] && riok[i])cnt++;
		}
		cout << 2 << endl;
		cout << cnt << endl;
	}
	//stop
