/**
 * Z algorithmによりZ Arrayを構築する
 * O(N)
 * S[0..]とS[i..]の共通接頭辞数
 * ex) aaabaaaab -> [9, 2, 1, 0, 3, 4, 2, 1, 0]
 */
class ZAlgorithm {
	const std::vector<int> m_zArray;

	static auto constrcutZArray(const std::string& str) {
		auto sz = str.size();
		auto zArray = std::vector<int>(sz);
		zArray[0] = sz;

		int i = 1, j = 0;
		while (i < sz) {
			while (i + j < sz && str[j] == str[i + j]) ++j;
			zArray[i] = j;
			if (j == 0) { ++i; continue; }
			int k = 1;
			while (i + k < sz && k + zArray[k] < j) {
				zArray[i + k] = zArray[k];
				++k;
			}
			i += k; j -= k;
		}
		return zArray;
	}
public:
	ZAlgorithm(const std::string& str) :m_zArray(constrcutZArray(str)) {}

	auto getZArray() const {
		return m_zArray;
	}

	/* output fot debug */
	void debugOutput() const {
		dump(m_zArray);
	}
};

signed main() {
	string str;
	cin >> str;

	ll sz = str.size();
	{
		char c0 = str[0];
		bool flg = true;
		REPC(c, str) {
			if (c != c0) { flg = false; break; }
		}
		if (flg) {
			cout << sz << endl << 1 << endl;
			return 0;
		}
	}

	auto z = ZAlgorithm(str).getZArray();

	ll tsz = sz;
	FOR(i, 1, sz) {
		if (i + z[i] == sz && z[i] % i == 0) { tsz = i; break; }
	}

	if (tsz == sz) {
		cout << 1 << endl << 1 << endl;
		return 0;
	}

	V<bool> lok(sz, true);
	{
		V<bool> use(sz);
		FOR(i, 1, sz) {
			if (use[i]) { continue; }
			for (int j = 1; i * j <= z[i]; ++j) {
				lok[i + i * j - 1] = false;
				use[i * j] = true;
			}
		}
	}
	V<bool> rok(sz, true);
	{
		auto s_ = str;
		std::reverse(ALL(s_));
		auto z = ZAlgorithm(s_).getZArray();

		V<bool> use(sz);
		FOR(i, 1, sz) {
			if (use[i]) { continue; }
			for (int j = 1; i * j <= z[i]; ++j) {
				rok[i + i * j - 1] = false;
				use[i * j] = true;
			}
		}
	}

	ll ans = 0;
	// s[:i-1] s[i:]
	FOR(i, 1, sz) {
		if (lok[i - 1] && rok[sz - i - 1]) { ++ans; }
	}
	cout << 2 << endl << ans << endl;
}

