int mod_inv(ll x, int M) {
	int t = M - 2, y = 1;
	for (; t; t>>=1) {
		if (t & 1) y = y * x % M;
		x = x * x % M;
	}
	return y;
}

struct rolling_hash {
	int M;
	vector<int> a, b;
	rolling_hash(string s, int _M) {
		M = _M;
		int N = s.length();
		a.resize(N + 1);
		ll x = 1;
		for (int i = 0; i < N; i++) {
			a[i + 1] = (a[i] + x * s[i]) % M;
			x = x * 256 % M;
		}
		ll inv = mod_inv(256, M);
		b.resize(N + 1);
		b[0] = 1;
		for (int i = 0; i < N; i++)
			b[i + 1] = b[i] * inv % M;
	}
	int get(int l, int r) {
		return ((ll)(a[r] - a[l]) * b[l] % M + M) % M;
	}
};

int p[500001], nxt[500001];

bool good(int l, int r, rolling_hash& a, rolling_hash& b) {
	int d = r - l;
	if (d == 1) return true;
	vector<int> ps;
	for (;;) {
		if (p[d]) ps.push_back(p[d]);
		else if (d > 1) ps.push_back(d);
		d = nxt[d];
		if (!d) break;
	}
	for (int p: ps) {
		int x = (r - l) / p;
		if (a.get(l, r - x) == a.get(l + x, r) && b.get(l, r - x) == b.get(l + x, r))
			return false;
		d = nxt[d];
	}
	return true;
}

