    int N = S.length(); vector<int> res(N);
    res[0] = N;
    int i = 1, j = 0;
    while (i < N) {
        while (i + j < N and S[j] == S[i + j]) j++;
        res[i] = j;
        if (j == 0) { i++; continue; }
        int k = 1;
        while (i + k < N and k + res[k] < j) res[i + k] = res[k], k++;
