string S;
int N;
vector<int> z1, z2;
//---------------------------------------------------------------------------------------------------
bool isGood(int n, vector<int>& z) {
    auto ed = enumdiv(n);

    fore(d, ed) if(d != 1) {
        int len = n / d;
        int cnt = 0;
        rep(i, 0, d) if (len <= z[i*len]) cnt++;
        if (cnt == d) return false;
    }

    return true;
}
//---------------------------------------------------------------------------------------------------
void _main() {
    cin >> S; N = S.length();

    z1 = Zalgorithm(S);
    reverse(all(S));
    z2 = Zalgorithm(S);

    if (isGood(N, z1)) {
        printf("1\n1\n");
        return;
    }

    set<char> s;
    fore(c, S) s.insert(c);
    if (s.size() == 1) {
        printf("%d\n1\n", N);
        return;
    }


    int ans = 0;
    rep(i, 1, N) {
        if (isGood(i, z1) and isGood(N-i, z2)) ans++;
    }

    printf("2\n%d\n", ans);
}

