const int MOD = 1e9 + 7;
ll add(ll a, ll b)
{
	a+=b;
	while(a>=MOD) a-=MOD;
	return a;
}

ll mult(ll a, ll b)
{
	return (a*b)%MOD;
}

ll dp[500011];
ll powr[500011];
ll ipowr[500011];
const int C = 2017;

ll modpow(ll a, ll b)
{
	ll r=1;
	while(b)
	{
		if(b&1) r=mult(r,a);
		a=mult(a,a);
		b>>=1;
	}
	return r;
}

ll hsh(int l, int r)
{
	if(l>r) return 0;
	if(l==0) return dp[r];
	return mult(ipowr[l],add(dp[r],MOD-dp[l-1]));
}

