vector<int> MP (string S) {
  vector<int> A(S.size() + 1);
  A[0] = -1;
  int j = -1;
  for(int i=0; i < (int) S.size() ; i++) {
    while (j >= 0 && S[i] != S[j]) j = A[j];
    j++;
    A[i+1] = j;
  }
  return A;
}

// shortest cycle length
vector<int> cycle(string S) {
  auto mp = MP(S);
  vector<int> A(S.size());
  for(int i = 0; i < (int) S.size() ; i++) {
    A[i] = i + 1 - mp[i + 1];
  }
  return A;
}

