vector<ll> z_algo(vector<ll> S) {//0-index
	ll N = S.size();

	vector<ll> A(N, 0);


	ll c = 0;
	repn(i, N-1) {
		if (c>0&&i - c + A[i - c] < A[c]) { A[i] = A[i - c]; }
		else {
			ll j = max(0, c + A[c] - i);
			while (i + j < N && S[j] == S[i + j]) { j++; }
			A[i] = j;
			c = i;
		}
	}

	A[0] = N;

	return A;
}

vector<bool> notgood(vector<ll> a) {
	ll N = a.size();
	vector<ll> Z = z_algo(a);
	vector<bool> ret(N+1, 0);

	//rep(i, N) cout << Z[i] <<" ";
	//cout << endl;

	ll d = 1;
	while (d < N) {
		if (Z[d] < d) { d++; continue; }
		for (ll i = 2 * d; i <= N; i += d) {
			if (Z[i - d] < d) {
				ll x = i - d;
				d = x / 2 + 1;
			}
			ret[i] = 1;

			if (i + d > N) { d++; break; }
		}
	}

	return ret;

}


