vll eratosthenes_minprime(ll n_){ //エラトステネスの篩、最小素因数版
    int n=(int)n_;
    vll mnpr(n+1); //mnpr[i]:iの最小素因数 i<=1は0

    for (int i=2; i<=n; i++){
        if (mnpr[i]) continue;

        for (int j=i; j<=n; j+=i){
            if (mnpr[j]==0) mnpr[j]=i;
        }
    }
    return mnpr;
}

void PrimeFactorization5(ll a_, vll &mnpr, vpll &out){
    if (a_<=1)return;
    int a=(int)a_;
    while (true){
        int mnp=(int)mnpr[a];
        if (!out.empty() and out.back().first==mnp) out.back().second++;
        else out.emplace_back(mnp, 1);
        if (mnp==a) return;
        a/=mnp;
    }
}


void solve()
{
    string w;  cin >> w;
    ll n=sz(w);

    {
        bool isall=true;
        each(e,w) if (!(e==w[0])) isall=false;
        if (isall){
            cout << n << '\n';
            cout << 1 << '\n'; return;
        }
    }

    string v=w;
    reverse(ALL(v));

    auto zary=z_algorithm(w);
    auto zarr=z_algorithm(v);

    ll nn=n/2;
    vll cr(n/2+1);
    rep(k,1,nn){
        rep(j,1,INF){
            if (k*j>=n or zary[k*j]<k){
                cr[k]=j;
                break;
            }
        }
    }
    vll rr(n/2+1);
    rep(k,1,nn){
        rep(j,1,INF){
            if (k*j>=n or zarr[k*j]<k){
                rr[k]=j;
                break;
            }
        }
    }

    vll mnpr = eratosthenes_minprime(n);
    vpll prs;
    auto zen=[&](ll m){
        prs.clear();
        PrimeFactorization5(m, mnpr, prs);
        each(e,prs){
            ll p=e.first;
            ll q=m/p;
            if (cr[q]>=p) return true;
        }
        return false;
    };
    auto kou=[&](ll m){
        prs.clear();
        PrimeFactorization5(m, mnpr, prs);
        each(e,prs){
            ll p=e.first;
            ll q=m/p;
            if (rr[q]>=p) return true;
        }
        return false;
    };

    if (!zen(n)){
        cout << 1 << '\n';
        cout << 1 << '\n';return;
    }

    ll ans=0;
    rep(i,1,n-1){
        if (zen(i))continue;
        if (kou(n-i))continue;
        ans++;
    }
    cout << 2 << '\n';
    cout << ans << '\n';
}


