{
	LL cmp;
	for(int i=2*x;i<=n;i+=x)
		if((hash[i-x]*Pow[x]+hash[x])%MO==hash[i])
			vis[i]=1;
		else
		{
			cmp=(hash[n]-hash[n-x]*Pow[x]%MO+MO)%MO;
			for(int j=n-x*2;j>0;j-=x)
				if((hash[j]*Pow[x]+cmp)%MO==hash[j+x])
					vis[j]=1;
