			}
		}
	}

	inline ll hash(int l, int r, int i) {
		return (hs[i][r] - hs[i][l] * pw[i][r - l] % mod[i] + mod[i]) % mod[i];
	}

	inline bool match(int l1, int r1, int l2, int r2) {
		bool res = true;
		REP(i, mod.size()) if (hash(l1, r1, i) != hash(l2, r2, i)) res = false;
		return res;
	}
};

string w;
bool cut[512345] = {}; // 0:ok, 1:no
bool rcut[512345] = {};

int main() {
	cin >> w;
	RollingHash rh(w);

	int l = w.size();

	bool ok = true;

	FOR(i, 1, l / 2 + 1) {
		bool f = true;
		// head
		for (int j = i + i; j <= l; j += i) {
			if (!rh.match(0, i, j - i, j)) { f = false; break; }
			cut[j] = true;
		}
		if (l % i == 0 && f) ok = false;

		// back
		for (int j = l - i - i; j >= 0; j -= i) {
			if (!rh.match(l - i, l, j, j + i)) break;
			rcut[j] = true;
		}
	}

	int cnt = 0;
	FOR(i, 1, l) if (!cut[i] && !rcut[i]) cnt++;

	//if (debug) cout << "cnt : " << cnt << endl;

	bool same = true;
	FOR(i, 1, l) if (w[i - 1] != w[i]) same = false;

	int a, b;
	if (same) a = l, b = 1;
	else if (ok) a = 1, b = 1;
	else a = 2, b = cnt;

	printf("%d\n%d\n", a, b);

	return 0;
}

