void calc(int * z, int * c)
{
	for(int i = 2, l = 1, r = 1; i <= n; ++i)
	{
		if(i <= r) z[i] = min(r - i + 1, z[i - l + 1]);
		while(i + z[i] <= n && s[z[i] + 1] == s[i + z[i]]) ++z[i];
		if(i > r) l = i, r = i + z[i] - 1;
	}
	for(int i = 2; i <= n; ++i) 
		if(z[i] > 0 && !c[i + z[i] - 1] && z[i] % (i - 1) == 0)
			c[i + z[i] - 1] = i - 1;
	for(int i = 1; i <= n; ++i)
		if(!c[i])
			c[i] = i;
}
