void kmp_init(int kmp0[]){//对a跑KMP算法 
	for(int i=2;i<=n;i++){
		int now=kmp0[i-1];
		while(now&&a[now+1]!=a[i])now=kmp0[now];
		kmp0[i]=a[now+1]==a[i]?now+1:0;
	}
}
