	kmp_init(kmp);
	reverse(a+1,a+n+1);//令a=a^r以算kmp_r 
	kmp_init(kmp_r);
	if(!kmp[n]||n%(n-kmp[n]))return puts("1\n1"),0;//特判不循环 
	puts("2");//一定有分成2段的方式 
	int ans=0;
	for(int i=1;i<n;i++)ans+=(!kmp[i]||i%(i-kmp[i]))&&(!kmp_r[n-i]||(n-i)%(n-i-kmp_r[n-i]));//如果都不循环，答案+1
	cout<<ans;
