void kmp(int *Next)
{
    for (int i = 2, j = 0; i <= len; i ++ )
    {
        while(j && s[j + 1] != s[i]) j = Next[j];
        if(s[j + 1] == s[i]) j ++;
        Next[i] = j;
    }
}

