vector<int> z_algorithm(const string &s) {
    int n = s.size();
    vector<int> lcp(n);
    lcp[0] = n;
    int i = 1, j = 0;
    while (i < n) {
        while (i + j < n && s[j] == s[i + j]) j++;
        lcp[i] = j;
        if (j == 0) { i++; continue; }
        int k = 1;
        while (i + k < n && k + lcp[k] < j) lcp[i + k] = lcp[k], k++;
        i += k, j -= k;
    }
    return lcp;     // longest common prefix of s and s[i:n]
}

vector<vector<int>> divisors_table(int n) {     // 自分自身を含まない
    vector<vector<int>> divisors(n + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = i + i; j <= n; j += i) divisors[j].emplace_back(i);;
    }
    return divisors;
}

int main() {
    string s; cin >> s;
    int n = s.length();
    if (s == string(n, s[0])) return !(cout << n << endl << 1 << endl);
    string s_r = s;
    reverse(begin(s_r), end(s_r));
    vector<int> lcp = z_algorithm(s), lcp_r = z_algorithm(s_r);
    auto ds = divisors_table(n);
    auto check = [&](int len) {
        for (int d: ds[len]) if (lcp[d] >= len - d) return false;
        len = n - len;
        for (int d: ds[len]) if (lcp_r[d] >= len - d) return false;
        return true;
    };
    if (check(n)) return !(cout << 1 << endl << 1 << endl);
    int cnt = 0;
    for (int i = 1; i < n; i++) cnt += check(i);
    cout << 2 << endl << cnt << endl;
    return 0;
}

