#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

typedef pair <int, int> pii;

const int MAXN = 500005;
const int MOD = 1000000007;
const int BASE = 10007;

int N;
char s[MAXN];
int hsh[MAXN];
int pot[MAXN];
bool pref[MAXN], suff[MAXN];

void load() {
    scanf("%s", s + 1);
}

inline int add(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    else if (x < 0) x += MOD;
    return x;
}

inline int mul(int x, int y) {
    return (long long)x * y % MOD;
}

int get(int lo, int hi) {
    return add(hsh[hi], -mul(hsh[lo - 1], pot[hi - lo + 1]));
}

pii solve() {
    N = strlen(s + 1);
    pot[0] = 1;
    for (int i = 1; i <= N; i++) {
        hsh[i] = add(mul(hsh[i - 1], BASE), s[i]);
        pot[i] = mul(pot[i - 1], BASE);
    }

    bool f = true;
    for (int i = 1; i <= N; i++)
        f &= s[i] == s[1];
    if (f) return pii(N, 1);

    for (int i = 1; i <= N; i++) {
        int p = get(1, i), s = get(N - i + 1, N);
        bool ok_p = true, ok_s = true;
        for (int j = 2; j <= N / i; j++) {
            ok_p &= get((j - 1) * i + 1, j * i) == p;
            pref[j * i] |= ok_p;
            ok_s &= get(N - j * i + 1, N - (j - 1) * i) == s;
            suff[N - j * i + 1] |= ok_s;
        }
    }

    if (!pref[N]) return pii(1, 1);

    int cnt = 0;
    for (int i = 1; i < N; i++)
        cnt += !pref[i] && !suff[i + 1];

    return pii(2, cnt);
}

int main() {
    load();
    pii sol = solve();
    printf("%d\n%d\n", sol.first, sol.second);
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int maxw = 500000;

template <class T, class U = int>
struct KnuthMorrisPratt {
	static const int maxn = 1000;

	int n;
	T p[maxn];
	U f[maxn + 1];

	KnuthMorrisPratt() : n(0) {

	}

	U & operator [] (const int & x) {
		return f[x];
	}

	void build(const T * first, const T * last) {
		const T * & p = first;
		n = last - first;
		memcpy(this->p, p, sizeof p[0] * n);
		f[0] = f[1] = 0;
		for (int i = 1, k; i < n; i++) {
			for (k = f[i]; k > 0 && p[k] != p[i]; k = f[k]);
			if (p[k] == p[i])
				k++;	
			f[i + 1] = k;
		}
	}
};

char w[maxw + 1];
KnuthMorrisPratt<char> KMP;

pair<int, int> answer() {
	int n = strlen(w);
	KMP.build(w, w + n);

	int l = n - KMP[n];
	if (n % l > 0 || n == l)
		return make_pair(1, 1);
	else if (l > 1) {
		int ans = n / l * (l - 1);
		if (n == l * 2) {
			int r = l - KMP[l];
			if (l % r > 0 || l == r)
				ans++;
		}
		return make_pair(2, ans);
	} else
		return make_pair(n, 1);
}

