		int t;
		if (L*2 == n) t = n-1; else t = n/L*(L-1);
		REP(i,L-1) { 
			if (nxt[i] > 0 && i%(i-nxt[i]) == 0) --t;
			if (nxt2[i] > 0 && i%(i-nxt2[i]) == 0) --t;
		}
		printf("%d\n%d\n", 2, t);
	}
	return 0;
}

