ll comb(int x, int y) {
	if (x < 0 || y < 0 || x < y)
		return 0;
	return fact[x]*invfact[y]%p*invfact[x-y]%p;
}

ll exp(ll x, ll k) {
	if (k == 0)
		return 1;
	ll y = exp(x, k/2);
	return (k%2 == 0) ? y*y%p : y*y%p*x%p;
}

ll inve(ll x) { return exp(x, p-2); }

ll get(int l, int r) {
    // cout << l << ' ' << r << ' ' << h[l] << ' ' << h[r+1] << ' ' << pinv[l] << endl;
    return ((h[r+1]-h[l] + p)*pinv[l])%p;
}

ll inithash(string s) {
    pinv[0] = px[0] = 1; 

    for (int i = 1; i <= n; ++i) {
        pinv[i] = inv*pinv[i-1]%p;
        px[i] = x*px[i-1]%p;
    }

    h[0] = 0;

    for (int i = 0; i < n; ++i)
        h[i+1] = (px[i]*(s[i] + 1) + h[i])%p;
}

void init() {
	inv1[1] = fact[0] = fact[1] = invfact[0] = invfact[1] = 1;
	for (int i = 2; i < MAXN; ++i) {
		inv1[i] = (p - (p/i) * inv1[p%i] % p) % p;
		fact[i] = i*fact[i-1]%p;
		invfact[i] = inv1[i]*invfact[i-1]%p;
	}
}

bool period(int l, int r) {
	for (int x : f[r-l+1]) {
		if (get(l, r - (r-l+1)/x) == get(l+(r-l+1)/x, r))
			return false;
	}

	return true;
}

