int mat[4010][4010];
void comp(string &S, int s){
	int i = 0, j = -1;
	vector<int> T(S.size()+1);
	T[0] = -1;
	while(i+s < S.size()){
		while(j >= 0 && S[i+s] != S[j+s]){
			j = T[j];
		}
		i++;j++;
		T[i] = j;
		int ss = i;
		int p = ss - j;
		if(p > 0 && p != ss && ss % p == 0){
			mat[s][s+i-1] = p;
		}else{
			mat[s][s+i-1] = -1;
		}
	}
}
pair<int,int> mem[4010];
pair<int,int> dp(int i){
	if(i < 0)return make_pair(0,1);
	int w = 1000000;
	if(mem[i].first != -1)return mem[i];
	int c = 0;
	for(int j = 0; j <= i; ++j){
		if(mat[j][i] == -1){
			pair<int,int> t = dp(j-1);
			if(t.first+1 < w){
				w = t.first+1;
				c = t.second;
			}else if(t.first+1 == w){
				c += t.second;
				c %= 1000000007;
			}
		}
	}
	return mem[i] = make_pair(w,c);
}

