using namespace std;

namespace XX
{
    template<typename RandIt>
    class KMPBody
    {        
        public:

            struct Iter
            {
                int idxP, idxT;
                int matchIdx;
                Iter(int p, int t, const KMPBody& b)
                    :idxP(p), idxT(t), body(b)
                {}

                int operator*(){return matchIdx;}
                bool operator!=(const Iter& other){return idxP != other.idxP || idxT != other.idxT;}
                Iter& operator++()
                {
                    while(true)
                    {
                        if(idxP == body._plen)
                        {
                            matchIdx = idxT - body._plen;
                            idxP = body._fail[idxP - 1] + 1;
                            break;
                        }
                        else if(idxT == body._tlen)
                        {
                            idxP = idxT = matchIdx = -1;
                            break;
                        }
                        else if(body._pbegin[idxP] == body._tbegin[idxT])
                        {
                            idxP++;
                            idxT++;
                        }
                        else if(!idxP)
                            idxT++;
                        else
                            idxP = body._fail[idxP - 1] + 1;
                    }
                    return *this;
                }


                const KMPBody& body;
            };



            Iter begin()const {return ++Iter(0, 0, *this);}
            Iter end()const {return Iter(-1, -1, *this);}

            KMPBody(RandIt pbegin, int plen, RandIt tbegin, int tlen) 
                :_pbegin(pbegin), _plen(plen), _tbegin(tbegin), _tlen(tlen), _fail(plen)
            {
                if(!plen)
                    return;

                _fail[0] = -1;
                for(int idx = 1; idx < _plen; ++idx)
                {
                    int last = _fail[idx - 1];
                    while(last > -1 && _pbegin[last + 1] != _pbegin[idx])
                        last = _fail[last];

                    if(_pbegin[last + 1] == _pbegin[idx])
                        _fail[idx] = last + 1;
                    else
                        _fail[idx] = -1;
                }
            }

        private:
            std::vector<int> _fail;
            RandIt _pbegin, _tbegin;
            int _plen, _tlen;
    };


    //Pattern, Text
    template<typename RandIt>
    KMPBody<RandIt> KMP(RandIt pbegin, int plen, RandIt tbegin, int tlen) 
    {
        return KMPBody<RandIt>(pbegin, plen, tbegin, tlen);
    }
}





