	int cut[512345] = {}; // 0:ok, 1:ok, 2:no

	FOR(i, 1, w.size() / 2 + 1) if (w.size() % i == 0) {
		bool f = true;
		for (int j = i; j < w.size(); j += i) {
			if (!rh.match(0, i, j, j + i)) f = false;
		}
		if (f) {
			bool p = (w.size() - 1) / i >= 2;

			for (int j = i; j < w.size(); j += i) {
				if (p) cut[j] = 2;
				else chmax(cut[j], 1);
			}
		}
	}

	int cnt = 0;
	bool ng = true;
	FOR(i, 1, w.size()) {
		if (cut[i] <= 1) cnt++;
		if (cut[i] >= 1) ng = false;
	}

	int a, b;
