    vi ret(n, 0);
    for (int j = 1; j < n; ++j) {
        for (int i = j; i + j - 1 < n; i += j) {
            if (get_hash(0, j - 1) == get_hash(i, i + j - 1) &&
                s.substr(0, j - 1) == s.substr(i, i + j - 1)) {
                ret[i + j - 1] = true;
            } else {
