	int ans = N;
	static bool G[MAX];
	for (int i = 0;i <= N;i ++) G[i] = true;
	for (int p = 1;p < N;p ++) {
		if (!G[p - 1]) continue;
		for (int k = 2;(k - 1) * p <= z1.get(p) && k * p <= N;k ++) {
			if (G[k * p - 1]) -- ans;
			G[k * p - 1] = false;
		}
		for (int k = 2;(k - 1) * p <= z2.get(p) && N - k * p > 0;k ++) {
			if (G[N - k * p]) -- ans;
			G[N - k * p] = false;
		}
	}

	if (G[N - 1]) cout << 1 << endl << 1;
	else if (ans <= 1) cout << N << endl << 1;
	else cout << 2 << endl << ans;

