template<uint mod>
class rolling_hash
{
public:
    template<typename InIt>
    rolling_hash(const InIt first, const InIt last) : sz(std::distance(first, last)), pow(sz + 1, 1), h(sz + 1, 0)
    {
        const ull base = g_rng_xo64(static_cast<uint>(2), mod - 1);
        for (usize i = 1; i <= sz; i++) { pow[i] = pow[i - 1] * base, h[i] = h[i - 1] * base + *std::next(first, i - 1); }
    }
    modint<mod> operator()(const usize l, const usize r) const { return h[r] - h[l] * pow[r - l]; }

private:
    const usize sz;
    std::vector<modint<mod>> pow, h;
};
int main()
{
    const auto w = read<std::string>();
    rolling_hash<1000000007> hash(w.begin(), w.end());
    const usize n = w.size();
    if (w == std::string(n, w.front())) {
        std::cout << n << "\n"
                  << 1 << std::endl;
        return 0;
    }
    std::vector<std::vector<usize>> divs(n + 1);
    for (usize i = 1; i <= n; i++) {
        for (usize j = i; j <= n; j += i) { divs[j].push_back(i); }
    }
    for (usize i = 1; i <= n; i++) { std::reverse(divs[i].begin(), divs[i].end()); }
    auto periodic = [&](const usize i, const usize j) {
        for (const usize d : divs[j - i]) {
            if (d == j - i) { continue; }
            if (hash(i, j - d) == hash(i + d, j)) { return true; }
        }
        return false;
    };
    if (not periodic(0, n)) {
        std::cout << "1\n1" << std::endl;
        return 0;
    }
    usize cnt = 0;
    for (usize i = 1; i < n; i++) {
        if (not periodic(0, i) and not periodic(i, n)) { cnt++; }
    }
    std::cout << 2 << "\n"
              << cnt << std::endl;
    return 0;
}

