  bs[ 0 ] = 1;
  for( int i = 1 ; i < N ; i ++ )
    bs[ i ] = mul( bs[ i - 1 ] , BS );
  for( int j = 1 ; j < N ; j ++ )
    for( int i = j + 1 ; i < N ; i ++ )
      if( i % j == 0 )
        divv[ i - j ].push_back( j );
