  for( int i = 1 ; i <= n ; i ++ )
    hs[ i ] = add( mul( hs[ i - 1 ] , BS ) , c[ i ] );
}
inline int hs_vl( int l , int r ){
  return sub( hs[ r ] , mul( hs[ l - 1 ] , bs[ r - l + 1 ] ) );
}
