vector<int> make_primes(int MAX_NUM){
	vector<bool> flag(MAX_NUM+1, true);
	vector<int> res;
	for(int i=2;i<=MAX_NUM;++i){
		if(flag[i]){
			res.push_back(i);
			for(int j=i*2;j<=MAX_NUM;j+=i){
				flag[j] = false;
			}
		}
	}
	return res;
}

bool check(string str){
	int n = str.size();
	for(int i=2;i<n;++i){
		if(n%i!=0)continue;
		int d = n / i;
		bool flag = true;
		for(int j=d;j<n;j+=d){
			if(str.substr(0, d)!=str.substr(j, d)){
				flag = false;
				break;
			}
		}
		if(flag)return true;
	}
	return false;
}

