const int MAXN = 4005;
const int MOD = 1000000007;
int f[MAXN], len[MAXN], dp[MAXN];
int main()
{
	string x;
	cin>>x;
	int n = x.length();
	assert(n < MAXN);
	len[n] = 0;
	dp[n] = 1;
	for (int i = n-1; i >= 0; --i)
	{
		memset(f, 0, sizeof f);
		string temp = x.substr(i);
		f[0] = 0;
		for (int j = 1; j < temp.length(); ++j)
		{
			int cpos = j-1;
			while(cpos >= 0)
			{
				if(temp[j] == temp[f[cpos]])
				{
					f[j] = f[cpos]+1;
					break;
				}
				else
					cpos = f[cpos] - 1;
			}
			if(cpos < 0)
				f[j] = 0;
		}
		len[i] = len[i+1] + 1;
		dp[i] = dp[i+1];
		// cout<<i<<": "<<len[i]<<" "<<dp[i]<<"\n";
		for (int j = 1; j < temp.length(); ++j)
		{
			int period = (j + 1 - f[j]);
			if((j+1)%period == 0 && period < (j+1))
				continue;
			// cout<<period<<" "<<j<<"\n";
			if(1 + len[i+j+1] < len[i])
			{
				len[i] = 1 + len[i+j+1];
				dp[i] = 0;
			}
			if(len[i] == 1 + len[i+j+1])
				dp[i] = (dp[i] + dp[i+j+1])%MOD;
		}
		// cout<<i<<": "<<len[i]<<" "<<dp[i]<<"\n";
	}
	cout<<len[0]<<"\n"<<dp[0]<<"\n";
	return 0;
}

