std::vector<int> z_array(const std::string &str) {
  int len = str.length();
  std::vector<int> z(len);
  z[0] = len;
  for (int i = 1, left = 0, right = 0; i < len; ++i){
    if (i > right) {
      left = right = i;
      for(; right < len && str[right - left] == str[right]; ++right) {}
      z[i] = right - left;
      right--;
    }
    else{
      int k = i - left;
      if(z[k] < right - i + 1){
	z[i] = z[k];
      }
      else{
	left = i;
	for(;right < len && str[right - left] == str[right]; right++);
	z[i] = right - left;
	right--;
      }
    }
  }
  return z;
}

