std::vector<int> kmp(int n, char *s) {
  std::vector<int> fail(n, -1);
  for (int i = 1, j = -1; i < n; ++i) {
    while (j >= 0 && s[j + 1] != s[i]) j = fail[j];
    fail[i] = s[j + 1] == s[i] ? ++j : j;
  }
  return fail;
}

