int M, x;
const int N = 7e5 + 10;
int pwx[N];

bool is_prime(int x) {
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0)
            return false;
    }
    return true;
}

void hash_init() {
    for(M = 1e9 + rng() % int(1e9); !is_prime(M); ++M);
    for(x = 130 + rng() % int(10); !is_prime(x); ++x);
    pwx[0] = 1;
    for (int i = 1; i < N; ++i) {
        pwx[i] = (ll) x * pwx[i - 1] % M;
    }
}


int hs[N];

void insum(int &a, int b) {
    a = (a + b) % M;
}

int get_hash(int l, int r) {
    if (!l)
        return hs[r];
    --l;
    return (hs[r] - (ll)hs[l] * pwx[r - l] % M + M) % M;
}

vi solve(string s) {
    int n = s.size();
    fori (i, n) {
        hs[i] = s[i];
        if (i) {
