        hs.push_back(s[i] - 'a');
        rhs.push_back(rev[i] - 'a');
      }
      for (int i = 1; i < n; ++i) {
        auto hash0i = hs.get(0, i);
        for (int j = i * 2; j < n; j += i) {
          if (hs.get(j - i, j) != hash0i) break;
          isGood[j] = 0;
        }
      }
      for (int i = 1; i < n; ++i) {
        auto hash0i = rhs.get(0, i);
        for (int j = i * 2; j < n; j += i) {
          if (rhs.get(j - i, j) != hash0i) break;
          isGood[n - j] = 0;
        }
      }
      cout << accumulate(isGood.begin() + 1, isGood.end(), 0) << endl;
    }
  }
};
