struct string_hasher {
  const ll mod = 1e9 + 7;
  const ll prime = 2641;
  string s; int n;
  vector<ll> H, P;
  string_hasher() {}
  void init(string s) {
    this->s = s;
    assert(s.front() == '*'); // string must be given as 1-indexed!!
    this->n = s.length(); this->n--;

    H.resize(n+10);
    P.resize(n+10);
    P[0] = 1;
    for (int i=1; i<=n; i++) {
      P[i] = prime*P[i-1];
      P[i] %= mod;
    }

    for (int i=1; i<=n; i++) {
      H[i] = H[i-1]*prime + (s[i]-'a'+1);
      H[i] %= mod;
    }
  }

  ll get(int l, int r) {
    assert(l>=1 && r>=1 && l<=n && r<=n);
    return ((H[r] - H[l-1]*P[r-l+1]) + mod) % mod;
  }

  // Check if s[l1..r1] == s[l2...r2]. Assumes substr2 starts ahead of substr1.
  ll substr_equal(ll l1, ll r1, ll l2, ll r2) {
    assert(r1>=l1 && r2>=l2 && l2>=l1);
    ll h1 = get(l1,r1);
    ll h2 = get(l2,r2);

    //return s.substr(l1,r1-l1+1) == s.substr(l2,r2-l2+1);
    return ((h1-h2)%mod) == 0;
  }
};


