//Morris-Pratt法
//res[i] := [0,i)の接頭辞と接尾辞が最大何文字一致しているか（自明な長さiを除く）
//res[0] = -1
void morris_pratt(const std::string& str, std::vector<int>&res)
{
	int len = str.length();
	res.resize(len + 1);
	res[0] = -1;
	int j = -1;
	for (int i = 0; i < len; ++i)
	{
		while (j >= 0 && str[i] != str[j])j = res[j];
		++j;
		res[i + 1] = j;
	}
}

//Manacher法
//res[i] := iを中心とする最大の回文の半径
void manacher(const std::string& str, std::vector<int>&res)
{
	int len = str.length();
	res.resize(len);
	int i = 0, j = 0;
	while (i < len)
	{
		while (i - j >= 0 && i + j < len && str[i - j] == str[i + j])
			++j;
		res[i] = j;
		int k = 1;
		while (i - k >= 0 && i + k < len && k + res[i - k] < j)
			res[i + k] = res[i - k], ++k;
		i += k, j -= k;
	}
}

//Z-algorithm
//res[i] := 自分自身と[i,|S|)の最長共通接頭辞の長さ
void z_algorithm(const std::string& str, std::vector<int>&res)
{
	int len = str.length();
	res.resize(len);
	res[0] = len;
	int i = 1, j = 0;
	while (i < len)
	{
		while (i + j < len && str[j] == str[i + j])
			++j;
		res[i] = j;
		if (j == 0)
		{
			++i;
			continue;
		}
		int k = 1;
		while (i + k < len && k + res[k] < j)
			res[i + k] = res[k], ++k;
		i += k, j -= k;
	}
}

