inline bool check(int len){
	for(int l = 1; l * l <= len; l++) if(len % l == 0){
		if(l < len && z[l] >= len - l) return 0;
		if(len / l < len && z[len / l] >= len - len / l) return 0;
	}
	for(int l = 1; l * l <= n - len; l++) if((n - len) % l == 0){
		if(l < n - len && rz[l] >= n - len - l) return 0;
		if(len / l < n - len && rz[len / l] >= n - len - len / l) return 0;
	}
	return 1;
}

