#define MAXN 500000

char s[MAXN + 1];
int pi[MAXN + 1], ip[MAXN + 1];

inline void calcPi(int n, char s[], int pi[]) {
    int r = 0;
    for (int i = 2; i <= n; i++) {
        while (r && s[i] != s[r + 1])
            r = pi[r];
        if (s[i] == s[r + 1])
            r++;
        pi[i] = r;
    }
}

int main() {
    char ch = fgetc(stdin);
    int n = 0;
    while (ch != '\n') {
        s[++n] = ch;
        ch = fgetc(stdin);
    }

    calcPi(n, s, pi);
    if (pi[n] == n - 1) printf("%d\n1\n", n);
    else if (pi[n] == 0 || n % (n - pi[n]) != 0) printf("1\n1\n");
    else {
        int ans = 0;
        for (int i = 1, j = n; i < j; i++, j--)
            std::swap(s[i], s[j]);
        calcPi(n, s, ip);
        for (int i = 1; i < n; i++)
            if ((pi[i] == 0 || i % (i - pi[i]) != 0) && (ip[n - i] == 0 || (n - i) % (n - i - ip[n - i]) != 0))
                ans++;
        printf("2\n%d\n", ans);
    }

    return 0;
}

