    if( a > b ){
      swap( a , b );
    }
    if( seg.query( a , b ) >= x-w ){
      // cout << "* " << x << endl;
      ng[x] = true;
    }
  }

  v = fact( n-x );
  SORT( v );
  UNIQUE( v );
  YYS( u , v ){
