void ZAlgorithm(const string& s, vector<int>& len)
{
    int n = s.size();
    int i = 1;
    int j = 0;

    len.resize(n);
    len[0] = n;
    while(i < n){
        while(i+j < n && s[j] == s[i+j])
            ++j;
        len[i] = j;
        if(j == 0){
            ++ i;
            continue;
        }

        int k = 1;
        while (i+k < n && k+len[k] < j){
            len[i+k] = len[k];
            ++ k;
        }
        i += k;
        j -= k;
    }
}

void solve(const string& s, vector<bool>& good)
{
    vector<int> len;
    ZAlgorithm(s, len);

    int n = s.size();
    good.assign(n+1, true);
    for(int i=1; i<n; ++i){
        for(int j=1; i*(j+1)<=n; ++j){
            if(len[i*j] < i)
                break;
            good[i*(j+1)] = false;
        }
    }
}

int main()
{
    string s;
    cin >> s;
    int n = s.size();
    if(s == string(n, s[0])){
        cout << n << endl << 1 << endl;
        return 0;
    }

