vector<int> z_func(string &s) {
  vector<int> z(len(s), 0);
  int l = 0, r = 1;
  rep(i, 1, sz(z) - 1) {
    if (i <= r)
      z[i] = min(z[i - l], r - i);
    while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]])
      z[i]++;
    if (i + z[i] > r)
      l = i, r = i + z[i]; 
  }
  return z;
}

bool is_good(string s) {
  auto z = z_func(s);
  rep(i, 1, len(s) / 2) {
    bool can_divide = len(s) % i == 0 && z[i] == i * (len(s) / i - 1);
    if (can_divide) return false;
  }
  return true;
}

void solve() {
  string s;
  cin >> s;

  string rev_s = s;
  reverse(all(rev_s));

  auto z = z_func(s);
  auto rev_z = z_func(rev_s);

  rep(i, 1, len(s) / 2) {
    bool can_divide = len(s) % i == 0 && z[i] == i * (len(s) / i - 1);
    if (!can_divide) continue;

