 public:
  string s;
  int n;
  Solver(string s) : s(s), n(s.length()){};
  int minPeriod(string str) {
    int l = str.length();
    for (int i = 1; i < l; ++i) {
      if (l % i == 0) {
        string tmp = str;
        rotate(tmp.begin(), tmp.begin() + i, tmp.end());
        if (tmp == str) return i;
      }
    }
    return 0;
  }
  void solve() {
    int p = minPeriod(s);
    if (p == 0) {
      cout << 1 << endl;
      cout << 1 << endl;
