    if (same)
    {
        cout << n << endl;
        cout << 1 << endl;
        return 0;
    }
    auto z = z_algorithm(s);
    bool dif = true;
    for (int len = 2; 2 * len <= n; len++)
    {
        if (n % len)
        {
            continue;
        }
        bool f = true; // len の部分文字列がすべて一致?
        for (int i = len; i < n; i += len)
        {
            if (z[i] < len)
            {
                f = false;
            }
        }
        if (f)
            dif = false;
    }
    if (dif)
    {
