            }
            len = (n - i) / l;
            for (int j = len; j < (n - i); j += len)
            {
                if (rz[j] < len)
                    f = false;
            }
            if (f)
            {
                good = false;
                break;
            }
        }
        if (good)
            ret++;
    }
