bool is_good(const string &s) {
	int len = (int) s.size();
	for (int l = 2; l <= len / 2; l ++) {
		if (len % l == 0) {
			string t = s.substr(0, l);
			bool bad = true;
			for (int bg = l; bg < len - l; bg += l) {
				for (int i = bg; i < bg + l; i ++) {
					if (t[i - bg] != s[i]) {
						bad = false;
						goto end;
					}
				}
			}
			end:;
			if (bad) {
				return false;
			}
		}
	}
	return true;
}

