vector<bool> solve(vector<int> z){
    int n = (int)z.size();
    vector<bool> G(n);
    for(int i = 1;i <= n;i++){
        G[i - 1] = true;
    }
    for(int p = 1;p < n;p++){
        if(!G[p - 1]) continue;
        for(int k = 2;(k - 1) * p <= z[p];k++){
            G[k * p - 1] = false;
        }
    }
    return G;
}

