vector <bool> get1(string s){
    int n = s.length();
    vector <bool> bol(n, false);
    for (int i = 1; i < n; i++){
        int d = 1e9;
        for (int j = i; j < n; j += i)
            d = min(d, z[j]);
        if (d >= i){
            for (int j = i; j < n; j += i)
                bol[j + i - 1] = true;
        }
    }
    return bol;
}


vector <bool> get2(string s){
    int n = s.length();
    vector <bool> bol(n, false);
    for (int i = 1; i < n; i++){
        int d = 1e9;
        for (int j = 2 * i - 1; j < n; j += i)
            d = min(d, p[j]);
        if (d >= i){
            for (int j = 2 * i - 1; j < n; j += i)
                bol[j] = true;
        }
    }
    return bol;
}

