std::vector<bool> check()
{
    memset(nxt, -1, sizeof(nxt));
    for (int i = 0; i < n; ++ i) {
        int j = i;
        while (~j) {
            j = nxt[j];
            if (s[j + 1] == s[i + 1]) {
                nxt[i + 1] = j + 1;
                break;
            }
        }
    }
    std::vector<bool> ok(n + 1);
    ok[1] = true;
    for (int i = 2; i <= n; ++ i) {
        ok[i] = i % (i - nxt[i - 1] + 1) != 0;
    }
    return ok;
}

int main()
{
    scanf("%s", s);
    n = strlen(s);
    auto prefix = check();
    std::reverse(s, s + n);
    auto suffix = check();
    if (prefix[n]) {
        printf("1\n1\n");
    } else {
        int cut = 0;
        for (int i = 1; i < n; ++ i) {
            cut += prefix[i] && suffix[n - i];
        }
        if (cut) {
            printf("2\n%d\n", cut);
        } else {
            printf("%d\n1\n", n);
        }
    }
}

