        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) j++;
        pi[i] = j;
    }
    return pi;
}

void solve() {
    string s;
    cin >> s;
    set<char> chars;
    for (char c : s) chars.insert(c);
    if (chars.size() == 1){
        cout << s.length() << '\n' << 1 << '\n';
    } else {
        int x = s.length() - p(s).back();
        if (x == s.length() || s.length() % x > 0)
            cout << 1 << '\n' << 1 << '\n';
        else
            cout << 2 << '\n' << s.length() - s.length() / x + (2 * x == s.length()) << '\n';
    }
}

bool multitest = false;

int main() {
    init();
    int t = 1;
    if (multitest) cin >> t;
    forn(i, t) solve();
}

