ll pat[4001];
ll tx[4001];
ll hashe[4001];

bool C(int f,int t){
	int len=t-f;
	vector<int> ve;
	for(int g=2;g*g<=len;g++){
		if(len%g==0){
			ve.push_back(g);
			ve.push_back(len/g);
		}
	}
	for(int i=0;i<ve.size();i++){
		int v=ve[i];
		ll base=(hashe[f+v]-hashe[f]+MOD)%MOD;
		int j;
		for(j=1;j<len/v;j++){
			ll bak=(hashe[f+v*(j+1)]-hashe[f+v*j]+MOD)%MOD;
			if(base*tx[v*j]%MOD!=bak)break;
		}
		if(j==len/v)return false;
	}
	return true;
}

int main(void){
	cin >> str;
	int n=str.size();
	tx[0]=1;
	for(int i=0;i<n;i++){
		hashe[i+1]+=hashe[i];
		hashe[i+1]+=(str[i]-'a')*tx[i]%MOD;
		hashe[i+1]%=MOD;
		tx[i+1]=tx[i]*26LL%MOD;
	}
	pat[0]=1;
	for(int i=0;i<=n;i++){
		dp[i]=n+5;
	}
	dp[0]=0;
	for(int i=0;i<n;i++){
		for(int j=i+1;j<=n;j++){
			if(C(i,j)){
				if(dp[j]>dp[i]+1){
					pat[j]=0;
				}
				dp[j]=min(dp[j],dp[i]+1);
				if(dp[j]==(dp[i]+1)){
					pat[j]+=pat[i];
					pat[j]%=MOD;
				}
			}
		}
	}
