// z-algorithm : a[i] = s[0,n) と s[i,n) の最長共通接頭辞の長さ O(N)
vector<int> zAlgorithm(const string &s){
  int n = s.size();
  vector<int> a(n+1,0);
  int i=1, j=0;
  while(i<n){
    while(i+j<n && s[j] == s[i+j]) j++;
    a[i] = j;
    if(j==0){i++; continue;}
    int k = 1;
    while(i+k<n && k+a[k]<j) a[i+k]=a[k], k++;
    i += k;
    j -= k;
  }
  return a;
}

int main(){
  string s;
  cin>>s;
  int n = s.size();

  if(all_of(all(s), [&](char c){return c == s[0];})){
    cout << n << "\n1\n";
    return 0;
  }

  auto zarr = zAlgorithm(s);
  bool perioded = false;
  rep(i,2,n) if(n%i==0 && zarr[i] == n-i) perioded = true;

  if(!perioded){
    cout << "1\n1\n";
    return 0;
  }

  vector<bool> lb(n+1,true), rb(n+1, true);
  reverse(all(s));
  auto rarr = zAlgorithm(s);

  auto exec = [&](vector<int> &z, vector<bool> &b){
    rep(i,1,n){
      int j = i;
      while(j<n){
        if(z[j] >= i) b[j+i] = false;
        else break;
        j += i;
      }
    }
  };

  exec(zarr, lb);
  exec(rarr, rb);

  int res = 0;
  rep(i,1,n) if(lb[i] && rb[n-i]) res++;
  assert(res>0);

  cout << "2\n" << res << endl;

  return 0;
}

