int Z[N];
string str;
int build()
{
    int n=str.size();
    fill(Z,Z+n,0);
    int L=0,R=0;
    int i,k;
    for(i=1;i<n;i++)
    {
        if(i>R)
        {
            L=i,R=i;
            while(R<n && str[R-L]==str[R])R++;
            Z[i]=R-L,R--;
        }
        else
        {
            k=i-L;
            if(Z[k]<R-i+1)
                Z[i]=Z[k];
            else
            {
                L=i;
                while(R<n && str[R-L]==str[R])R++;
                Z[i]=R-L,R--;
            }
        }
    }
    lp(i,1,n)
    {
        if(Z[i]==n-i && (n%i)==0)
            return i;
    }
    return n;
}
queue<int> pq;
int s=0;
int add(int k,int p)
{
    int m=0,x=k+1;
    int i;
    while(s--)
    {
        i=pq.front();
        pq.pop();
        if(str[k]==str[k-i])
        {
            if(i<=p)
            {
                pq.push(i),m++;
                if((k+1)%i==0)
                    x=i;
            }
        }
    }
    if(str[k]==str[0])
    {
        if(k<=p)
        {
            pq.push(k),m++;
            if(k==1)
                x=1;
        }
    }
    s=m;
    if(x<k+1)
        return 0;
    return 1;
}
vi initial(int p)
{
    int i,n;
    n=str.size();
    while(!pq.empty())
        pq.pop();
    s=0;
    vi v(n,1);
    i=1;
    while(str[i]==str[0])
        v[i]=0,pq.push(i),s++,i++;
    for(;i<n;i++)
    {
        if(i<4*p)
            v[i]=add(i,p);
        else if((i+1)%p==0)
            v[i]=0;
    }
    return v;
}
