int hash1(int l, int r) {
	return (h1[r] - 1LL * h1[l] * pw1[r - l] % mod1 + mod1) % mod1;
}
int hash2(int l, int r) {
	return (h2[r] - 1LL * h2[l] * pw2[r - l] % mod2 + mod2) % mod2;
}
int main() {
	cin >> s;
	pw1[0] = pw2[0] = 1;
	for (int i = 1; i <= s.size(); i++) {
		h1[i] = (1LL * h1[i - 1] * b + s[i - 1]) % mod1;
		h2[i] = (1LL * h2[i - 1] * b + s[i - 1]) % mod2;
		pw1[i] = pw1[i - 1] * b % mod1;
		pw2[i] = pw2[i - 1] * b % mod2;
	}
	int z = -1;
	for (int i = 1; i <= s.size(); i++) {
		if (s.size() % i != 0) continue;
		bool f = true;
		for (int j = i; j < s.size(); j++) {
