int kmp[4010][4010], dp[4100], ways[4100];

void pre(int idx) {
	int j = idx;
	kmp[idx][idx] = idx;
	for (int i = idx + 1; i < s.size(); ++i) {
		while (j > idx && s[i] != s[j])j = kmp[idx][j - 1];
		if (s[i] == s[j])++j;
		kmp[idx][i] = j;
	}
}
bool isGood(int l , int r) {
	int len = (r - l + 1);
	int pattern = r - kmp[l][r] + 1;
	if (pattern == len)return 1;
	return len % pattern != 0;
}

int calc(int idx) {
	if (idx == s.size())return 0;
	int &ret = dp[idx];
	if (ret != -1)return ret;
	ret = oo;
	for (int i = idx ; i < s.size(); ++i) {
		if (isGood(idx, i))ret = min(ret, 1 + calc(i + 1));
	}
	return ret;
}
int solve(int idx) {
	if (idx == s.size())return 1;
	int &ret = ways[idx];
	if (ret != -1)return ret;
	ret = 0;
	for (int i = idx ; i < s.size(); ++i) {
		if (isGood(idx, i) && 1 + calc(i + 1) == calc(idx)) {
			ret = (ret + solve(i + 1)) % MOD;
		}
	}
	return ret;
}
int main() {
	memset(dp, -1, sizeof dp);
	memset(ways,-1,sizeof ways);
	cin >> s;
	for (int i = 0 ; i < s.size(); ++i)pre(i);
	printf("%d\n", calc(0));
	printf("%d\n", solve(0));
	return 0;
}

