// z[i] is the length of the longest common prefix between s and the suffix of s starting at i
vector<int> make_z_function(const string& s) {
    vector<int> z(s.length());
    z[0] = s.length();
    for(int i = 1, L = 0, R = 0; i < s.length(); i++) {
        z[i] = i < R ? min(z[i - L], R - i) : 0;
        while(i + z[i] < s.length() and s[i + z[i]] == s[z[i]]) {
            z[i]++;
        }
        if(R < i + z[i]) {
            L = i, R = i + z[i];
        }
    }
    return z;
}
vector<int> get_periods(string& s) {
    auto z = make_z_function(s);
    vector<int> periods(s.size() + 1);
    iota(periods.begin(), periods.end(), 0);
    for(int k = s.size() - 1; k >= 1; k--) {
        bool can = true;
        for(int i = 0; i + k <= s.size() and can; i += k) {
            if(can &= z[i] >= k) {
                periods[i + k] = k;
            }
        }
    }
    return periods;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    string s;
    cin >> s;
    vector<int> period_left = get_periods(s);
    reverse(s.begin(), s.end());
    vector<int> period_right = get_periods(s);
    if(period_left[s.size()] == s.size()) {
        cout << 1 << endl;
