const int MAX = 500001, MS = 2;
const ll mod[] = {999999937LL, 1000000007LL}, base = 9973;
struct rolling_hash {
    //全て開区間であることに注意
    int n;
    vector<ll> hs[MS], pw[MS];
    rolling_hash(){}
    rolling_hash(const string &s) {
        n = s.size();
        for (int i = 0; i < MS; i++) {
            hs[i].assign(n+1,0);
            pw[i].assign(n+1,0);
            hs[i][0] = 0;
            pw[i][0] = 1;
            for (int j = 0; j < n; j++) {
                pw[i][j+1] = pw[i][j]*base%mod[i];
                hs[i][j+1] = (hs[i][j]*base+s[j])%mod[i];
            }
        }
    }
    ll hash(int l, int r, int i) { return ((hs[i][r]-hs[i][l]*pw[i][r-l])%mod[i]+mod[i])%mod[i]; }
    bool match(int l1, int r1, int l2, int r2) {
        bool ret = 1;
        for (int i = 0; i < MS; i++) ret &= hash(l1,r1,i)==hash(l2,r2,i);
        return ret;
    }
    bool match(int l, int r, ll h[]) {
        bool ret = 1;
        for (int i = 0; i < MS; i++) ret &= hash(l,r,i)==h[i];
        return ret;
    }
};

int main(){
    string S;
    cin >> S;
    int N = S.size();
    rolling_hash hash(S);
    vec<int> L(N+1,1),R(N+1,1);
    int mi = N;
    for(int i=1;i<=N;i++){
        bool ok = true;
        for(int j=i;j<N;j+=i){
            bool y = hash.match(0,i,j,j+i);
            ok &= y;
            L[j] &= !ok;
        }
        if(ok && N%i==0){
            mi = min(mi,i);
        }
        ok = true;
        for(int j=N-2*i;j>=0;j-=i){
            bool y = hash.match(N-i,N,j,j+i);
            ok &= y;
            R[j] &= !ok;
        }
    }
    if(mi==1){
        cout << N << "\n";
        cout << 1 << "\n";
        return 0;
    }else if(mi==N){
        cout << 1 << "\n";
        cout << 1 << "\n";
        return 0;
    }
    int ans = 1;
    for(int i=1;i<N;i++) ans += L[i] && R[i];
    cout << 2 << "\n";
    cout << ans << "\n";
}

