vector<int> Zalgorithm(const string &str) {
  int sz = str.size();
  vector<int> ret(sz, 0);
  ret[0] = sz;
  int i = 1, j = 0;
  while (i < sz) {
    while (i+j < sz && str[j] == str[i+j]) ++j;
    ret[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i+k < sz && k+ret[k] < j) {
      ret[i+k] = ret[k];
      ++k;
    }
    i += k; j -= k;
  }
  return ret;
}

void solve() {
  string s; cin >> s;

  auto zf = Zalgorithm(s);
  reverse(ALL(s));
  auto zb = Zalgorithm(s);

  const int n = s.size();
  vb f(n+1, true), b(n+1, true);

  rep1(i,n/2+1) {
    if (f[i] && zf[i] >= i) {
      for (int j=i; j<=zf[i]; j+=i) {
        f[i+j] = false;
      }
    }
    if (b[i] && zb[i] >= i) {
      for (int j=i; j<=zb[i]; j+=i) {
        b[i+j] = false;
      }
    }
  }

  int cnt, sum;

  if (f[n]) {
    cnt = sum = 1;
  } else if (zf[1] == n-1) {
    cnt = n, sum = 1;
  } else {
    cnt = 2, sum = 0;
    rep1(i,n) sum += f[i] & b[n-i];
  }

  cout << cnt << "\n" << sum << endl;
}


