	static int const P[K] = {63, 61};
	static int const MOD[K] = {1000001531, 1000002187};//, 1000000007, 1000002277};

	int mul(int a, int b, int mod){
		return (ll) a * b % mod;
	}

	int sum(int a, int b, int mod){
		a %= mod;
		while(a < 0) a += mod;
		b %= mod;
		while(b < 0) b += mod;
		return (a + b) % mod;
	}

	void build(){
		fi(0, K) d[i][0] = 1;
		fi(1, N) fj(0, K){
			d[j][i] = mul(d[j][i-1], P[j], MOD[j]);
		}
		fi(0, sz(str)) fj(0, K){
			h[j][i] = mul( (i ? h[j][i-1] : 0), P[j], MOD[j]);
			h[j][i] = sum(h[j][i], (str[i] - 'a' + 1), MOD[j]);
		}
	}

	vector<int> gethash(int l, int r){
		vector<int> res;
		fi(0, K){
			int x = h[i][r];
			if(l) x = sum(x, -mul(h[i][l-1], d[i][r-l+1], MOD[i]), MOD[i]);
			res.pb(x);
		}
		return res;
	}
};

