struct KnuthMorrisPratt {
    string ptn;
    vector<int> kmp, mp;
    KnuthMorrisPratt(const string &ptn) : ptn(ptn) {
        int m = ptn.size();
        mp.assign(m + 1, -1), kmp.assign(m + 1, -1);
        for (int i = 0, j = -1; i < m; i++) {
            while (j >= 0 && ptn[i] != ptn[j]) j = kmp[j];
            kmp[i + 1] = mp[i + 1] = ++j;
            if (i + 1 < m && ptn[i + 1] == ptn[j]) kmp[i + 1] = kmp[j];
        }
    }
    int period(int i) { return i - mp[i]; }
    vector<int> match(const string &s) {
        int m = ptn.size(), n = s.size();
        vector<int> res;
        for (int i = 0, k = 0; i < n; i++) {
            while (k >= 0 && s[i] != ptn[k]) k = mp[k];
            if (++k == m) res.emplace_back(i - m + 1);
        }
        return res;
    }
};

vector<long long> enum_divisors(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i * i <= n; i++) {
        if (n % i != 0) continue;
        res.emplace_back(i);
        if (i != n / i) res.emplace_back(n / i);
    }
    sort(res.begin(), res.end());
    return res;
}

int main() {
    string s; cin >> s;
    int n = s.length();
    KnuthMorrisPratt kmp(s);
    if (s == string(n, s[0])) return !(cout << n << endl << 1 << endl);
    if (kmp.period(n) == n || n % kmp.period(n) != 0) {
        return !(cout << 1 << endl << 1 << endl);
    }
    string s_r = s;
    reverse(begin(s_r), end(s_r));
    KnuthMorrisPratt kmp_r(s_r);
    int cnt = 0;
    for (int i = 1; i < n; i++) {
        if (kmp.period(i) < i && i % kmp.period(i) == 0) continue;
        int j = n - i;
        if (kmp_r.period(j) < j && j % kmp_r.period(j) == 0) continue;
        cnt++;
    }
    cout << 2 << endl << cnt << endl;
    return 0;
}

