vector<int> z_fn(const string& s) {
    vector<int> ans(len(s));
    ans[0] = len(s);
    int l = 0, r = 0;
    rep1(i, len(s) - 1) {
        if (i > r) {
            l = i;
            r = i - 1;
        } else {
            ans[i] = ans[i - l];
        }
        while (i + ans[i] < len(s) and s[i + ans[i]] == s[ans[i]]) ++ans[i];
        if (i + ans[i] > r) {
            l = i;
            r = i + ans[i];
        }
    }
    return ans;
}

