const int MOD = 1e9+7;
const int N = 5e5+1;

vector<int> divisor[N], good[N];
int m[N], total[N], l;
string s;

bool isBad(int left, int right, int d) {
	string temp = "";
	for(int i = left; i < (left+d); i++) temp += s[i];
	for(int i = (left+d); i <= right; i += d)  
		for(int j = 0; j < d; j++)  
			if(temp[j] != s[i+j]) return false;						
	return true;
}

bool isGood(int left, int right) {
	int len = right-left+1;
	for(auto d : divisor[len])   
		if(isBad(left, right, d)) return false; 					
	return true;
}

void precompute() {
	for(int i = 2; i <= l; i++) {
		for(int j = 2; j*j <= i; j++) {
			if(i % j == 0) {
				divisor[i].push_back(j);
				if(j < (i/j)) divisor[i].push_back(i/j);
			} 
		}
		divisor[i].push_back(1);
	} 

	for(int i = 0; i < l; i++)  
		for(int j = 0; j <= i; j++)
			if(isGood(j, i)) good[i].push_back(i-j+1);
}

void solve() {
	m[0] = 0;
	total[0] = 1;
	for(int i = 1; i <= l; i++) {
		int curr1 = i, curr2 = 0;		
		for(auto g : good[i-1]) {
			if(m[i-g]+1 < curr1) {
				curr1 = m[i-g]+1;
				curr2 = total[i-g]; 
			}
			else if(m[i-g]+1 == curr1) curr2 = (curr2+total[i-g]) % MOD;
		}
		m[i] = curr1;
		total[i] = curr2;
	}
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> s;
	l = s.length();
	precompute(); 
	solve();
	cout << m[l] << endl;
	cout << total[l];
}

