const int N = 5e5 + 4;

int n, p[N], pr[N];

string s;

void fpi(int* pi) {
    pi[0] = 0;
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j && s[i] != s[j]) {
            j = pi[j - 1];
        }
        if (s[i] == s[j]) {
            ++j;
        }
        pi[i] = j;
    }
}

bool check(int len, int c) {
    if (len == 1) {
        return true;
    }
    return len == c || len % c;
}

void calc() {
    n = size(s);
    fpi(p);
    reverse(all(s));
    fpi(pr);

    int cycle = n - p[n - 1];
    if (cycle == n || n % cycle) {
        cout << "1\n1\n";
    } else {
        if (cycle == 1) {
            cout << n << "\n1\n";
        } else {
            int res = 0;
            for (int i = 0; i < n; ++i) {
                int c1 = i + 1 - p[i];
                int c2 = (n - i - 1) - pr[n - i - 2];
                if (check(i + 1, c1) && check(n - i - 1, c2)) {
                    ++res;
                }
            }
            cout << "2\n" << res << "\n";
        }
    }
}

void solve() {
    cin >> s;
    calc();
}

