  for(long long i=2; i*i<d.size(); i++){
    if(d[i] != i) continue;
    d[i] /= i;
    for(long long j=i*i; j<d.size(); j+=i ){
      if(d[j] != j) continue;
      d[j] /= i;
    }
  }
  for(auto i : range(1,n+1) ){
    if(d[i] == i) d[i] /= i;
  }

  vector<long long> bk(n+1, 1);
  for(auto i : range(1,n+1) ){
    bk[i] = bk[i-1] * 10009ll % mod;
  }
  for(auto i : range(1,n+1) ){
    bk[i] = (bk[i-1] + bk[i]) % mod;
  }


  Rolling_Hash h(w);
  vector<pair<long long,long long>> dp(w.size()+1, {1e7, 0});
