const int mod = 1e9 + 2277;

string s;
int Hash[N], pw[N], n;
bool pref[N], suff[N];

void buildHash(){
    s = "#" + s;
    pw[0] = 1;
    for (int i = 1; i < N; i++) pw[i] = (pw[i - 1] * base) % mod;
    Hash[0] = 0;
    for (int i = 1; i <= n; i++) Hash[i] = (Hash[i - 1] * base + s[i]) % mod;
}

int get (int l, int r) {
    return ((1LL * Hash[r] - 1LL * Hash[l - 1] * pw[r - l + 1]) % mod + mod) % mod;
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

