  const ll prime = 2641;
  string s; int n;
  vector<ll> H, P;
  string_hasher() {}
  void init(string s) {
    this->s = s;
    this->n = s.length();

    H.resize(n+10);
    P.resize(n+10, 1);
    for (int i=0; i<n; i++) {
      H[i+1] = (H[i]*prime+(s[i]-'a'))%mod;
      P[i+1] = (prime*P[i])%mod;
    }

  }

  ll get(int l, int r) {
    assert(l>=0 && r>=0 && l<n && r<n);
    ll res = H[r+1] - (P[r-l+1]*H[l])%mod;
    res %=mod;
    res += mod;
    return res%mod;
  }

  // Check if s[l1..r1] == s[l2...r2]. Assumes substr2 starts ahead of substr1.
  ll substr_equal(ll l1, ll r1, ll l2, ll r2) {
    assert(r1>=l1 && r2>=l2 && l2>=l1);
    ll h1 = get(l1,r1);
    ll h2 = get(l2,r2);

    bool res = ((h1-h2)%mod) == 0;
    // bool naive = (s.substr(l1,r1-l1+1) == s.substr(l2,r2-l2+1));
    // assert(res == naive);
    return res;
  }
};


