template<class T, class U> inline void amax(T &a, U b) { if (b > a) a = b; }
template<class T, class U> inline void amin(T &a, U b) { if (b < a) a = b; }
template<class T> inline T tabs(T a) { return (a > 0) ? a : -a; }
template<class T> T gcd(T a, T b) { while (b != 0) { T c = a; a = b; b = c % b; } return a; }

// based on 1-index
struct RollingHash {
	typedef unsigned long long ull;
	const unsigned base = 1000000009U;
	vector<ull> tpow, thash;

	template<class T>
	void init(const T s, const int _size) {
		tpow.resize(_size + 1);
		thash.resize(_size + 1);
		tpow[0] = 1, thash[0] = 0;
		for (int i = 0; i < _size; ++i) {
			tpow[i + 1] = tpow[i] * base;
			thash[i + 1] = s[i] + thash[i] * base;
		}
	}
	// return range[l, r]
	ull range(int l, int r) const { return thash[r] - thash[l - 1] * tpow[r - l + 1]; }
};

const int N = 500001;
vector<int> g[N];

int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	string w; cin >> w;
	int n = w.size();
	REPU(i, 1, n + 1) {
		for (int j = i + i; j <= n; j += i) g[j].push_back(i);
	}
	{// all w[i] are identical
		bool ok(true);
		REPU(i, 1, n) if (w[i] != w[0]) {
			ok = false; break;
		}
		if (ok) {
			printf("%d\n%d\n", n, 1);
			return 0;
		}
	}
	RollingHash rh;
	rh.init(w, n);
	{// ans = 1
		bool ok(true);
		for (int p : g[n]) {
			if (rh.range(1, n - p) == rh.range(p + 1, n)) {
				ok = false; break;
			}
		}
		if (ok) {
			printf("%d\n%d\n", 1, 1);
			return 0;
		}
	}
	{// ans = 2
		int ans = 0;
		REPU(i, 1, n) {
			int check = 0;
			if (i == 1) check++;
			else {
				bool ok(true);
				for (int p : g[i]) {
					if (rh.range(1, i - p) == rh.range(p + 1, i)) {
						ok = false; break;
					}
				}
				if (ok) check++;
			}
			if (n - i == 1) check++;
			else {
				bool ok(true);
				for (int p : g[n - i]) {
					if (rh.range(i + 1, n - p) == rh.range(i + p + 1, n)) {
						ok = false; break;
					}
				}
				if (ok) check++;
			}
			if (check == 2) ans++;
		}
		printf("%d\n%d\n", 2, ans);
	}

	return 0;
}

