int n;
int ai[N], ar[N];
char ch[N], cr[N];
int pr[N];
void solve(char ch[], int a[])
{
    int u = 0;
    a[1] = 1;
    for (int i = 2; i <= n; ++ i)
    {
        while (u && ch[u + 1] != ch[i]) u = pr[u];
        if (ch[u + 1] == ch[i]) u ++;
        if (u && i % (i - u) == 0); else a[i] = 1;
    }
}
int main()
{
    scanf("%s", ch + 1); n = strlen(ch + 1);
    int bo = 1;
    for (int i = 2; i <= n; ++ i)
        if (ch[i] != ch[1]) bo = 0;
    if (bo) {cout << n << "\n" << 1; return 0;}
    for (int i = 1; i <= n; ++ i) cr[i] = ch[n - i + 1];
    solve(ch, ai);
    if (ai[n]) {cout << 1 << "\n" << 1; return 0;}
    solve(cr, ar);
    for (int i = 1, j = n; i < j; ++ i, -- j) swap(ar[i], ar[j]);
    int cnt = 0;
    for (int i = 1; i < n; ++ i)
        if (ai[i] && ar[i + 1])
            cnt ++;
    cout << 2 << "\n" << cnt;
}

