    for(int i = 2; i <= N; i++)
    {
        while(p && s[i] != s[p + 1])
            p = pi[p];
        if(s[i] == s[p + 1])    p++;
        pi[i] = p;
    }

    int per = 0;
    if(pi[N] && N % (N - pi[N]) == 0)
        per = N - pi[N];

    if(!per)
    {
        printf("1\n1\n");
        return 0;
    }

    if(per == 1)
    {
        printf("%d\n1\n", N);
        return 0;
