long long Hash(long long x,long long y)
{
	return ((hash[y]-hash[x-1]*bitp[y-x+1])%MOD+MOD)%MOD;
}
bool check()
{
	for(long long i=2;i<=len;i++)
		if(s[i]!=s[i-1])
			return 0;
	return 1;
