inline void calcPrefix ( const string S, vector<int>& pi ) {
	int n = S.length ();
	pi.clear (), pi.push_back ( 0 );
	for ( int i = 1; i ^ n; ++ i ) {
		int j = pi[i - 1];
		for ( ; j && S[i] ^ S[j]; j = pi[j - 1] );
		pi.push_back ( j + ( S[i] == S[j] ) );
	}
}

int main () {
	ios :: sync_with_stdio ( false ), cin.tie ( 0 );
	cin >> S;
	int n = S.length ();
	bool allsame = true;
	for ( int i = 1; i ^ S.size () && allsame; ++ i ) allsame &= S[i] == S[0];
	if ( allsame ) return cout << n << "\n1\n", 0;
	calcPrefix ( S, prepi );
	reverse ( S.begin (), S.end () );
	calcPrefix ( S, sufpi );
	if ( ! prepi[n - 1] || n % ( n - prepi[n - 1] ) ) return cout << "1\n1\n", 0;
	int ans = 0;
	for ( int i = 0; i + 1 < n; ++ i ) {
		if ( ( ! prepi[i] || ( i + 1 ) % ( i + 1 - prepi[i] ) )
			&& ( ! sufpi[n - 2 - i] || ( n - i - 1 ) % ( n - i - 1 - sufpi[n - 2 - i] ) ) ) {
			++ ans;
		}
	}
	cout << "2\n" << ans << endl;
	return 0;
}

