    }
    return 1;
}
int binpow(int x, int y, int mod){
   // cout << x << " " << y << " " << mod << endl;
    if (y == 0) return 1;
    if (y % 2) return x * binpow(x, y - 1, mod) % mod;
    int z = binpow(x, y / 2, mod);
    return z * z % mod;
}
