	per(i,0,len) {
		if (pre2[i]==len) f2[i]=len-i; else {
			if (pre2[i]-i == f2[pre2[i]]) {
				f2[i] = f2[pre2[i]];
			}
			else {
				f2[i] = len-i;
			}
		}
		//debug(f2[i]);
	}

	///work
	if (f1[len-1]==len) {
		cout << 1 << endl << 1;
		return 0;
	}
	if (f1[len-1]==1) {
		cout << len << endl << 1;
		return 0;
	}
	int ans=0;
	rep(i,0,len-1) if (f1[i]==i+1 && f2[i+1]==len-i-1) ans++;
	cout << 2 << endl << ans;


}

