struct Zalgorithm {
	std::string s;
	std::vector<int> z;
	Zalgorithm(std::string s) : s(s), z(s.size()) {
		z[0] = s.size();
		int i = 1, j = 0;
		while (i < s.size()) {
			while (i + j < s.size() && s[j] == s[i + j]) ++j;
			z[i] = j;
			if (j == 0) { ++i; continue; }
			int k = 1;
			while (i + k < s.size() && k + z[k] < j) z[i + k] = z[k], ++k;
			i += k;
			j -= k;
		}
	}
	int& operator[](int i) { return z[i]; }
};

std::vector<int> enumerateDivisors(ll n) {
	std::set<int> set;
	for (int i = 1; i*i <= n; ++i) {
		if (n%i) continue;
		set.insert(i);
		set.insert(n / i);
	}
	std::vector<int> res(set.size());
	int p = 0;
	for (const auto& x : set) {
		res[p++] = x;
	}
	return res;
}

