string S; long long hush[600000], hushmod = 1000000007, mod = 1000000007, minx = 999999; bool OK[600000], res[600000];
vector<long long>y[600000]; long long power256[1000000];
long long modpow(long long a, long long b, long long m) {
	if (a == 256 && b < 1000000)return power256[b];
	long long p = 1, q = a;
	for (int i = 0; i < 40; i++) { if ((b / (1LL << i)) % 2 == 1) { p *= q; p %= m; }q *= q; q %= m; }
	return p;
}
long long Div(long long a, long long b, long long m) { return (a*modpow(b, m - 2, m)) % m; }
long long Hush(long long s, long long t, long long m) { return Div((hush[t] - hush[s] + m) % m, modpow(256, s, m), m); }
vector<long long>solve(string U) {
	vector<long long>cnt;
	for (int i = 0; i <= U.size(); i++)OK[i] = true;
	long long r3 = 0, r4 = 1;
	for (int i = 1; i <= U.size(); i++) { r3 += r4*U[i - 1]; r3 %= hushmod; hush[i] = r3; r4 *= 256; r4 %= hushmod; }
	for (int i = 0; i < U.size() - 1; i++) {
		int E = i + 1; bool T = false;
		for (int j = 0; j < y[E].size(); j++) {
			long long n1 = Hush(E - y[E][j], E, mod);
			long long n2 = 0; if (E != y[E][j]) n2 = Hush(E - y[E][j] * 2, E - y[E][j], mod);
			if (E != y[E][j] && n1 != n2)OK[y[E][j]] = false;
			if (OK[y[E][j]] == true && E != y[E][j])T = true;
		}
		if (T == true)cnt.push_back(i);
	}
	return cnt;
}
int main() {
	cin >> S; long long r1 = 0, r2 = 1; for (int i = 1; i <= S.size(); i++) { r1 += r2*S[i - 1]; r1 %= hushmod; hush[i] = r1; r2 *= 256; r2 %= hushmod; }
	power256[0] = 1; for (int i = 1; i < 1000000; i++) { power256[i] = (power256[i - 1] * 256LL) % mod; }
	for (long long i = 1; i <= S.size(); i++) { for (int j = i; j <= S.size(); j += i) { y[j].push_back(i); } }
	for (long long i = 1; i <= S.size(); i++) {
		if (S.size() % i >= 1)continue; long long r3 = Hush(0, i, mod); bool OK = true;
		for (int j = i; j < S.size(); j += i) { if (Hush(j, j + i, mod) != r3)OK = false; }
		if (OK == true)minx = min(minx, i);
	}
	if (minx == 1) { cout << S.size() << endl << "1" << endl; }
	else if (minx == S.size()) { cout << "1 1" << endl; }
	else {
		long long ret1 = 1; if (minx < S.size())ret1 = 2;
		string T = S;
		vector<long long>R1 = solve(T); for (int i = 0; i < R1.size(); i++)res[R1[i]] = true; reverse(T.begin(), T.end());
		vector<long long>R2 = solve(T); for (int i = 0; i < R2.size(); i++)res[S.size() - 2 - R2[i]] = true;
		if (S.size() / minx >= 3) { for (int i = minx - 1; i < S.size() - 1; i += minx) { res[i] = true; } }
		int ans = 0; for (int i = 0; i < S.size() - 1; i++) { if (res[i] == false)ans++; }
		cout << ret1 << endl << ans << endl;
	}
	return 0;
}

