// Suffix Array ( Manber&Myers: O(n (logn)^2) )
// 160830(ARC060 F)
struct SuffixArray {
    static const int MAX_S = 550000;
    string str;
    int sa[MAX_S];          // sa[i] : the starting index of the i-th smallest suffix (i = 0, 1, ..., n)
    vector<int> lcp;        // lcp[i]: the lcp of sa[i] and sa[i+1] (i = 0, 1, ..., n-1)
    inline int& operator [] (int i) {return sa[i];}

    // build SA
    int rank_sa[MAX_S];
    int tmp_rank_sa[MAX_S];
    struct CompareSA {
        int n, k;
        int *rank;
        CompareSA(int n, int k, int* rank_sa) : n(n), k(k), rank(rank_sa) {}
        bool operator()(int i, int j) {
            if (rank[i] != rank[j]) return (rank[i] < rank[j]);
            else {
                int rank_ik = (i + k <= n ? rank[i + k] : -1);
                int rank_jk = (j + k <= n ? rank[j + k] : -1);
                return (rank_ik < rank_jk);
            }
        }
    };
    void buildSA() {
        int n = (int)str.size();
        for (int i = 0; i < n; ++i) sa[i] = i, rank_sa[i] = (int)str[i];
        sa[n] = n, rank_sa[n] = -1;
        for (int k = 1; k <= n; k *= 2) {
            CompareSA csa(n, k, rank_sa);
            sort(sa, sa + n + 1, csa);
            tmp_rank_sa[sa[0]] = 0;
            for (int i = 1; i <= n; ++i) {
                tmp_rank_sa[sa[i]] = tmp_rank_sa[sa[i - 1]];
                if (csa(sa[i - 1], sa[i])) ++tmp_rank_sa[sa[i]];
            }
            for (int i = 0; i <= n; ++i) rank_sa[i] = tmp_rank_sa[i];
        }
    }

    // build LCP
    static const int INF = 1<<29;
    struct SparseTable {
        static const int LOG_MAX_S = 21;
        int st[LOG_MAX_S][MAX_S];
        int ln[MAX_S];

        void init(const vector<int> &vec) {
            for (int i = 0; i < MAX_S; ++i) {
                st[0][i] = INF;
                int ti = i, tln = 0;
                while (ti > 0) ti /= 2, ++tln;
                ln[i] = tln - 1;
            }
            for (int i = 0; i < vec.size(); ++i) st[0][i] = vec[i];
            for (int i = 1; i < LOG_MAX_S; ++i) {
                for (int j = 0; j < MAX_S; ++j) {
                    st[i][j] = min(st[i-1][j], st[i-1][j + (1<<(i-1))]);
                }
            }
        }

        // [a, b)
        int get(int a, int b) {
            if (a >= b) return INF;
            int bet = b - a, row = ln[bet];
            return min(st[row][a], st[row][b - (1<<row)]);
        }
    } st;
    int rsa[MAX_S];
    void calcLCP() {
        int n = (int)str.size();
        for (int i = 0; i <= n; ++i) rsa[sa[i]] = i;
        lcp.resize(n + 1);
        lcp[0] = 0;
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            int pi = sa[rsa[i] - 1];
            if (cur > 0) --cur;
            for (; pi + cur < n && i + cur < n; ++cur) {
                if (str[pi + cur] != str[i + cur]) break;
            }
            lcp[rsa[i] - 1] = cur;
        }
        st.init(lcp);
    }
    int getLCP(int a, int b) {          // lcp of str.sutstr(a) and str.substr(b)
        return st.get(min(rsa[a], rsa[b]), max(rsa[a], rsa[b]));
    }

    // sa
    void init(const string& str_) {
        str = str_;
        buildSA();
        calcLCP();
    }

} sa;



