        cout << 1 << endl;
        return 0;
    }
    bool ok = true;
    for(int i = 2; i < N; i++){
        if(N%i == 0){
            if(!same(i)) ok = false;
        }
    }
    if(ok){
        cout << 1 << endl;
        cout << 1 << endl;
        return 0;
