vector<int> z_func(string &s) {
  vector<int> z(len(s), 0);
  int l = 0, r = 1;

  rep(i, 1, sz(z) - 1) {
    if (i >= r) {
      l = r = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    } else if (z[i - l] < r - i) {
      z[i] = z[i - l];
    } else {
      z[i] = r - i;
      l = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    }
  }

  return z;
}

void solve() {
  string s;
  cin >> s;

  string rev_s = s;
  reverse(all(rev_s));

  auto z = z_func(s);
  auto rev_z = z_func(rev_s);

  rep(i, 1, sz(z) / 2) {
    bool can_divide = z[i] == len(s) - i;
    if (!can_divide) continue;

    if (i == 1) {
      cout << len(s) << nl << 1;
      return;
    } 

    vector<bool> can_divide_left(sz(z), true);
    can_divide_left[0] = false;
    rep(j, 1, sz(z) - 1) {
      if (z[j] >= j && can_divide_left[j]) {
        for (int k = j + j; k <= j + z[j]; k += j)
          if (k < sz(z))
            can_divide_left[k] = false;
      }
    }

    vector<bool> can_divide_right(sz(z), true);
    can_divide_right[sz(z) - 1] = false;
    per(j, sz(z) - 2, 0) {
      int l = len(s) - j - 1;
      if (rev_z[l] >= l && can_divide_right[j]) {
        for (int k = j - l; k >= j - rev_z[j]; k -= l)
          if (k >= 0)
            can_divide_right[k] = false;
      }
    }

    int res = 0;
    rep(j, 1, len(s) - 1) {
      if (can_divide_left[j] && can_divide_right[j - 1]) {
        res++;
      }
    }

    cout << 2 << nl << res;
    return;
  }

  cout << 1 << nl << 1;
}

