vector<int> KMP(string s) {
  int n = s.size();
  vector<int> pi(n + 1, -1);
  for (int i = 0; i < n; ++i) {
    int j = pi[i];
    while (j != -1 && s[j] != s[i])
      j = pi[j];
    pi[i + 1] = j + 1;
  }
  pi.erase(pi.begin());
  return pi;
}

int main() {
  string s; cin >> s;
  auto pi = KMP(s);
  reverse(s.begin(), s.end());
  auto ip = KMP(s);
  reverse(s.begin(), s.end());
  reverse(ip.begin(), ip.end());
  int n = s.size();

  if (pi.back() == n - 1) {
    cout << n << " " << 1 << endl;
  } else if (pi[n - 1] == 0 || n % (n - pi[n - 1]) != 0) {
    cout << 1 << " " << 1 << endl;
  } else {
    int total = 0;
    bool found = false;
    for (int i = 1; i < n; ++i) {
      int n1 = i, p1 = pi[i - 1];
      int n2 = n - i, p2 = ip[i];
      if ((n1 > 1 && p1 > 0 && n1 % (n1 - p1) == 0) || 
          (n2 > 1 && p2 > 0 && n2 % (n2 - p2) == 0)) 
        continue;
      // cerr << "OK: " << string(s.begin(), s.begin() + i) << " " << string(s.begin() + i, s.end()) << endl;
      found = true;
      total += 1;
    }
    assert(found);
    cout << 2 << " " << total << endl;
  }

  return 0;
}

