			(H0[r]-H0[l]*P0[r-l]%M0+M0)%M0,{
			(H1[r]-H1[l]*P1[r-l]%M1+M1)%M1,
			(H2[r]-H2[l]*P2[r-l]%M2+M2)%M2}
		};
	}
};

