double dot(complex<double> a, complex<double> b) {
	return a.real() * b.real() + a.imag() * b.imag();
}
double gyaku_dot(complex<double> a, complex<double> b) {
	return a.real() * b.imag() - a.imag() * b.real();
}
double leng(complex<double> a) {
	return sqrt(a.real() * a.real() + a.imag() * a.imag());
}
double angles(complex<double> a, complex<double> b) {
	double cosine = dot(a, b) / (leng(a) * leng(b));
	double sine = gyaku_dot(a, b) / (leng(a) * leng(b));
	double kaku = acos(min((double)1.0, max((double)-1.0, cosine)));
	if (sine <= 0) {
		kaku = 2 * Ma_PI - kaku;
	}
	return kaku;
}
vector<int> convex_hull(vector<complex<double>> a) {
	vector<int> ans;
	double now_minnest = a[0].real();
	int now_itr = 0;
	REP(i, a.size()) {
		if (now_minnest > a[i].real()) {
			now_minnest = a[i].real();
			now_itr = i;
		}
	}
	ans.push_back(now_itr);
	complex<double> ba(0, 1);
	while (true) {
		int now_go = 0;
		double now_min = 0;
		double now_length = 0;
		int starter = ans[ans.size() - 1];
		for (int i = 0; i < a.size(); ++i) {
			if (i != starter) {
				double goa = angles(ba, a[i] - a[starter]);
				if (goa - now_min >= eps || (abs(goa - now_min) <= eps && (abs(a[i] - a[starter]) - now_length) >= eps)) {
					now_min = goa;
					now_go = i;
					now_length = abs(a[i] - a[starter]);
				}
			}
		}
		if (now_go == ans[0]) break;
		ans.push_back(now_go);
		ba = complex<double>(a[now_go] - a[starter]);
	}
	return ans;
}
long long geko[200000] = {};
pair<long long, long long> nya[200000];
long long powing(long long A, long long B,long long C) {
	long long ans = 1;
	while (B != 0) {
		if (B % 2 == 1) {
			ans *= A;
			ans %= C;
		}
		A *= A;
		A %= C;
		B /= 2;
	}
	return ans;
}
pair<long long,long long> oks(long long start, long long len) {
	pair<long long, long long> first_set = nya[start + len - 1];//finite
	if (start != 0) {
		pair<long long, long long> geko = nya[start - 1];
		geko.first *= powing(26, len, MAX_MOD);
		geko.second *= powing(26, len, MOD);
		geko.first %= MAX_MOD;
		geko.second %= MOD;
		first_set = make_pair(first_set.first - geko.first, first_set.second - geko.second);
		first_set.first = (first_set.first + MAX_MOD) % MAX_MOD;
		first_set.second = (first_set.second + MOD) % MOD;
	}
	return first_set;
}
