inline int rhash(int l, int r) {
  return (1LL * ((T[r]+MOD-(l>0?T[l-1]:0))%MOD) * pB[N-l]) % MOD;
}

bool cycle(int l, int r, int d) {
  int n = r-l+1;
  if (2*d > n) return false;
  // [l, r-d] = [l+d, r]
  return rhash(l, r-d) == rhash(l+d, r);
}

bool is_good(int l, int r) {
  int n = r-l+1;
  for (int d=1; d<=sqrt(n); d++) {
    if (n % d) continue;
    if (cycle(l, r, d)) return false;
    if (cycle(l, r, n/d)) return false;
  }
  return true;
}

