vector<int> prefix_function (string s) {
    int n = (int) s.length();
    vector<int> pi (n);
    for (int i=1; i<n; ++i) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j])
            j = pi[j-1];
        if (s[i] == s[j])  ++j;
        pi[i] = j;
    }
    return pi;
}

void smain() {
    string s;
    cin >> s;
    int n = s.size();
    vi p = prefix_function(s);
    reverse(ALL(s));
    vi rp = prefix_function(s);
    reverse(ALL(rp));
    set<char> symbols(ALL(s));
    if (symbols.size() == 1) {
        cout << n << "\n1\n";
