const int MAXN = 500005;
const int MOD = 1000000007;
int f[MAXN], ans[MAXN], sums[MAXN], len[MAXN];
int main()
{
	string x;
	cin>>x;
	int n = x.length();
	ans[0] = 1;
	len[0] = 1;
	sums[1] = 1;
	for (int i = 1; i < n; ++i)
	{
		int cpos = i-1;
		while(cpos >= 0)
		{
			if(x[i] == x[f[cpos]])
			{
				f[i] = f[cpos]+1;
				break;
			}
			else
				cpos = f[cpos] - 1;
		}
		if(cpos < 0)
			f[i] = 0;
		int period = (i + 1 - f[i]);
		if((i+1)%period == 0 && period < (i+1))
		{
			if(period == 1)
			{
				ans[i] = 1;
				len[i] = i+1;
			}
			else
			{
				ans[i] = sums[1];
				len[i] = 2;
			}
		}
		else
		{
			ans[i] = 1;
			len[i] = 1;
		}
		sums[len[i]] = (sums[len[i]] + ans[i])%MOD;
	}
	cout<<len[n-1]<<"\n"<<ans[n-1]<<"\n";
	return 0;
}

