inline vector<int> InitKMP(const string& p) {
    vector<int> f(p.size(), -1);

    for (int i = 1; i < p.size(); i++) {
        int j = f[i-1];
        while (j >= 0 && p[j+1] != p[i]) j = f[j];
        if (p[j+1] == p[i]) f[i] = j + 1;
        else f[i] = -1;
    }

    for (int i = 0; i < p.size(); i++) ++f[i];
    return f;
}

