vector<int> v[500005];

inline int get(int l, int r) {
    long long res = h[r] - h[l - 1];
    if (res < 0) res += md;
    res *= p[n - l];
    res %= md;
    return res;
}

bool check(int l, int r) {
    int len = r - l + 1;
    if (len == 1) return false;
    for (int i = 0; i < (int)v[len].size(); ++i)
        if (get(l, r - v[len][i]) == get(l + v[len][i], r)) return true;
    return false;
}

