		for (int a = 2 ; a * d <= n ; a ++) {
			if (get(n - a * d , n - (a - 1) * d) != get(n - d , n)) break ;
			bad[n - a * d - 1] = 1 ;
		}
	}

	cout << "2\n" ;

	int ans = 0 ;
	for (int i = 0 ; i < n ; i ++) ans += !bad[i] ;

	cout << ans << '\n' ;
}

