#include <bits/stdc++.h>
using namespace std;
struct ZFunc{
    vector<int> z;
    ZFunc(const vector<int> & v): z(v.size()){
        int n = v.size(), a = 0, b = 0;
        if(!z.empty()) z[0] = n;
        for(int i = 1; i < n; ++i) {
            int end = i; if(i < b) end = min(i + z[i-a], b);
            while(end < n && v[end] == v[end-i]) ++end;
            z[i] = end - i; if(end > b) a = i, b = end;
        }
    }
};
int min_psz(string s){
	vector<int> v;
	for(auto e : s) v.push_back(e);
	ZFunc z(v);
	int len = s.size();
	for(int i = 1; i <= len; i++){
		if(len % i == 0){
			bool bad = false;
			for(int j = 0; j < len; j += i){
				if(z.z[j] < i) bad = true;
			}
			if(!bad) return i;
		}
	}
	assert(0);
	return -1;
}
int good_pos(string s){
	vector<int> v;
	for(auto e : s) v.push_back(e);
	ZFunc z(v);
	int len = s.size();
	vector<bool> good_cut(len + 1, true);
	for(int i = 1; i <= len; i++){
		for(int j = i; j < len; j += i){
			if(z.z[j] >= i){
				good_cut[j + i] = false;
			} else {
				break;
			}
		}
	}
	int ans = 0;
	for(int i = 1; i < len; i++){
		ans += good_cut[i];
	}
	return ans;
}
int main(){
	string s; cin >> s;
	int p = min_psz(s);
	int len = s.size();
	if(len == p) cout << "1\n1\n";
	else if(p == 1) cout << len << "\n1\n";
	else {
		cout << 2 << endl;
		string ns;
		for(int i = 0; i < p; i++) ns.push_back(s[i]);
		long long ans = good_pos(ns);
		ans += (len / p - 1) * (p - 1);
		if(len / p == 2){
			ans += min_psz(ns) == p;
		}	
		ans %= 1'000'000'007;
		cout << ans << endl;
	}
	return 0;
}

