	while(ch>='a'&&ch<='z')st[++len]=ch,ch=getchar();
	return len;
}

void getnext(char *st,int len)
{
	int j=0;
	for(int i=2;i<=len;++i)
	{
		while(j&&st[i]!=st[j+1])j=next[j];
		if(st[i]==st[j+1])++j;
		next[i]=j;
	}
}

