void Zalgo(string S){

  int L = 0, R = 0;
  int n = S.size();
  for (int i = 1; i < n; i++)
  {
      if (i > R)
      {
          L = R = i;
          while (R < n && S[R-L] == S[R])
          {
              R++;
          }
          z[i] = R-L;
          R--;
      }
      else
      {
          int k = i-L;
          if (z[k] < R-i+1)
          {
              z[i] = z[k];
          }
          else
          {
              L = i;
              while (R < n && S[R-L] == S[R])
              {
                  R++;
              }
              z[i] = R-L;
              R--;
          }
      }
  }
  int idx = (find(S.begin(), S.end(), '#') - S.begin()) + 1;
  f(i,idx,n)
    z[i-idx] = z[i];
}
bitset<N> solve(){
  bitset<N> ret;
  ret.set();
  Zalgo(S + "#" + S);
  f(i,1,S.size()/2+1)
    for(int j = i; z[j] >= i && j + i <= n; j += i)ret[j+i] = 0;
  return ret;
}
