auto z_algorithm(const string &s) {
	int n = s.size(), i = 1, j = 0, k;
	vector<int> z(n, n);
	while (i < n) {
		while (i + j < n && s[i + j] == s[j]) j++;
		z[i] = j, k = !!j;
		while (i + k < n && k + z[k] < j) z[i + k] = z[k], k++;
		i += k + !j, j -= k;
	}
	return z;
}

bool is_good_string(const vector<int> &z,int len){
	if(len == 1) return true;
	if(1 + z[1] >= len) return false;

	for(int j = 2; j * j <= len; ++j) {
		if(len % j) continue;
		if (j + z[j] >= len) return false;
		const int k = len / j;
		if (k + z[k] >= len) return false;
	}

	return true;
}

