ll MOD = 999999937;
ll _MOD = 1000000009;
double EPS = 1e-10;

int mod_inv(ll x, int M) {
	int t = M - 2, y = 1;
	for (; t; t>>=1) {
		if (t & 1) y = y * x % M;
		x = x * x % M;
	}
	return y;
}

struct rolling_hash {
	int M;
	vector<int> a, b;
	rolling_hash(string s, int _M) {
		M = _M;
		int N = s.length();
		a.resize(N + 1);
		ll x = 1;
		for (int i = 0; i < N; i++) {
			a[i + 1] = (a[i] + x * s[i]) % M;
			x = x * 256 % M;
		}
		ll inv = mod_inv(256, M);
		b.resize(N + 1);
		b[0] = 1;
		for (int i = 0; i < N; i++)
			b[i + 1] = b[i] * inv % M;
	}
	int get(int l, int r) {
		return ((ll)(a[r] - a[l]) * b[l] % M + M) % M;
	}
};

int p[500001], nxt[500001];

bool good(int l, int r, rolling_hash& a, rolling_hash& b) {
	int d = r - l;
	while (p[d]) {
		int x = (r - l) / p[d];
		if (a.get(l, r - x) == a.get(l + x, r) && b.get(l, r - x) == b.get(l + x, r))
			return false;
		d = nxt[d];
	}
	return true;
}

int main() {
	string s; cin >> s;
	int N = s.length();
	bool same = true;
	for (int i = 0; i + 1 < N; i++)
		if (s[i] != s[i + 1])
			same = false;
	if (same) {
		cout << N << endl;
		cout << 1 << endl;
		return 0;
	}
	rolling_hash a(s, MOD), b(s, _MOD);
	for (int i = 2; i <= 500000; i++)
		if (!p[i])
			for (int j = i * 2; j <= 500000; j += i)
				if (!p[j]) {
					p[j] = i;
					for (nxt[j] = j; nxt[j] % i == 0; nxt[j] /= i);
				}
	if (good(0, N, a, b)) {
		cout << 1 << endl;
		cout << 1 << endl;
		return 0;
	}
	int ans = 0;
	for (int i = 1; i <= N - 1; i++)
		if (good(0, i, a, b) && good(i, N, a, b))
			ans++;
	cout << 2 << endl;
	cout << ans << endl;
}

