vector<int> KMP(vector<int> A){
    int N = A.size();
    vector<int> K(N + 1), next(N);
    K[0] = -1; next[0] = -1;
    int j = -1;
    for(int i = 0; i < N; i++){
        while(j >= 0 && A[i] != A[j]) j = next[j];
        j++;
        K[i + 1] = j;
        if(i + 1 < N){
            if(A[i + 1] == A[j]) next[i + 1] = next[j];
            else next[i + 1] = j;
        }
    }
    return K;
}

vector<int> KMP(string S){
    int N = S.size();
    vector<int> A(N);
    for(int i = 0; i < N; i++) A[i] = (int)S[i];
    return KMP(A);
}

