    if(s[i] != s[0]) same = false;
  }
  if(same) {
    printf("%d %d\n",(int)s.size(), 1);
    return 0;
  }
  F[0] = F[1] = 0;

  rep(i,2,n+1) {
    int j = F[i-1];
    while(1) {
      if(s[j] == s[i-1]) {
        F[i] = j + 1;
        break;
      }
      if(!j) {
        F[i] = 0;
        break;
      }
      j = F[j];
    }
  }
  int x = F[n];
  int y = n - x;
  if(n % y != 0 || y == n || !check(n,y)) {
    printf("%d %d\n",1,n);
    return 0;
  }

  rep(i,1,n) {
    int x = i - F[i];
    if(x != i && i % x == 0 && check(i,x)) X[i] = true;
  }

  reverse(all(s));
  F[0] = F[1] = 0;

  rep(i,2,n+1) {
    int j = F[i-1];
