bool prime(int x){
    if (x == 1) return 0;
    for (int i = 2; i * i <= x; i++){
        if (x % i == 0) return 0;
    }
    return 1;
}
int binpow(int x, int y, int mod){
   // cout << x << " " << y << " " << mod << endl;
    if (y == 0) return 1;
    if (y % 2) return x * binpow(x, y - 1, mod) % mod;
    int z = binpow(x, y / 2, mod);
    return z * z % mod;
}
void calc(string s, int k){
    string t = s;
    int n = s.length();
    if (k == 1){
        for (int i = 0; i < n; i++){
            t[i] = s[n - i - 1];
        }
    }
    int b = 400 + rand() % 30000;
    vector < int > pr;
    int l = 1e9 + 1e7;
    for (int i = l; pr.size() < 1; i++){
        if (prime(i)) pr.pb(i);
    }
    for (int i = 0; i < n; i++){
        for (int j = 0; j < pr.size(); j++){
            h[i + 1][j] = (h[i][j] * b + t[i]) % pr[j];
        }
    }
    for (int i = 1; i <= n; i++) p[k][i] = 1;
    for (int i = 1; i < n; i++){
      //  cout << i << endl;
        for (int l = 0; l < pr.size(); l++){
            y[l] = binpow(b, i, pr[l]);
            val[l] = y[l];
            sum[l] = 1;
        }
        for (int j = 2 * i; j <= n; j += i){
            for (int l = 0; l < pr.size(); l++){
                sum[l] = (sum[l] + val[l]) % pr[l];
                val[l] = val[l] * y[l] % pr[l];
                if (p[k][j] == 0) continue;
                if (p[k][j - i] == 1 && j != 2 * i) continue;
                int x = (h[j][l] - y[l] * h[j - i][l] % pr[l] + pr[l]) % pr[l];
                int v3 = x * sum[l] % pr[l];
                if (v3 == h[j][l]){
                    p[k][j] = 0;
                    break;
                }
            }
        }
    }
}
