int subh(int l, int r) {
    int b = h[r], s = 0;
    if (l > 0) {
        s = h[l - 1] * pw[r - l + 1] % mod;
    }
    if (b - s < 0) return b - s + mod;
    return b - s;
}

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
