    pw[0] = 1;
    for (int i = 1; i < MAXN; i++) {
        pw[i] = pw[i - 1] * p % mod;
    }
    cin >> s;
    n = s.size();
    h[0] = s[0] - 'a' + 1;
    for (int i = 1; i < n; i++) {
        h[i] = (h[i - 1] * p + s[i] - 'a' + 1) % mod;
    }
    int t = -1;
    for (int i = 1; i < n; i++) {
        if (n % i) continue;
        bool ok = 1;
        for (int j = i; j < n; j += i) {
            if (subh(j, j + i - 1) != subh(0, i - 1)) {
                ok = 0;
                break;
            }
        }
        if (ok) {
            t = i;
            break;
        }
    }
    if (t == -1) {
        cout << "1\n1\n";
        return 0;
    }
    if (t == 1) {
        cout << n << "\n1\n";
        return 0;
    }
    vector<int> bad(n + 1, 0);
    for (int i = 1; i < n; i++) {
        for (int j = i; j + i - 1 < n; j += i) {
            if (subh(0, i - 1) == subh(j, j + i - 1)) {
                bad[j + i] = 1;
            } else {
                break;
            }
        }
    }
    for (int i = 1; i < n; i++) {
        for (int j = n - i - 1; j - i + 1 >= 0; j -= i) {
            if (subh(j - i + 1, j) == subh(n - i, n - 1)) {
                bad[j - i + 1] = 1;
            } else {
                break;
            }
        }
    }
    int ans = 0;
    for (int i = 0; i <= n; i++) {
        ans += !bad[i];
    }
    cout << 2 << "\n" << ans << "\n";
}
