	else {
		cout << 2 << endl;
		string ns;
		for(int i = 0; i < p; i++) ns.push_back(s[i]);
		long long ans = good_pos(ns);
		ans *= len / p;
		if(len / p == 2){
			ans += min_psz(ns) == p;
		}	
		ans %= 1'000'000'007;
		cout << ans << endl;
	}
	return 0;
}

