bool check(string str){
	int n = str.size();
	for(int i=2;i<n;++i){
		if(n%i!=0)continue;
		int d = n / i;
		bool flag = true;
		for(int j=d;j<n;j+=d){
			if(str.substr(0, d)!=str.substr(j, d)){
				flag = false;
				break;
			}
		}
		if(flag)return true;
	}
	return false;
}

bool check_front(int x){
	for(int i=2;i<x;++i){
		if(x%i)continue;
		bool flag = true;
		int d = x / i;
		for(int j=d;j<x;j+=d){
			if(d>front[j-1]){
				flag = false;
			}
		}
		if(flag)return true;
	}
	return false;
}

bool check_back(int x){
	for(int i=2;i<x;++i){
		if(x%i)continue;
		bool flag = true;
		int d = x / i;
		for(int j=d;j<x;j+=d){
			if(d>back[j-1]){
				flag = false;
			}
		}
		if(flag)return true;
	}
	return false;
}

