ll hs(ll s, ll l) {
	ll ha = ra[s+l]-sa[l]*ra[s];
	ll hb = rb[s+l]-sb[l]*rb[s];
	ha = ((ha%MA)+MA)%MA;
	hb = ((hb%MB)+MB)%MB;
	return (ha*MB)+hb;
}
