using namespace std;

vector<int> Zalgorithm(const string &s){
    int n=s.size();
    vector<int> z(n);
    z[0]=n;
    int i=1,j=0;
    while(i<n){
        while(i+j<n&&s[j]==s[i+j]) ++j;
        z[i]=j;
        if (j==0){++i; continue;}
        int k=1;
        while(i+k<n&&k+z[k]<j) z[i+k]=z[k],++k;
        i+=k,j-=k;
    }
    return z;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    string S; cin >> S;
    int bit=0,n=S.size();
    for (auto c:S) bit|=1<<(c-'a');
    if (__builtin_popcount(bit)==1){
        cout << n << '\n' << 1 << '\n';
        return 0;
    }
    vector<int> check(n-1,1);
    int ok=1;
    for (int _=0;_<2;++_){
        vector<int> Z=Zalgorithm(S);
        for (int i=1;i<n;++i){
            if (Z[i]==n-i) ok=0;
            for (int j=2*i;j<Z[i];j+=i){
                check[(!_?j:n-1-j)]=0;
            }
        }
        reverse(S.begin(),S.end());
    }
    if (ok) cout << 1 << '\n' << 1 << '\n';
    else cout << 2 << '\n' << accumulate(check.begin(),check.end(),0) << '\n';
}

