template<class T> struct RMQ {
	vector<vector<T>> dat;
	vector<int> table;

	RMQ(vector<T> a) {
		int n = a.size();
		int m = log2(n * 2 - 1);
		dat.resize(m, vector<T>(n));
		dat[0] = a;
		for (int i = 0; i < m - 1; i++) {
			for (int j = 0; j + (1 << (i + 1)) <= n; j++) {
				dat[i + 1][j] = min(dat[i][j], dat[i][j + (1 << i)]);
			}
		}

		table.resize(a.size() + 1);
		for (int i = 0; (1 << i) < table.size(); i++) {
			table[1 << i] = i;
		}

		for (int i = 1; i < table.size(); i++) {
			table[i] += table[i - 1];
		}
	}

	T query(int l, int r) {
		int k = table[r - l];
		return min(dat[k][l], dat[k][r - (1 << k)]);
	}
};

struct SuffixArray {
	vector<int> sa;
	vector<int> rank;
	vector<int> lcp;

	SuffixArray(string s) {
		int n = s.size();

		sa.resize(n + 1);
		rank.resize((n + 1) * 2, -1);
		lcp.resize(n + 1);

		vector<int> next_rank((n + 1) * 2, -1);

		for (int i = 0; i <= n; i++) {
			sa[i] = i;
			rank[i] = i < n ? s[i] : -1;
		}

		for (int k = 1; k <= n; k *= 2) {
			auto compare = [&](int i, int j) {
				return rank[i] != rank[j] ? rank[i] < rank[j] : rank[i + k] < rank[j + k];
			};
			sort(sa.begin(), sa.end(), compare);
			int r = 0;
			for (int i = 0; i <= n; i++) {
				if (i > 0 && compare(sa[i - 1], sa[i])) r++;
				next_rank[sa[i]] = r;
			}
			swap(rank, next_rank);
		}
		rank.resize(n);

		int h = 0;
		lcp[0] = 0;
		for (int i = 0; i < n; i++) {
			int j = sa[rank[i] - 1];
			if (h > 0) h--;
			while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
			lcp[rank[i] - 1] = h;
		}
	}
};

int main() {
	string s;
	cin >> s;

	int n = s.size();
	if (n > 4000) {
		return 0;
	}

	SuffixArray sa(s);
	RMQ<int> rmq(sa.lcp);

	static bool g[4040][4040];

	for (int i = 0; i < n; i++) {
		for (int j = 1; i + j * 2 <= n; j++) {
			for (int k = i + j; k + j <= n; k += j) {
				int x, y;
				tie(x, y) = minmax(sa.rank[i], sa.rank[k]);
				int lcp = rmq.query(x, y);
				if (lcp >= j) {
					g[i][k + j] = true;
				} else {
					break;
				}
			}
		}
	}

	const long long mod = 1e9 + 7;
