	for (int i = 0; i < 4040; i++) dp[i] = 1e18;

	dp[0] = 0;
	dp2[0] = 1;

	for (int i = 0; i < n; i++) {
		for (int j = i + 1; j <= n; j++) {
			if (g[i][j]) continue;

			if (dp[j] == dp[i] + 1) {
				dp2[j] += dp2[i];
			} else if (dp[j] > dp[i] + 1) {
				dp[j] = dp[i] + 1;
				dp2[j] = dp2[i];
			}
		}
	}

	cout << dp[n] << endl;
	cout << dp2[n] << endl;
}

