pii isgood(string W) {
    int N = W.size();

    bool diff = false;
    for (int i = 1; i < N && !diff; i++) {
        diff |= (W[0] != W[i]); 
    }
    if (!diff) return {N,1};

    for (int i = 2; i < N; i++) {
        if (N % i != 0) continue;
        bool diff = false;
        for (int j = i; j < N && !diff; j+=i) {
            for (int k = 0; k < i && !diff; k++) {
                diff |= W[k] != W[j+k];
            }
        }
        if (!diff) {
            int g = 2*i-4;
            for (int j = 2; j < i; j++) {
                pii a = isgood(W.substr(0,j));
                if (a.x == 1) --g;
            }
            for (int j = 2; j < i; j++) {
                pii a = isgood(W.substr(N-j,N));
                if (a.x == 1) --g;
            }


            if (N/i == 2) {
                return{2, N-1-g};
            } else {
                return{2, N-(N/i)-g}; 
            }
        }
    }
    return {1,1};
}

