char s[500005];
int fail[500005],fail2[500005];
bool can[500005],can2[500005];

int main(){
	fio>>(s+1);
	int n=strlen(s+1);
	fail[1]=0;
	int nf=0;
	for(int i=2;i<=n;i++){
		while(nf&&s[nf+1]!=s[i]){
			nf=fail[nf];
		}
		if(s[nf+1]==s[i]){
			nf++;
		}
		fail[i]=nf;
	}
	if(!fail[n]){
		fio<<"1\n"<<"1\n";
		return 0;
	}
	for(int i=1;i<=n;i++){
		can[i]=(!fail[i]||(i%(i-fail[i])));
	}
	reverse(s+1,s+n+1);
	nf=0;
	fail2[1]=0;
	for(int i=2;i<=n;i++){
		while(nf&&s[nf+1]!=s[i]){
			nf=fail2[nf];
		}
		if(s[nf+1]==s[i]){
			nf++;
		}
		fail2[i]=nf;
	}
	for(int i=1;i<=n;i++){
		can2[i]=(!fail2[i]||(i%(i-fail2[i])));
	}
	int cnt=0;
	for(int i=1;i<=n;i++){
		if(can[i]&&can2[n-i]){
			cnt++;
		}
	}
	if(!cnt){
		fio<<n<<endl<<"1\n";
	}else{
		fio<<"2\n"<<cnt<<endl;
	}
	return 0;
}

