class RollingHash{
	vvl H,P;
	vl B,M;
public:
	RollingHash(str S):H(3,vl(S.size()+1)),P(3,vl(S.size()+1)){
		B={123457,123567,124567};
		M={998242353,MD,e9+9};
		fr(i,3){
			P[i][0]=1;
			fr(j,S.size()){
				H[i][j+1]=(H[i][j]*B[i]+S[j])%M[i];
				P[i][j+1]=(P[i][j]*B[i])%M[i];
			}
		}
	}
	vl operator()(int l,int r){
		vl v;
		fr(i,3){
			v<<(H[i][r]-H[i][l]*P[i][r-l]%M[i]+M[i])%M[i];
		}
		return v;
	}
};

