const int maxn = 1e6 + 5;




struct string_hasher {
  const ll mod = 1e9 + 7;
  const ll prime = 31;
  string s; int n;
  vector<ll> H, P;
  string_hasher() {}
  void init(string s) {
    this->s = s;
    assert(s.front() == '*'); // string must be given as 1-indexed!!
    this->n = s.length(); this->n--;
    H.resize(n+10);
    P.resize(n+10);
    P[0] = 1;
    for (int i=1; i<=n; i++) {
      P[i] = prime*P[i-1];
      P[i] %= mod;
    }
    for (int i=1; i<=n; i++) {
      H[i] = H[i-1] + P[i]*(s[i]-'a');
    }
  }

  ll get(int l, int r) {
    assert(l>=1 && r>=1 && l<=n && r<=n);
    return ((H[r] - H[l-1]) + mod) % mod;
  }

  // Check if s[l1..r1] == s[l2...r2]. Assumes substr2 starts ahead of substr1.
  ll substr_equal(ll l1, ll r1, ll l2, ll r2) {
    assert(r1>=l1 && r2>=l2 && l2>=l1);
    ll h1 = get(l1,r1);
    ll h2 = get(l2,r2);

    h1 *= P[l2-l1]; h1 = ((h1%mod)+mod)%mod;
    return ((h1-h2)%mod) == 0;
  }
};


string s; int n;
string_hasher H;
bool badl[maxn], badr[maxn];

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

  cin>>s; n = s.length();

  s = "*" + s;
  H.init(s);

  {

    int minp = n;
    for (int l=1; l<n; l++) {
      if (n%l) continue;
      bool bad = true;
      for (int j=1; j<=n; j++) {
	if (s[j-1+1] != s[((j-1)%l)+1]) {
	  bad = false;
	}
      }
      if (bad) {
	minp = l; break;
      }
    }

    if (minp == n) {
      // s isn't periodic
      cout<<1<<endl;
      cout<<1<<endl;
      return 0;
    }

    if (minp == 1) {
      //aaaa
      cout<<n<<endl;
      cout<<1<<endl;
      return 0;
    }
  }



  for (int l=1; l<n; l++) {
    if (n%l) continue;
    int x0=1; int y0=l;
    for (int i=l+1; i+l-1<=n; i+=l) {
      if (H.substr_equal(x0,y0,i,i+l-1)) {
	badl[i+l-1] = true;
      } else {
	break;
      }
    }
  }

  for (int l=1; l<n; l++) {
    int x0=n-l+1; int y0=n;
    for (int i=n-l; i-l+1>=1; i-=l) {
      if (H.substr_equal(i-l+1,i,x0,y0)) {
	badr[i-l+1] = true;
      } else {
	break;
      }
    }
  }

  cout<<2<<endl;
  int ans = 0;
  for (int i=1; i<n; i++) {
    if (!badl[i] && !badr[i+1]) {
      ans++;
    }
  }
  cout<<ans<<endl;  

  return 0;
}

