  void solve(vector<int>& v, string& s){
    int l = s.size(), i = 1, j = 0, k;
    v.resize(l);
    if(l < 1) return;
    v[0] = l;
    while (i < l) {
      while (i+j < l && s[j] == s[i+j]) ++j;
      v[i] = j;
      if (j == 0) { ++i; continue;}
      k = 1;
      while (i+k < l && k+v[k] < j) v[i+k] = v[k], ++k;
      i += k; j -= k;
    }
  }
