vector<int> KMP(string s) {
  int n = s.size();
  vector<int> kmp(n + 1), mp(n + 1);
  kmp[0] = mp[0] = -1;
  int j = -1;
  for(int i = 0; i < n; i++) {
    while(j >= 0 && s[i] != s[j]) j = kmp[j];
    kmp[i + 1] = mp[i + 1] = ++j;
    if(s[i] == s[j - 1]) kmp[i + 1] = kmp[j];
  }
  return mp;
}

vector<int> cycle(string s) {
  auto mp = KMP(s);
  vector<int> len(s.size());
  for(int i = 0; i < (int) s.size(); i++)
    len[i] = i + 1 - mp[i + 1];
  return len;
}

int main() {
