vector<int> build_lps(string p) {
    int sz = p.size();
    vector<int> lps;
    lps.assign(sz + 1, 0);
    int j = 0;
    lps[0] = 0;
    for(int i = 1; i < sz; i++) {
        while(j >= 0 && p[i] != p[j]) {
            if(j >= 1) j = lps[j - 1];
            else j = -1;
        }
        j++;
        lps[i] = j;
    }
    return lps;
}
inline int min_rep(int lps, int len) {
	if (lps % (len - lps) == 0) return len - lps;
	return len;
}
int32_t main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    string s; cin >> s;
    int n = s.size();
    auto lps = build_lps(s);
    int cur = min_rep(lps[n - 1], n);
    if (cur == 1) return cout << n << '\n' << 1 << '\n', 0;
    if (cur == n) return cout << 1 << '\n' << 1 << '\n', 0;
    cout << 2 << '\n';
    int ans = n - n / cur + 1;
    cout << ans << '\n';
    return 0;
}

