	FOR(i,2,n) {
		int j = nxt[i-1];
		for (; j > 0 && s[j+1] != s[i]; j = nxt[j]);
		if (s[j+1] == s[i]) nxt[i] = j+1; else nxt[i] = 0;

		j = nxt2[i-1];
		for (; j > 0 && s[n+1-(j+1)] != s[n+1-i]; j = nxt2[j]);
		if (s[n+1-(j+1)] == s[n+1-i]) nxt2[i] = j+1; else nxt2[i] = 0;
