  if (count(begin(s), end(s), s[0]) == n) return cout << n << "\n1\n", 0;

  init(n);
  RollingHash rh(begin(s), end(s));
  auto chk = [&](int l, int r) -> bool {
    auto mp = factorize(r - l);
    for (const auto& e : mp) {
      int d = (r - l) / e.first;
      if (rh.get(l, r - d) == rh.get(l + d, r)) return false;
    }
    return true;
  };

  if (chk(0, n)) return cout << "1\n1\n", 0;

  int res = 0;
  for (int i = 1; i < n; ++i) {
    res += chk(0, i) and chk(i, n);
  }
  cout << "2\n" << res << '\n';
}

