struct Hash{
    ll x;
    ll inq(ll a, ll q, ll mod)
    {
        if (q == 0) return 1;
        ll l = inq(a, q / 2, mod);
        if (q % 2) return l * l % mod * a % mod;
        return l * l % mod;
    }
    Hash operator = (Hash b)
    {
        x = b.x;
        return x;
    }
    bool operator == (Hash b)
    {
        return x == b.x;
    }
    Hash operator + (Hash b)
    {
        long long y = x + b.x;
        if (y >= MOD) y -= MOD;
        return y;
    }
    Hash operator * (Hash b)
    {
        long long y = x * b.x;
        if (y >= MOD) y %= MOD;
        return y;
    }
    Hash operator - (Hash b)
    {
        long long y = x - b.x;
        if (y < 0) y += MOD;
        return y;
    }
    Hash operator / (Hash b)
    {
        long long y = x * inq(b.x, MOD - 2, MOD);
        if (y >= MOD) y %= MOD;
        return y;
    }
    Hash operator + (int a)
    {
        int y = x + a;
        while (y >= MOD) y -= MOD;
        return y;
    }
    Hash operator + (long long a)
    {
        long long y = x + a;
        if (y >= MOD) y %= MOD;
        return y;
    }
    Hash operator - (int a)
    {
        int y = x - x;
        while (y < 0) y += MOD;
        return y;
    }
    Hash operator - (long long a)
    {
        long long y = x - x;
        if (y < 0) y = (y + MOD * MOD) % MOD;
        return y;
    }
    Hash operator * (long long a)
    {
        long long y = x * a;
        if (y >= MOD) y %= MOD;
        return y;
    }
    Hash (int x_)
    {
        x = x_;
    }
    Hash ()
    {
        x = 0;
    }
};

ostream& operator << (ostream& out, Hash& a)
{
    out << a.x;
}

istream& operator >> (istream& in, Hash& a)
{
