const int N = 5e5 + 10;
const int MOD = 1e9 + 7;

int n;
int has[N], powe[N];
bool pre[N], suff[N];
string s;

int getm(int l, int r)  {
    int res = (has[r] - has[l - 1] * powe[r - l + 1] * 1ll % MOD + 1ll*MOD*MOD) % MOD;
    return res;
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> s;
    char rem = s[0]; bool flag = false;
    for(int i = 0; i < s.length(); ++i) if(s[i] != rem) flag = true;
    if(!flag)   {
        cout << s.length() << '\n' << "1";
        return 0;
    }

    for(int i = 1; i <= s.length(); ++i)  has[i] = (has[i - 1] * 26 + s[i - 1] - 'a') % MOD;

    powe[0] = 1ll;
    for(int i = 1; i <= s.length(); ++i)    powe[i] = powe[i - 1] * 26 % MOD;

    // check prefix
    for(int i = 1; i <= s.length(); ++i)   if(!pre[i]){
        int cur = getm(1, i);
        for(int idem = 2; i * idem <= s.length(); ++idem) {
            int tmp = getm(i*idem - i + 1, i*idem);
            if(tmp != cur) break;
            pre[idem*i] = true;
        }
    }
//cout << getm(1, 2) << ' ' << getm(3, 4) << '\n';
    for(int i = s.length(); i >= 1; --i)    {
        int cur = getm(i, s.length());
        int dem = s.length() - i + 1;
        for(int idem = 2; idem * dem <= s.length(); ++idem) {
            int tmp = getm(s.length() - dem*idem + 1, s.length() - dem*(idem - 1));
            if(tmp == cur) suff[s.length() - dem*idem + 1] = true;
            else break;
        }
    }
   // cout << pre[s.length()] << '\n';
    if(pre[s.length()] == false)    {
        cout << "1\n1";
    }else {
        cout << "2\n";
        int idem = 0;
        for(int i = 1; i < s.length(); ++i) if(pre[i] == false && suff[i + 1] == false) idem ++;
        cout << idem;
    }
}

