using namespace std;

char A[500050]; int F[500050];
bool cut[500050];

int main()
{
	scanf("%s", A);
	int l = 0; while (A[l]) l++;
	int k = -1; F[0] = -1;
	for (int i=1;i<l;i++){
		while (k >= 0 && A[k+1] != A[i]) k = F[k];
		if (A[k+1] == A[i]) k++;
		F[i] = k;
	}

	if (F[l-1] == l-2){
		printf("%d\n%d\n", l, 1);
	}
	else{
		bool good = 1;
		for (int i=F[l-1];i>=0;i=F[i]){
			int p = l-1 - i;
			if (l % p == 0){
				if (p*2 != l) for (int j=p;j<=l;j+=p) cut[j] = 1;
				good = 0;
			}
		}

		if (good) printf("1\n1\n");
		else{
			int ans = 0;
			for (int i=1;i<l-1;i++) if (F[i] != -1){
				int p = i - F[i];
				if ((i + 1) % p == 0) cut[i+1] = 1;
			}
			reverse(A,A+l);

			int k = -1; F[0] = -1;
			for (int i=1;i<l;i++){
				while (k >= 0 && A[k+1] != A[i]) k = F[k];
				if (A[k+1] == A[i]) k++;
				F[i] = k;
			}
			for (int i=1;i<l-1;i++) if (F[i] != -1){
				int p = i - F[i];
				if ((i + 1) % p == 0) cut[l-i] = 1;
			}

			for (int i=1;i<l;i++) if (!cut[i]) ans++;

			printf("%d\n%d\n", 2, ans);
		}
	}
	return 0;
}

