template<typename InIt>
std::vector<usize> mp(const InIt first, const InIt last)
{
    const usize sz = std::distance(first, last);
    std::vector<usize> A(sz + 1, sz);
    for (usize i = 0, j = sz; i < sz; i++) {
        while (j != sz and *(std::next(first, i)) != *(std::next(first, j))) { j = A[j]; }
        j = (j == sz ? 0 : j + 1), A[i + 1] = j;
    }
    return A;
}
