            p[i]++;
    }

    int per = n - p[n - 1];

    if (n == per || n % per) {
        cout << "1\n1";
    }
    else if (per == 1) {
        cout << n << "\n1";
    }
    else if (n / per == 2) {
        cout << "2\n" << n - 1;
    }
    else {
        cout << "2\n" << n - 1 - n / per + 1;
    }

    return 0;
}

