struct RollingHash {
	typedef unsigned long long ull;
	const unsigned base = 1000000007U;
	vector<ull> tpow, thash;

	template<class T>
	void init(const T s, const int _size) {
		tpow.resize(_size + 1);
		thash.resize(_size + 1);
		tpow[0] = 1, thash[0] = 0;
		for (int i = 0; i < _size; ++i) {
			tpow[i + 1] = tpow[i] * base;
			thash[i + 1] = s[i] + thash[i] * base;
		}
	}
	// return range[l, r]
	ull range(int l, int r) const { return thash[r] - thash[l - 1] * tpow[r - l + 1]; }
};

