	exit(0);
}

void calc(int Z[], int G[]) {
	int L = -1, R = -1;
	for (int i = 1; i < n; ++i) {
		if (R < i) {
			L = R = i; while(R < n && w[R] == w[R - L]) ++R;
			Z[i] = R - L; --R;
		} else {
			int k = i - L;
			if (Z[k] < R - i + 1) Z[i] = Z[k];
			else {
				L = i; while(R < n && w[R] == w[R - L]) ++R;
				Z[i] = R - L; --R;
			}
		}
	}

	for (int i = 0; i < n; ++i) G[i] = true;
	for (int i = 1; i < n; ++i) {
		for (int j = i + i; j <= Z[i] + i; j += i) G[j - 1] = false;
	}
}

