// z[i] = len of lcp of s, s[i..]; lcp(longest common prefix)
vector<int> z_fn(const string& s) {
    int n = s.size();
    vector<int> z(n, 0);
    for (int i = 1, l = 0, r = 0; i < n; i++) {
        if (i <= r)
            z[i] = min(r-i+1, z[i-l]);
        while (i+z[i] < n && s[z[i]] == s[i+z[i]]) {
            z[i]++;
        }
        if (i+z[i]-1 > r) {
            l = i; r = i+z[i]-1;
        }
    }
    return z;
}

int min_period(const vector<int>& z) {
    int n = z.size();
    for (int i = 1; i <= n/2; i++) {
        if (n%i) continue;
        if (z[i] == n-i) return i;
    }
    return n;
}

void solve() {
    string s; cin >> s;
    auto z = z_fn(s);
    int n = s.size();
    int period = min_period(z);
    if (period == 1) {
        cout << n << "\n1"; return;
    }
    if (period == n) {
        cout << "1\n1"; return;
    }

    vector<bool> pre(n+1, true), suf(n+1, true);
    for (int p = 1; p < n; p++) {
        if (!pre[p]) continue;
        for (int k = 2; (k-1)*p <= z[p]; k++) {
            pre[k*p] = false;
        }
    }
    reverse(s.begin(), s.end());
    auto y = z_fn(s);
    for (int p = 1; p < n; p++) {
        if (!suf[p]) continue;
        for (int k = 2; (k-1)*p <= y[p]; k++) {
            suf[k*p] = false;
        }
    }
    int cnt = 0;
    for (int i = 1; i < n; i++) {
        if (pre[i] && suf[n-i]) cnt++;
    }
    assert(cnt);
    cout << "2\n" << cnt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    cout << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int KEY = 61;

int ADD(int x, int y) {
  int res = (x + y) % MOD;
  if (res < 0) res += MOD;
  return res;
}

int MUL(int x, int y) {
  int res = 1ll * x * y % MOD;
  if (res < 0) res += MOD;
  return res;
}

int power(int n, int x) {
  if (x == 0) {
    return 1;
  }
  int res = power(n, x / 2);
  res = MUL(res, res);
  if (x & 1) {
    res = MUL(res, n);
  }
  return res;
}

int inverse(int n) {
  return power(n, MOD - 2);
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  string s;
  cin >> s;
  int n = s.size();

  // the number of elements is either 1, 2, or n (if all characters are the same)
  // if prefix(n - 1) is periodic, and suffix(n - 1) is periiodic, then all characters are the same


  vector<int> Hash(n); // string hashing
  for (int i = 0; i < s.size(); i++) {
    if (i > 0) Hash[i] = Hash[i - 1];
    Hash[i] += MUL((s[i] - 'a' + 1), power(KEY, i));
  }

  auto GetHash = [&Hash](int i, int j) {
    int seg = Hash[j];
    if (i > 0) {
      seg = ADD(seg, -Hash[i - 1]);
    }
    seg = MUL(seg, inverse(power(KEY, i)));
    return seg;
  };

  vector<int> goodPrefix(n, 1); // the prefix i of string s is good (there is no period)
  vector<int> goodSuffix(n, 1); // the suffix i of string s is good (there is no period)

  for (int d = 1; d <= n; d++) {
    int Key = GetHash(0, d - 1);
    bool stat = true;
    for (int i = d; i + d - 1 < n; i += d) {
      if (GetHash(i, i + d - 1) != Key) {
        break;
      }
      goodPrefix[i + d - 1] = 0;
    }
  }

  for (int d = 1; d <= n; d++) {
    int Key = GetHash(n - d, n - 1);
    for (int i = n - d - 1; i - d + 1 >= 0; i -= d) {
      if (GetHash(i - d + 1, i) != Key) {
        break;
      }
      goodSuffix[i - d + 1] = 0;
    }
  }

  if (goodPrefix[n - 1]) { // length n is good
    cout << 1 << "\n";
    cout << 1 << "\n";
    return 0;
  }

  int cnt = 0; // count number of 2-element goods
  for (int i = 0; i + 1 < n; i++) {
    if (goodPrefix[i] && goodSuffix[i + 1]) {
      cnt++;
    }
  }
  if (cnt > 0) {
    cout << 2 << "\n";
    cout << cnt << "\n";
    return 0;
  }

  // all elements are the same, only 1 possibility

  cout << n << "\n";
  cout << 1 << "\n";
  return 0;
}

