vector<int> getpr(string s) {
	int n = s.length();
	vector<int> p(n);
	for (int i = 1; i < n; ++i) {
		//int j = p[i - 1];
		p[i] = p[i - 1];
		while (p[i] && s[i] != s[p[i]]) p[i] = p[p[i] - 1];
		if (s[i] == s[p[i]])  ++p[i];
	}
	return p;
}

pair<int, int> fastsolve(string s) {
	int n = s.length();
	vector<int> p = getpr(s);
	reverse(s.begin(), s.end());
	vector<int> p2 = getpr(s);
	reverse(s.begin(), s.end());

	int k = n - p[n - 1];
	if (k != n && n % k == 0) {
		if (k == 1) return make_pair(n, 1);
		int cnt = 0;
		for (int i = 1; i <n; i++) {
			bool ok = 1;
			int len = i;
			int per = len - p[len - 1];
			if (len % per == 0 && len != per) {
				ok = 0;
			}

			len = n - i;
			per = len - p2[len - 1];
			if (len % per == 0 && len != per) {
				ok = 0;
			}

			if (ok) cnt++;
		}
		return make_pair(2, cnt);
	}
	else {
		return make_pair(1, 1);
	}
}

bool ok(string s) {
	int n = s.length();
	for (int len = 1; len < n; len++) if (n % len == 0) {
		bool ok = 0;
		for (int i = 0; i + len < n; i++) ok |= s[i] != s[i + len];
		if (!ok) return 0;
	}
	return 1;
}

pair<int, int> slowsolve(string s) {
	int n = s.length();
	vector<int> dp(n + 1, INF);
	vector<int> cnt(n + 1, 0);
	dp[0] = 0;
	cnt[0] = 1;
	for (int i = 0; i < n; i++) {
		string cur = "";
		for (int j = i; j < n; j++) {
			cur += s[j];
			if (ok(cur)) {
				if (dp[j + 1] > dp[i] + 1) {
					dp[j + 1] = dp[i] + 1;
					cnt[j + 1] = 0;
				}
				if (dp[j + 1] == dp[i] + 1) {
					cnt[j + 1] = (cnt[j + 1] + cnt[i]) % MOD;
				}
			}
		}
	}
	return make_pair(dp[n], cnt[n]);
}

