    cin.tie(0);
    cin>>w;
    int n=w.size();
    initDict();
    vector<Hash> h(n+1);
    vector<Hash> powA(n+1);
    h[0]=0;
    powA[0]=1;
    for(int i=0;i<n;i++){
        h[i+1]=(h[i]*A+dict[w[i]])%MOD;
        powA[i+1]=(powA[i]*A)%MOD;
    }

    vector<vector<int>> divisor(n+1);
    for(int i=1;i<=n;i++){
        for(int j=i;j<=n;j+=i){
            divisor[j].push_back(i);
        }
    }

    auto getHash=[&](int l,int r){
        return ((h[r]-(h[l]*powA[r-l])%MOD)%MOD+MOD)%MOD;
    };
    auto repeat=[&](Hash x,int len,int k){
        Hash res=0;
        Hash xA=powA[len];
        for(int i=0;i<21;i++){
            if((k>>i)&1){
                res=(res*xA)%MOD+x;
                res%=MOD;
            }
            x=(x*xA)%MOD+x;
            x%=MOD;
            xA*=powA[len];
            xA%=MOD;
        }
        return res;        
    };
    auto isGood=[&](int l,int r){
        //cerr<<l<<" "<<r<<endl;
        for(int k=0;k+1<divisor[r-l].size();k++){
            Hash x=getHash(l,l+divisor[r-l][k]);
            Hash rx=repeat(x,divisor[r-l][k],(r-l)/divisor[r-l][k]);
            //cerr<<(ll)(getHash(l,r))<<" "<<(ll)(rx)<<endl;
            bool res=(rx!=getHash(l,r));
            if(!res) return false;
        }
        return true;
    };
    int cnt=0;
    for(int i=0;i<n;i++){
        //divide[0,i) (i,n)
        bool isokl=isGood(0,i);
