class RollingHash {
public:
  using ull = unsigned long long;
  using pull = pair<ull, ull>;
  const ull B1 = 100000007;
  const ull B2 = 103;

  int n;
  string s;
  vector<pull> hash;
  vector<ull> Bpower1;
  vector<ull> Bpower2;

  RollingHash(string s) :s(s), n(s.size()) {
    hash.resize(n + 1); Bpower1.resize(n + 1); Bpower2.resize(n + 1);
    Bpower1[0] = Bpower2[0] = 1;
    for (int i = 0; i < n; i++) {
      hash[i + 1].first = hash[i].first * B1 + s[i];
      hash[i + 1].second = hash[i].second * B2 + s[i];
      Bpower1[i + 1] = Bpower1[i] * B1;
      Bpower2[i + 1] = Bpower2[i] * B2;
    }
  }

  //S[l, r)
  pull part(int l, int r) {
    pull res = hash[r];
    res.first -= hash[l].first * Bpower1[r - l];
    res.second -= hash[l].second * Bpower2[r - l];
    return res;
  }
};


int main() {
  string s;
  cin >> s;
  int n = s.size();
  assert(n <= 4000);

  RollingHash rh(s);
  int mlen = inf;
  vi out(n + 1);
  for (int len = 1; len < n; len++) {
    if (n % len != 0) continue;
    auto h = rh.part(0, len);
    bool flag = true;
    for (int l = len; l < n; l += len) {
      if (rh.part(l, l + len) != h) {
        flag = false;
        break;
      }
      out[l + len] = true;
    }
    if (flag) {
      mlen = len;
      break;
    }
  }

  for (int len = 1; len < n; len++) {
    if (n % len != 0) break;
    auto h = rh.part(n - len, n);
    for (int l = n - 2*len; l >= 0; l -= len) {
      if (rh.part(l, l + len) != h) break;
      out[l] = true;
    }
  }

  if (mlen == inf) {
    cout << 1 << endl;
    cout << 1 << endl;
    return 0;
  }
  else if (mlen == 1) {
    cout << n << endl;
    cout << 1 << endl;
    return 0;
  }
  else {
    cout << 2 << endl;
    int cnt = 0;
    for (int i = 1; i < n; i++) {
      if (!out[i]) cnt++;
    }
    cout << cnt << endl;
  }
}

