			fill(leok, leok + m + 1, true);
			fill(riok, riok + m + 1, true);
			rep1(i, m) {
				if (lesk[i])continue;
				else {
					int le = 0, ri = i;
					while (ri + i <= m) {
						bool valid = true;
						rep(j, i) {
							if (s[le + j] != s[ri + j]) {
								valid = false; break;
							}
						}
						if (valid) {
							ri += i; le += i;
							leok[ri] = false;
							lesk[ri] = true;
						}
						else {
							lesk[ri] = true;
							break;
						}
					}
				}
			}
			rep1(i, m) {
				if (risk[m - i])continue;
				else {
					int le = m - i, ri = m;
					while (le - i >= 0) {
						bool valid = true;
						rep(j, i) {
							if (s[le + j] != s[le + j - i]) {
								valid = false; break;
							}
						}
						if (valid) {
							le -= i; ri -= i;
							riok[le] = false;
							risk[le] = true;
						}
						else {
							risk[le] = true;
							break;
						}
					}
				}
			}
			int cnt = 0;
			int r = n / m;
			cnt += (r - 2)*(m - 1);
			if (r == 2)cnt++;
			rep1(i, m - 1) {
				if (leok[i])cnt++;
			}
			rep1(i, m - 1) {
				if (riok[i])cnt++;
			}
			cout << 2 << endl;
			cout << cnt << endl;
		}
	}
	//stop
	return 0;
}

