pair<ll, ll> query(int i, int j) {
    return make_pair((H[0][j] - H[0][i-1]*pB[0][j-i+1]%M[0] + M[0]) % M[0],
                     (H[1][j] - H[1][i-1]*pB[1][j-i+1]%M[1] + M[1]) % M[1]);
}

void solve() {
    int L = (int)w.size();
