        H[i][0] = 0;
        pB[i][0] = 1;
        for (int j = 1; j <= L; j++) {
            H[i][j] = (H[i][j-1] * B[i] + w[j-1]) % M[i];
            pB[i][j] = pB[i][j-1] * B[i] % M[i];
        }
