		if (f) {
			for (int j = i; j < w.size(); j += i) {
				if (!cut[j]) cut[j] = true, cnt++;

			}
		}
	}

	if (cnt == w.size() - 1) printf("%d\n%d\n", w.size(), 1);
	else if (cnt == 0) printf("%d\n%d\n", 1, 1);
	else {
		FOR(i, 1, w.size()) if (!cut[i]) cnt++;
		printf("%d\n%d\n", 2, cnt);
	}
	return 0;
}

