class Solve
{
  string w;
  int n;
  int ans;
  MP<string> mp, mp_rev;

public:
  Solve() : ans{0}
  {
    cin >> w;
    n = w.size();
    mp = MP<string>{w};
    reverse(w.begin(), w.end());
    mp_rev = MP<string>{w};
    reverse(w.begin(), w.end());
  }

  void flush()
  {
    if (all_of(w.begin(), w.end(), [&](auto c) { return c == w[0]; }))
    {
      cout << n << endl;
      cout << 1 << endl;
    }
    else if (is_good(mp, n))
    {
      cout << 1 << endl;
      cout << 1 << endl;
    }
    else
    {
      for (auto i{1}; i < n; ++i)
      {
        if (is_good(mp, i) && is_good(mp_rev, n - i))
        {
          ++ans;
        }
      }
      cout << 2 << endl;
      cout << ans << endl;
    }
  }

private:
  bool is_good(MP<string> const &mp, int s)
  {
    auto p{mp.period(s)};
    return p == s || s % p != 0;
  }
};

