int main() {
  string s;
  cin >> s;
  if (all_of(s.begin(), s.end(), [&](char c) { return c == s[0]; })) {
    cout << s.size() << "\n";
    cout << "1\n";
    return 0;
  }
  int n = s.size();
  constexpr int kP = 1'000'000'000 + 123;
  constexpr int kQ = 7122;
  vector<int> hv(n), pw(n + 1, 1);
  for (int i = 1; i <= n; ++i) pw[i] = 1LL * pw[i - 1] * kQ % kP;
  hv[0] = s[0];
  for (int i = 1; i < n; ++i) hv[i] = (1LL * hv[i - 1] * kQ + s[i]) % kP;

  vector<int> is_cyclic(n);

  auto GetHash = [&](int p, int k) {
    if (p == 0) return hv[p + k - 1];
    return (int)((hv[p + k - 1] + kP - 1LL * pw[k] * hv[p - 1] % kP) % kP);
  };

  for (int k = 1; k <= n; ++k) {
    int h = hv[k - 1]; 
    for (int j = k; j <= n; j += k) {
      is_cyclic[j - 1]++;
      if (j + k <= n && GetHash(j, k) != h) break;
    }
  }

  if (is_cyclic[n - 1] == 1) {
    cout << "1\n";
    cout << "1\n";
    return 0;
  }

  vector<int> suffix(n);
  for (int k = 1; k <= n; ++k) {
    int h = GetHash(n - k, k);
    for (int j = n - k; j >= 0; j -= k) {
      suffix[j]++;
      if (j >= k && GetHash(j - k, k) != h) break;
    }
  }
  int ans = 0;
  for (int i = 0; i + 1 < n; ++i) {
    if (is_cyclic[i] == 1 && suffix[i + 1] == 1) ans++;
  }
  assert(ans > 0);
  cout << "2\n";
  cout << ans << "\n";
  return 0;
}

