/*
文字列の長さが n、最小周期が p です。
p = n なら、(1,1) です。
p = 1 なら、(n,1) です。
それ以外は、(2, k*(p-1) + (k==2)) です。（n=kp）
*/

#include "bits/stdc++.h"
using namespace std;
const int N = 5e5 + 5;
const int mod1 = 1e9 + 7;
const int mod2 = 1e9 + 9;
const int base = 33;
struct num{
    int a , b;
    num(){
        a = 0;
        b = 0;
    }
    num(int _a , int _b){
        a = _a;
        b = _b;
    }
    inline num operator + (const num &other) const {
        num res;
        res.a = a + other.a;
        res.b = b + other.b;
        res.a -= (res.a >= mod1) * mod1;
        res.b -= (res.b >= mod2) * mod2;
        return res;
    }
    inline num operator * (const num &other) const {
        num res;
        res.a = (1LL * a * other.a) % mod1;
        res.b = (1LL * b * other.b) % mod2;
        return res;
    }
    inline num operator - (const num &other) const {
        num res;
        res.a = a - other.a;
        res.b = b - other.b;
        res.a += (res.a < 0) * mod1;
        res.b += (res.b < 0) * mod2;
        return res;
    }
    inline bool operator == (const num &other) const {
        return make_pair(a , b) == make_pair(other.a , other.b);
    }
};
int n;
char str[N];
vector < int > v[N];
num arr[N];
num pw[N];
num inv[N];
int power(int a , int b , int mod){
    int res = 1;
    while(b){
        if(b & 1){
            res = (1LL * res * a) % mod;
        }
        a = (1LL * a * a) % mod;
        b >>= 1;
    }
    return res;
}
void pre(){
    for(int i = 1 ; i <= n ; ++i){
        for(int j = i + i ; j <= n ; j += i){
            v[j].emplace_back(i);
        }
    }
    pw[0] = num(1 , 1);
    for(int i = 1 ; i <= n ; ++i){
        pw[i] = pw[i - 1] * num(base , base);
    }
    arr[0] = num(0 , 0);
    for(int i = 1 ; i <= n ; ++i){
        arr[i] = arr[i - 1] + num(str[i] - 'a' + 1 , str[i] - 'a' + 1) * pw[i];
    }
    num tmp = num(power(base , mod1 - 2 , mod1) , power(base , mod2 - 2 , mod2));
    inv[0] = num(1 , 1);
    for(int i = 1 ; i <= n ; ++i){
        inv[i] = inv[i - 1] * tmp;
    }
}
num get(int l , int r){
    return arr[r] - arr[l - 1];
}
bool ok(int l , int r , int d){
    return get(l , r - d) == get(l + d , r);
}
bool check(int l , int r){
    for(int d : v[r - l + 1]){
        if(ok(l , r , d)){
            return 0;
        }
    }
    return 1;
}
