int ADD(int x, int y) {
  int res = (x + y);
  if (res < 0) res += MOD;
  if (res >= MOD) res -= MOD;
  return res;
}

int MUL(int x, int y) {
  int res = 1ll * x * y % MOD;
  if (res < 0) res += MOD;
  return res;
}

int power(int n, int x) {
  if (x == 0) {
    return 1;
  }
  int res = power(n, x / 2);
  res = MUL(res, res);
  if (x & 1) {
    res = MUL(res, n);
  }
  return res;
}

int inverse(int n) {
  return power(n, MOD - 2);
}

