struct Hash {
    vector<pair<ll, ll> > vh;
    vector<ll> h1_inv, h2_inv;

    Hash(string &w) {
        vh.resize(w.size(), make_pair(0LL, 0LL));
        ll h1 = 1, h2 = 1;
        for (int i = vh.size()-1; i >= 0; --i) {
            if (i != vh.size()-1) vh[i] = vh[i+1];
            vh[i].first = add(mul(w[i], h1), vh[i].first);
            vh[i].second = add(mul(w[i], h2), vh[i].second);
            h1 = mul(h1, hash1);
            h2 = mul(h2, hash2);
        }

        h1_inv.push_back(1); h2_inv.push_back(1);
        ll ih1 = mod_exp(hash1, mod-2);
        ll ih2 = mod_exp(hash2, mod-2);
        for (int i = 0; i < vh.size(); ++i) {
            h1_inv.push_back(mul(ih1, h1_inv.back()));
            h2_inv.push_back(mul(ih2, h2_inv.back()));
        }
    }

    pair<ll, ll> hash(int l, int r) {
        pair<ll, ll> ret = vh[l];
        if (r != vh.size()) ret = ret - vh[r];
        ret.first = mul(ret.first, h1_inv[vh.size()-r]);
        ret.second = mul(ret.second, h2_inv[vh.size()-r]);

        return ret;
    }

    bool is_good(int l, int r) {
        int sz = r - l;
        for (int i = 1; i < sz; ++i)
            if (sz % i == 0 && hash(l, r-i) == hash(l+i, r)) return 0;

        return 1;
    }
};


