bool check(string str){
	int n = str.size();
	for(int i=2;i<n;++i){
		if(n%i!=0)continue;
		int d = n / i;
		bool flag = true;
		for(int j=d;j<n;j+=d){
			if(str.substr(0, d)!=str.substr(j, d)){
				flag = false;
				break;
			}
		}
		if(flag)return true;
	}
	return false;
}

