typedef long long ll;

ll MOD = (1ll << 61) - 1;
ll BIT31 = (1ll << 31) - 1;
ll BIT30 = (1ll << 30) - 1;

ll mod_p(ll x,ll y){
        return (x + y + MOD) % MOD;
}
ll mod_m(ll x,ll y){
        ll xd = x & BIT31;
        ll xu = (x >> 31);
        ll yd = y & BIT31;
        ll yu = (y >> 31);
        ll mid = xu * yd + yu * xd;
        ll midd = mid & BIT30;
        ll midu = (mid >> 30);
        ll tmp = midu + (midd << 31);
        return ((xu * yu * 2) % MOD + tmp % MOD + xd * yd % MOD) % MOD;
}

ll mod_pow(ll x, ll t){
        if(t == 0) {
                return 1;
        }else if(t % 2 == 0){
                ll tmp = mod_pow(x, t/2);
                return mod_m(tmp, tmp);
        }else{
                ll tmp = mod_pow(x, t/2);
                return mod_m(mod_m(tmp, tmp), x);
        }
}

ll mod_inv(ll x){
        return mod_pow(x, MOD - 2);
}

vll basepow(1e6+1);
vll basepowinv(1e6+1);

