        REP(i,2,1e6){
                basepow[i] = mod_m(basepow[i-1], basepow[1]);
                basepowinv[i] = mod_m(basepowinv[i-1], basepowinv[1]);
        }
}

vll f(string s){
        vll ans;
        ll n = s.size();
        vll ms(n+1);
        ms[0] = 0;
        REP(i,1,n){
                ms[i] = mod_p(ms[i-1], mod_m(s[i-1] - 'a' + 1, basepow[i]));
        }
        REP(i,1,n){
                ll cur = i;
                ll tmp = ms[i];
                while(cur + i<= n){
                        ll nx = mod_m(mod_p(ms[cur + i], -ms[cur]), basepowinv[cur]);
                        cur += i;
                        if(tmp == nx){
                                ans.push_back(cur);
                        }else{
                                break;
                        }
                }
        }
        return ans;
}

