    if (len > 1 && len % v == 0 && len != v) continue;
    int len2 = (n-1)-(i+1)+1, v2 = len2 - p2[n-1-i-1];
    //cout << i << " " << len2 << " " << v2 << endl;
    if (len2 > 1 && len2 % v2 == 0 && len2 != v2) continue;
    ans++;
  }
  cout << k << " " << ans << endl;
}

