vector <int> kmp(string str) {
	vector <int> f(str.size(), 0);
	for(int i = 1; i < str.size(); i++) {
		int j = f[i - 1];
		while(j && str[j] != str[i]) {
			j = f[j - 1];
		}
		f[i] = j + (str[i] == str[j]);
	}
	return f;
}

