vector<int> prefix_function(string s) {
	int n = s.size();
	vector<int> pi(n);
	for (int i=1; i<n; ++i) {
		int j = pi[i-1];
		while (j > 0 && s[i] != s[j])
			j = pi[j-1];
		if (s[i] == s[j]) ++j;
		pi[i] = j;
	}
	return pi;
}

void solve() {
  string s; cin >> s;
  vector<int> p = prefix_function(s);
  reverse(all(s));
  vector<int> p2 = prefix_function(s);
  int n = s.size(), k = n - p[n - 1];
  //cout << k << endl;
  if (k == 1) {
    cout << n << "\n1\n"; return;
  }
  if (n % k != 0 || k == n) {
    cout << "1\n1\n"; return;
  }
  int ans = 0;
  for (int i = 0; i < n - 1; i++) {
    int len = i + 1, v = len - p[i];
    //cout << i << " " << len << " " << v << endl;
    if (len > 1 && v % len == 0 && len != v) continue;
    int len2 = (n-1)-(i+1)+1, v2 = len2 - p2[n-1-i-1];
    //cout << i << " " << len2 << " " << v2 << endl;
    if (len2 > 1 && v2 % len2 == 0 && len2 != v2) continue;
    ans++;
  }
  cout << k << " " << ans << endl;
}

