class KMP
{
public:
    vector<int> table, res;
    string pattern;
    int plen;
    KMP(const string s){
        pattern = s;
        plen = (int)pattern.size();
        table.resize(plen+1);
        table[0] = -1;
        int j = -1;
        rep(i,plen){
            while(j >= 0 && pattern[i] != pattern[j]){
                j = table[j];
            }
            table[i+1] = ++j;
        }
    }
    void search(const string& text){
        int head = 0, j = 0, tlen = (int)text.size();
        while(head + j < tlen){
            if(pattern[j] == text[head + j]) {
                if(++j == plen){
                    res.push_back(head);
                    head = head + j - table[j];
                    j = table[j];
                }
            }else{
                head = head + j - table[j];
                if(j){
                    j = table[j];
                }
            }
        }
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    string s;
    cin >> s;
    int n = len(s);
    KMP x(s);
    reverse(all(s));
    KMP y(s);
    vi tx = x.table,ty = y.table;
    srep(i,1,n+1){
        tx[i-1] = i-tx[i];
        ty[i-1] = i-ty[i];
    }
    if(tx[n-1] == n || n%tx[n-1] != 0){
        cout << "1\n";
        cout << "1\n";
    }else if(tx[n-1] == 1){
        cout << "n\n";
        cout << "1\n";
    }else{
        cout << "2\n";
        int ans = 0;
        rep(i,n-1){
            if(tx[i] == i+1 || (i+1)%tx[i] != 0){
                if(ty[n-2-i] == n-1-i || (n-1-i)%ty[n-2-i] != 0){
                    ans++;
                }
            }
        }
        cout << ans << "\n";
    }
    return 0;
}

