namespace Hash{
	ull h[2][N], d[2][N];
	static ull const P[2] = {41, 1000 * 1000 * 1000 + 7};

	void build(){
		fi(0, 2) d[i][0] = 1;
		fi(1, N) fj(0, 2){
			d[j][i] = d[j][i-1] * P[j];
		}
		fi(0, sz(str)) fj(0, 2){
			h[j][i] = (i ? h[j][i-1] : 0) * P[j];
			h[j][i] += (str[i] - 'a' + 1);
		}
	}

	vector<ull> gethash(int l, int r){
		vector<ull> res;
		fi(0, 2){
			ull x = h[i][r];
			if(l) x -= h[i][l-1] * d[i][r-l+1];
			res.pb(x);
		}
		return res;
	}
};

bool checkone(){
	fi(1, n){
		if(n % i == 0){
			vector<ull> h = Hash::gethash(0, i-1);
			bool ok = true;
			for(int j=0;j<n;j+=i){
				if(Hash::gethash(j, j+i-1) != h){
					ok = false;
					break;
				}
			}
			if(ok) return false;
		}
	}	
	return true;
}

bool checkall(){
	fi(0, sz(str)) if(str[i] != str[0]) return false;
	return true;
}

int p[N], s[N];

void build(){
	memset(p, 0, sizeof(p));
	memset(s, 0, sizeof(s));
	fi(0, n) p[i] = s[i] = 1;
	fi(1, n){
		vector<ull> h = Hash::gethash(0, i-1);
		for(int j=i+i;j<=n;j+=i){
			vector<ull> h0 = Hash::gethash(j-i, j-1);
			if(h != h0) break;
			p[j-1] = 0;
		}
	}
	fi(1, n){
		vector<ull> h = Hash::gethash(n-i, n-1);
		for(int j=i+i;j<=n;j+=i){
			vector<ull> h0 = Hash::gethash(n-j, n-j+i-1);
			if(h != h0) break;
			s[n-j] = 0;
		}
	}
}

int checktwo(){
