vector<int> z_func(string &s) {
  vector<int> z(len(s));
  int l = 0, r = 1;

  rep(i, 1, sz(z) - 1) {
    if (i < r) {
      z[i] = min(z[i - l], r - i);
      while (r < len(s) && s[z[i]] == s[r]) z[i]++, r++;
    } else {
      l = r = i;
      while (r < len(s) && s[z[i]] == s[r]) z[i]++, r++;
    }
  }

  return z;
}

bool can_divide(vector<int> &z, int &prefix_len) {
  for (int i = prefix_len; i < sz(z); i += prefix_len)
    if (z[i] < prefix_len) 
      return false;
  return true;
}

void solve() {
