struct RollingHash {
	vector<ll> mod;
	vector<vector<ll> > hs, pw;
	string s;
	ll base;
	int n;

	RollingHash() {}
	RollingHash(string s) { init(s); }

	void init(string _s) {
		s = _s;
		n = s.size();

		mod.clear();
		hs.clear();
		pw.clear();

		mod.push_back(999999937);
		mod.push_back(1000000007);

		base = 9973;

		hs.resize(mod.size(), vector<ll>(n + 1));
		pw.resize(mod.size(), vector<ll>(n + 1));

		REP(i, mod.size()) {
			pw[i][0] = 1;
			REP(j, n) {
				hs[i][j + 1] = (hs[i][j] + s[j]) * base % mod[i];
				pw[i][j + 1] = pw[i][j] * base % mod[i];
			}
		}
	}

	inline ll hash(int l, int r, int i) {
		return (hs[i][r] - hs[i][l] * pw[i][r - l] % mod[i] + mod[i]) % mod[i];
	}

	inline bool match(int l1, int r1, int l2, int r2) {
		bool res = true;
		REP(i, mod.size()) if (hash(l1, r1, i) != hash(l2, r2, i)) res = false;
		return res;
	}
};

string w;
int cut[512345] = {}; // 0:ok, 1:ok, 2:no
int rcut[512345] = {};


int main() {
	cin >> w;
	RollingHash rh(w);

	bool ok = true;

	FOR(i, 1, w.size() / 2 + 1) if (w.size() % i == 0) {
		bool f = true;
		// head
		for (int j = i + i; j <= w.size(); j += i) {
			if (!rh.match(0, i, j - i, j)) { f = false; break; }
			cut[j] = 2;
		}
		if (f) ok = false;

		// back
		for (int j = w.size() - i - i; j >= 0; j -= i) {
			if (!rh.match(w.size() - i, w.size(), j, j + i)) break;
			rcut[j] = 2;
		}
	}

	int cnt = 0;
	FOR(i, 1, w.size()) if (cut[i] <= 1 && rcut[i] <= 1) cnt++;

	//if (debug) cout << "cnt : " << cnt << endl;

	bool same = true;
	FOR(i, 1, w.size()) if (w[i - 1] != w[i]) same = false;



	int a, b;
	if (same) a = w.size(), b = 1;
	else if (ok) a = 1, b = 1;
	else a = 2, b = cnt;

	printf("%d\n%d\n", a, b);

	return 0;
}

