struct RollingHash{

    using ll = __int128_t;
    static const ll MOD = 9000000000000000041;
    int N;
    ll x, invx;
    vector<ll> pow_x, pow_invx, hash_vec, invhash_vec;

    template<typename T>
    RollingHash(int x, vector<T> S, bool calcinv = false): x(x) {
        N = S.size();

        pow_x.resize(N + 1);
        pow_x[0] = 1;
        REP(i, N) pow_x[i + 1] = (pow_x[i] * x) % MOD;
        pow_invx.resize(N + 1);
        invx = inv();
        pow_invx[0] = 1;
        REP(i, N) pow_invx[i + 1] = (pow_invx[i] * invx) % MOD;

        hash_vec.resize(N + 1);
        hash_vec[0] = 0;
        REP(i, N) hash_vec[i + 1] = (hash_vec[i] + pow_x[i] * S[i]) % MOD;

        if(calcinv){
            invhash_vec.resize(N + 1);
            invhash_vec[N] = 0;
            REP(i, N) invhash_vec[N - 1 - i] = (invhash_vec[N - i] + pow_x[i] * S[N - 1 - i]) % MOD;
        }
    }

    RollingHash(int x, string S, bool calcinv = false){
        vector<int> s(S.size());
        REP(i, SZ(S)) s[i] = (int)S[i];
        *this = RollingHash(x, s, calcinv);
    }

    ll inv(){
        ll a = 1, n = MOD - 2;
        for(int i = 63; i >= 0; i--){ a = (a * a) % MOD; if((n >> i) & 1) a = (a * x) % MOD; }
        return a;
    }

    //0<=l<=r<N
    //Hash of (S_l,S_(l+1),...,S_r)
    ll hash(int l, int r){
        return (((hash_vec[r + 1] - hash_vec[l] + MOD) % MOD) * pow_invx[l]) % MOD;
    }

    //0<=l<=r<N
    //Hash of (S_r,S_(r-1),...,S_l)
    ll invhash(int l, int r){
        return (((invhash_vec[l] - invhash_vec[r + 1] + MOD) % MOD) * pow_invx[N - 1 - r]) % MOD;
    }

};

signed main(){

    string S; cin >> S;
    int N = SZ(S);

    bool same = true;
    REP(i, N) if(S[i] != S[0]) same = false;
    if(same){
        Out(N);
        Out(1);
        return 0;
    }

    RollingHash RH(1145141919, S);
    bools fl(N, true), fr(N, true);
    FOR(L, 1, N + 1){
        int l = L, r = 2 * L - 1;
        while(r < N && RH.hash(0, L - 1) == RH.hash(l, r)){
            fl[r] = false;
            l += L; r += L;
        }
    }
    FOR(L, 1, N + 1){
        int l = N - 2 * L, r = N - L - 1;
        while(l >= 0 && RH.hash(N - L, N - 1) == RH.hash(l, r)){
            fr[l] = false;
            l -= L; r -= L;
        }
    }
    if(fl[N - 1] || fr[0]){
        Out(1);
        Out(1);
    }else{
        int ans = 0;
        REP(i, N - 1) if(fl[i] && fr[i + 1]) ans++;
        Out(2);
        Out(ans);
    }

    return 0;
}

