		return true;
	}
	bool same = true;
	for (int i = 0; i < len - 1; i ++) {
		same = same && s[i] == s[i + 1];
	}
	if (same) {
		return false;
	}
	for (int l = 2; l <= len / 2; l ++) {
		if (len % l == 0) {
			string t = s.substr(0, l);
			for (int bg = l; bg <= len - l; bg += l) {
				for (int i = bg; i < bg + l; i ++) {
					if (t[i - bg] != s[i]) {
						goto end;
					}
				}
			}
			return false;
			end:;
		}
	}
	return true;
}

