template<unsigned long long mod1,unsigned long long mod2>
class RollingHash {
private:
    typedef unsigned long long ULL;
    typedef pair<ULL,ULL> PULL;
    int len;
    vector<ULL> power1;
    vector<ULL> power2;
public:
    // 文字列
    string S;
    // hashed[k] : 先頭k文字のhash値
    vector<ULL> hashed1;
    vector<ULL> hashed2;
    // O(len)
    RollingHash(const string &s,ULL base1 = 10007LL,ULL base2 = 10009LL) :
        S(s),len(s.size()),power1(len+1,1),power2(len+1,1),hashed1(len+1,0),hashed2(len+1,0) {
        // O(N)
        for (int i = 0;i < len ;i++) {
            power1[i+1] = (power1[i] * base1) % mod1;
            power2[i+1] = (power2[i] * base2) % mod2;
            hashed1[i+1] = ((hashed1[i] * base1) + s[i]) % mod1;
            hashed2[i+1] = ((hashed2[i] * base2) + s[i]) % mod2;
        }
    }

    // [l,r) のハッシュ値を求める. O(1)
    PULL getHash(int l,int r) {
        // 負の数にならないようにmodを取ること.
        ULL p1 = ((hashed1[r]+mod1) - ((hashed1[l] * power1[r-l])%mod1))%mod1;
        ULL p2 = ((hashed2[r]+mod2) - ((hashed2[l] * power2[r-l])%mod2))%mod2;
        return make_pair(p1,p2);
    }

    // ハッシュ値h1 と h2 を結合 O(1)
    PULL connect(PULL h1,PULL h2,int h2len) {
        return make_pair(((h1.first*power1[h2len]) + h2.first)%mod1,((h1.second*power2[h2len]) + h2.second)%mod2);
    }

    int pLCP(int l1 ,int r1 ,int l2 ,int r2 ) {
        int sz = min(r1 - l1,r2 - l2);
        int low = (-1),high = sz + 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (getHash(l1,l1+mid) == getHash(l2,l2+mid)) low = mid;
            else high = mid;
        }
        return low;
    }

    // 区間[l1,r1) と bの区間[l2,r2) の最長共通接頭辞の長さを求める. O(log N)
    int LCP(const RollingHash<mod1,mod2> &b,int l1 ,int r1 ,int l2 ,int r2 ) {
        int sz = min(r1 - l1,r2 - l2);
        int low = (-1),high = sz + 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (getHash(l1,l1+mid) == b.getHash(l2,l2+mid)) low = mid;
            else high = mid;
        }
        return low;
    }
};

