std::vector<long long> divisor(long long n) {
    // nの約数をソートして列挙。1とnも含む。計算量はO(sqrt(n))なので、long longも入り得る。
    std::vector<long long> res;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i) {
                res.push_back(n / i);
            }
        }
    }
    std::sort(res.begin(), res.end());
    return res;
}

bool has_period(const std::string& w, int p) {
    if (w.size() % p != 0) {
        return false;
    }
    for (int i = 0; i < w.size() / p; i++) {
        for (int j = 0; j < p; j++) {
            if (w[i*p + j] != w[j]) {
                return false;
            }
        }
    }
    return true;
}

int has_period_any(const std::string& w) {
    if (w.size() == 1) {
        return 0;
    }
    std::vector<long long> divi = divisor(w.size());

    for (auto d : divi) {
        if (d != w.size() && has_period(w, d)) {
            return d;
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    std::string w;
    std::cin >> w;

    int per = has_period_any(w);

    if (per == 0) {
        std::cout << 1 << std::endl;
        std::cout << 1 << std::endl;
    } else if (per == 1) {
        std::cout << w.size() << std::endl;
        std::cout << 1 << std::endl;
    } else {
        std::cout << 2 << std::endl;

        int cnt = 0;
        std::string s1;
        std::string s2 = w;
        std::reverse(s2.begin(), s2.end());
        for (int i = 1; i <= w.size() - 1; i++) {
            s1.push_back(w[i-1]);
            s2.pop_back();
            if (has_period_any(s1) == 0 && has_period_any(s2) == 0) {
                cnt++;
            }
        }
        std::cout << cnt << std::endl;

    }


    return 0;
}

