template <class Container>
std::vector<int> zalgo(const Container& dat) {
    int n = dat.size();

    std::vector<int> ret(n);
    ret[0] = n;

    int i = 1, len = 0;
    while (i < n) {
        while (i + len < n && dat[len] == dat[i + len]) {
            ++len;
        }
        ret[i] = len;

        if (len == 0) {
            ++i;
            continue;
        }

        int nlen = 1;
        while (i + nlen < n && nlen + ret[nlen] < len) {
            ret[i + nlen] = ret[nlen];
            ++nlen;
        }

        i += nlen;
        len -= nlen;
    }

    return ret;
}

int run(const std::string& s) {
    int n = s.length();
    auto zs = zalgo(s);

    int l;
    for (l = 1; l < n; ++l) {
        bool judge = true;
        for (int i = l; i < n; i += l) {
            if (zs[i] < l) judge = false;
        }
        if (judge) break;
    }
    return l;
}

void solve() {
    std::string s;
    std::cin >> s;

    int n = s.length();
    int l = run(s);

    if (l == n) {
        std::cout << 1 << std::endl
                  << 1 << std::endl;
    } else if (l == 1) {
        std::cout << n << std::endl
                  << 1 << std::endl;
    } else {
        s.pop_back();
        assert(run(s) == (int)s.length());

        int k = n / l;
        std::cout << 2 << std::endl
                  << (n - 1) - (k == 2 ? 0 : k - 1) << std::endl;
    }
}

int main() {
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

