    vector<Hash> powA(n+1);
    h[0]=0;
    powA[0]=1;
    for(int i=0;i<n;i++){
        h[i+1]=(h[i]*A+dict[w[i]])%MOD;
        powA[i+1]=(powA[i]*A)%MOD;
    }

    vector<vector<int>> divisor(n+1);
    for(int i=1;i<=n;i++){
        for(int j=i;j<=n;j+=i){
            divisor[j].push_back(i);
        }
    }

    auto getHash=[&](int l,int r){
        return ((h[r]-h[l]*powA[r-l])%MOD+MOD)%MOD;
    };
    auto repeat=[&](Hash x,int len,int k){
        Hash res=0;
        Hash xA=powA[len];
        for(int i=0;i<20;i++){
            if((k>>i)&1){
                res=res*xA+x;
                res%=MOD;
            }
            x=x*xA+x;
            x%=MOD;
            xA*=powA[len];
            xA%=MOD;
        }
