            //cerr<<(ll)(getHash(l,r))<<" "<<(ll)(rx)<<endl;
            res&=(rx!=getHash(l,r));
        }
        return res;
    };
    int cnt=0;
    for(int i=0;i<n;i++){
        //divide[0,i) (i,n)
        bool isokl=isGood(0,i);
        bool isokr=isGood(i,n);
