		if (s[j + 1] == s[i]) ++j; pre[i] = j;
	}
	for (int i = n - 1, j = n + 1; i; i--)
	{
		while (j <= n && s[j - 1] != s[i]) j = nxt[j];
		if (s[j - 1] == s[i]) --j; nxt[i] = j;
