vi kmp(string s) {
    int n = sz(s); vi f(n+1); f[0] = -1;
    FOR(i,1,n+1) {
        f[i] = f[i-1];
        while (f[i] != -1 && s[f[i]] != s[i-1]) f[i] = f[f[i]];
        f[i] ++;
    }
    return f;
}

bool ok(int i, int f) { return i%(i-f) || f == 0; }

int main() {
    setIO();
    string s; sc(s); int n = sz(s); vi fwd = kmp(s);
    if (ok(n,fwd[n])) return ps(1),ps(1),0;
    if (n-fwd[n] == 1) return ps(n),ps(1),0;
    reverse(all(s)); vi bwd = kmp(s);
    int ans = 0; 
    FOR(i,1,n) if (ok(i,fwd[i])&&ok(n-i,bwd[n-i])) ans++; 
    ps(2); ps(ans);
	return 0;
}

