		}
		return false;
		next:;
	}
	return true;
}
pair<int,int> f(int p) {
	if (p == L) return {0, 1};
	if (memo.count(p)) return memo[p];
	int r1 = 1 << 30;
	int r2 = 0;
	for (int x : G[p]) {
		auto q = f(x);
		++ q.first;
		if (q.first < r1) {
			r1 = q.first;
			r2 = q.second;
		} else if (q.first == r1) {
			r2 += q.second;
			r2 %= mod;
		}
	}
	return memo[p] = {r1, r2};
}
