vector<int> x, y;

vector<int> zal(const string &s) {
	int n = s.size();
	vector<int> a(n);
	a[0] = n;
	int i = 1, j = 0;
	while (i<n) {
		while (i+j<n && s[j]==s[i+j]) ++j;
		a[i] = j;
		if (j==0) {++i; continue;}
		int k = 1;
		while (i+k<n && k+a[k]<j) a[i+k] =a[k], ++k;
		i += k, j -= k;
	}
	return a;
}

vector<int> pre() {
	vector<int> res(n+1,1), z = zal(s);
	reps(i,1,n) for (int j=2; (j-1)*i<=z[i]; j++) res[i*j] = 0;
	return res;
}

signed main() {
