		same = same && (s[i-1]==s[i]);
	}
	if(same){
		printf("%d\n1\n", (int)s.size());
		return 0;
	}
	kp[0] = 0;
	int j = 0;
	for (int i = 1 ; i < s.size(); ++i) {
		while (j > 0 && s[i] != s[j])j = kp[j - 1];
		if (s[i] == s[j])j++;
		kp[i] = j;
	}
	ks[s.size() - 1] = s.size() - 1;
	j = s.size() - 1;
	for (int i = s.size() - 2; i >= 0 ; --i) {
		while (j < s.size() - 1 && s[i] != s[j])
			j = ks[j + 1];
		if(s[i]==s[j])--j;
		ks[i] = j;
	}
	if(kp[s.size()-1] == 0){
		printf("1\n1\n");
		return 0;
	}/*
	for (int i = 0; i < s.size(); ++i){
		cout << ks[i] << " ";
	}
	cout << endl;
*/
	int cnt = 0;
	for(int i = 0 ; i+1 < s.size();++i){
		if((kp[i]==0||(i+1)%(i-kp[i]+1)!=0)&&
			(ks[i+1]==s.size()-1 || (s.size()-(i+1))%(ks[i+1]-i) != 0)){
			cnt++;
		}
	}
	puts("2");
	cout << cnt << endl;
	return 0;
}

