int main(){
	fio>>(s+1);
	int n=strlen(s+1);
	fail[1]=0;
	int nf=0;
	for(int i=2;i<=n;i++){
		while(nf&&s[nf+1]!=s[i]){
			nf=fail[nf];
		}
		if(s[nf+1]==s[i]){
			nf++;
		}
		fail[i]=nf;
	}
	if(!fail[n]){
		fio<<"1\n"<<"1\n";
		return 0;
	}
	for(int i=1;i<=n;i++){
		can[i]=(!fail[i]||(i%(i-fail[i])));
	}
	reverse(s+1,s+n+1);
	nf=0;
	fail2[1]=0;
	for(int i=2;i<=n;i++){
		while(nf&&s[nf+1]!=s[i]){
			nf=fail2[nf];
		}
		if(s[nf+1]==s[i]){
			nf++;
		}
		fail2[i]=nf;
	}
	if(!fail[n]){
		fio<<"1\n"<<"1\n";
