		hash_[0].resize(sz+1,0),hash_[1].resize(sz+1,0);
		if(!mul0) mul0=10009+(((ll)&mul0)>>5)%259,mul1=10007+(((ll)&mul1)>>5)%257;
		if(pmo[0].empty()) pmo[0].pb(1),pmo[1].pb(1);
		rep(i,sz) hash_[0][i+1]=(hash_[0][i]*mul0+add0+s[i])%mo0;	//hash_[0][i]はインデックス0~i-1までの文字列のハッシュ値
		rep(i,sz) hash_[1][i+1]=(hash_[1][i]*mul1+add1+s[i])%mo1;
	}
	pair<ll,ll> hash(int l,int r) {	//文字列sのインデックス[l,r]の部分文字列のハッシュ値
		if(l>r) return make_pair(0,0);
		while((int)pmo[0].size()<r+2) pmo[0].pb(pmo[0].back()*mul0%mo0), pmo[1].pb(pmo[1].back()*mul1%mo1);
		return make_pair((hash_[0][r+1]+(mo0-hash_[0][l]*pmo[0][r+1-l]%mo0))%mo0,
			             (hash_[1][r+1]+(mo1-hash_[1][l]*pmo[1][r+1-l]%mo1))%mo1);
	}
	pair<ll,ll> hash(string s) { init(s); return hash(0,(int)s.size()-1); }	//文字列s全体のハッシュ値
	pair<ll,ll> update_hash(int l, int r, int k, char c){  //文字列sのs[k]を文字cに変えたときの[l,r]までの部分文字列のハッシュ値
        // if(l > k || r < k) return hash(l,r); kが[l,r]の範囲になかったら
        while((int)pmo[0].size()<r+2) pmo[0].pb(pmo[0].back()*mul0%mo0), pmo[1].pb(pmo[1].back()*mul1%mo1);
        return make_pair((hash_[0][r+1]+(mo0-hash_[0][l]*pmo[0][r+1-l]%mo0)+pmo[0][r-k]*(c - s[k]+mo0))%mo0,
                         (hash_[1][r+1]+(mo1-hash_[1][l]*pmo[1][r+1-l]%mo1)+pmo[1][r-k]*(c - s[k]+mo1))%mo1);
    }
	static pair<ll,ll> concat(pair<ll,ll> L,pair<ll,ll> R,int RL) { //文字列L+Rのハッシュ値,RLはRの文字列の長さ
		while((int)pmo[0].size()<RL+2) pmo[0].pb(pmo[0].back()*mul0%mo0), pmo[1].pb(pmo[1].back()*mul1%mo1);
		return make_pair((R.first + L.first*pmo[0][RL])%mo0,(R.second + L.second*pmo[1][RL])%mo1);
	}
};
vector<ll> RollingHash::pmo[2]; ll RollingHash::mul0,RollingHash::mul1;

vi pr[MAX_N];
bool is_prime[MAX_N];

void all_fac(int n)
{
    fill(is_prime,is_prime+n+1,true);
    for(int i=2;i<=n;i++){
        if(is_prime[i]){
            pr[i].pb(i);
            for(int j=2*i;j<=n;j+=i){
                is_prime[j] = false;
                pr[j].pb(i);
            }
        }
    }
}

int n;

bool syuki(int a,RollingHash& rh)
{
    bool ok1=false,ok2=false;
    for(auto id : pr[a+1]){
        if(id == a+1) break;
        if(rh.hash(0,a-id) == rh.hash(id,a)){
            ok1 = true;
            break;
        }
    }
    for(auto id : pr[n-a-1]){
        if(id == n-a-1) break;
        if(rh.hash(a+1,n-1-id) == rh.hash(a+1+id,n-1)){
            ok1 = true;
            break;
        }
    }
    return (ok1||ok2);
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    string s;
    cin >> s;
    n = len(s);
    RollingHash rh;
    rh.init(s);
    int loop = -1;
    rep(i,n+1){
        pr[i].pb(1);
    }
    all_fac(n);
    for(auto id : pr[n]){
        if(id == n) break;
        if(rh.hash(0,n-id-1) == rh.hash(id,n-1)){
            loop = id;
            break;
        }
    }
    if(loop < 0){
        cout << "1\n";
        cout << "1\n";
    }else if(loop == 1){
        cout << n << "\n";
        cout << "1\n";
    }else{
        cout << "2\n";
        int ans = 0;
        rep(i,n-1){
            if(!syuki(i,rh)){
                ans++;
            }
        }
        assert(ans);
        cout << ans << "\n";
    }
    return 0;
}

