  string s; cin >> s;
  RollingHash rh(s);

  int n = sz(s);
  int m = n/2 + 3;

  Vb bl(n+1);
  Vb br(n+1);

  rep2(i, 1, m) {
    for (int j = i; j < n; j += i) {
      if (rh.get(0, i) == rh.get(j, j+i)) bl[j+i] = true;
      else break;
    }
    for (int j = n-i; j >= i; j -= i) {
      if (rh.get(n-i, n) == rh.get(j-i, j)) br[j-i] = true;
      else break;
    }
  }

