		if (s.size() % i != 0) continue;
		bool f = true;
		for (int j = i; j < s.size(); j++) {
			if (s[j] != s[j - i]) f = false;
		}
		if (f) {
			z = i;
			break;
		}
	}
	if (z == s.size()) puts("1\n1\n");
	else if (z == 1) printf("%u\n1\n", s.size());
	else {
		for (int i = 1; i <= s.size(); i++) {
			int p1 = hash1(0, i), p2 = hash2(0, i);
			for (int j = i * 2; j <= s.size(); j += i) {
				if (p1 != hash1(j - i, j) || p2 != hash2(j - i, j)) break;
				okl[j] = true;
			}
		}
		for (int i = 1; i <= s.size(); i++) {
			int p1 = hash1(s.size() - i, s.size()), p2 = hash2(s.size() - i, s.size());
			for (int j = i * 2; j <= s.size(); j += i) {
				if (p1 != hash1(s.size() - j, s.size() - j + i) || p2 != hash2(s.size() - j, s.size() - j + i)) break;
				okr[s.size() - j] = true;
			}
		}
		int ret = 0;
		for (int j = 1; j < s.size(); j++) {
			if (!okl[j] && !okr[j]) ret++;
		}
		printf("2\n%d\n", ret);
	}
	return 0;
}

