// ----- MP algorithm -----

template <typename Type = string>
class MP
{
  int N;
  Type S;
  vector<int> A;

public:
  MP() {}
  MP(Type const &S) : N(S.size()), S{S}, A(N + 1, -1)
  {
    int j{-1};
    for (auto i{0}; i < N; i++)
    {
      while (j != -1 && S[j] != S[i])
      {
        j = A[j];
      }
      ++j;
      A[i + 1] = j;
    }
  }

  int operator[](int i) const { return A[i]; }

  int period(int i) const
  { // The period of S[0, i).
    auto tmp{i - A[i]};
    if (i % tmp == 0)
    {
      return tmp;
    }
    return i;
  }

  vector<int> place(Type const &T) const
  {
    vector<int> res;
    int j{0};
    for (auto i{size_t{0}}; i < T.size(); i++)
    {
      while (j != -1 && S[j] != T[i])
      {
        j = A[j];
      }
      ++j;
      if (j == N)
      {
        res.push_back(i - j + 1);
        j = A[j];
      }
    }
    return res;
  }

  vector<bool> table(Type const &T) const
  {
    vector<bool> res(T.size(), false);
    for (auto e : place(T))
    {
      res[e] = true;
    }
    return res;
  }
};

// ----- Solve -----

class Solve
{
  string w;
  int n;
  int ans;
  MP<string> mp, mp_rev;

public:
  Solve() : ans{0}
  {
    cin >> w;
    n = w.size();
    mp = MP<string>{w};
    reverse(w.begin(), w.end());
    mp_rev = MP<string>{w};
    reverse(w.begin(), w.end());
  }

  void flush()
  {
    if (all_of(w.begin(), w.end(), [&](auto c) { return c == w[0]; }))
    {
      cout << n << endl;
      cout << 1 << endl;
    }
    else if (is_good(mp, n))
    {
      cout << 1 << endl;
      cout << 1 << endl;
    }
    else
    {
      for (auto i{1}; i < n; ++i)
      {
        if (is_good(mp, i) && is_good(mp_rev, n - i))
        {
          ++ans;
        }
      }
      cout << 2 << endl;
      cout << ans << endl;
    }
  }

private:
  bool is_good(MP<string> const &mp, int s)
  {
    auto p{mp.period(s)};
    return p == s;
  }
};

