        cout << N << endl;
        cout << 1 << endl;
        return 0;
    }
    for(int i = N-1; i >= 0; i--) t += s[i];
    auto vs = z_algorithm(s);
    auto vt = z_algorithm(t);
    for(int i = 2; i*2 <= N; i++){
        int m = vs[i];
        for(int j = 1; i*j <= m; j++){
            st.insert(i+i*j);
        }
    }
    for(int i = 2; i*2 <= N; i++){
        int m = vt[i];
        for(int j = 1; i*j <= m; j++){
            st.insert(N-(i+i*j));
        }
    }
    // for(int i : st) cout << i << endl;
    if(st.size() == 0){
        cout << 1 << endl;
        cout << 1 << endl;
    }else{
        st.erase(N);
        st.erase(0);
        cout << 2 << endl;
        cout << N-1-st.size() << endl;
    }
}

