ll modpow(ll x, ll n, ll mod){
	ll res = 1;
	while(n > 0){
		if(n & 1) res = res * x % mod;
		x = x * x % mod;
		n >>= 1;
	}
	return res;
}

vl divisor(ll k){
	vl c;
	for(ll i=1; i*i<=k; i++){
		if(k % i == 0){
			c.push_back(i);
			if((k / i) != i){
				c.push_back(k/i);
			}
		}
	}
	sort(c.begin(), c.end());
	return c;
}

vector<ll> zalgo(string s){
	ll n = s.size();
	vector<ll> z(n,0);
	z[0] = n;
	ll i = 1, j = 0;
	while(i < n){
		while(i+j < n && s[j] == s[i+j]) j++;
		if(j == 0){
			i++;
			continue;
		}
		z[i] = j;
		ll k = 1;
		while(k < j && k + z[k] < j){
			z[i+k] = z[k];
			k++;
		}
		i += k;
		j -= k;
	}
	return z;
}

