vector < int > z_function(string& s) {
    vector < int > z(s.size());
    int l = 0;
    int r = 0;
    for (int i = 1; i < s.size(); i++) {
        if (r < i) {
            l = r = i;
        }
        z[i] = min(r - i, z[i - l]);
        while (i + z[i] < s.size() && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    return z;
}
vector < bool > get(string& s) {
    int n = s.size();
    vector < bool > f(n + 1, true);
    auto z = z_function(s);
    for (int i = 1; i <= n; i++) {
        for (int j = 2 * i; j <= n; j += i) {
            if (z[i] >= j - i) {
                f[j] = false;
            }
        }
    }
    return f;
}
