        pair<ll, ll> x = rh.get(0, d);
        bool ok = 1;
        for(int i = d; i < n; i += d) {
            if(x != rh.get(i, i + d)) {
                ok = 0;
            }
        }
        if(ok) chmin(syuuki, d);
