        return;
    }
    vector<bool> check(n + 1, 1);
    for(int d = 1; d <= n; ++ d) {
        pair<ll, ll> x = rh.get(0, d);
        for(int i = d; i < n; i += d) {
            if(x != rh.get(i, i + d)) break;
            check[i + d] = 0;
        }
        x = rh.get(n - d, n);
        for(int i = n - d; i > 0; i -= d) {
            if(x != rh.get(i - d, i)) break;
            check[i - d] = 0;
        }
    }
    int cnt = 0;
    for(int i = 1; i < n; ++ i) {
        if(check[i]) ++ cnt;
    }
    cout << 2 << " " << cnt << endl;
}

