struct Hashing {
	vector<LL> ha, pw;
	LL mod = 1000696969;
	int base;

	Hashing(string &str) {
		base = 31;
		int len = size(str);
		ha.resize(len + 1);
		pw.resize(len + 1, 1);
		REP(i, len) {
			ha[i + 1] = (ha[i] * base + str[i] - 'a' + 1) % mod;
			pw[i + 1] = (pw[i] * base) % mod;
		}
	}

	LL get_hash(int l, int r) {
		return ((ha[r + 1] - ha[l] * pw[r - l + 1]) % mod + mod) % mod;
	}
};

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	string str;
	cin >> str;

	int n = size(str);
	Hashing hsh(str);
	auto cmp = [&](int a, int b, int c, int d) {
		if(a > b) return false;
		return hsh.get_hash(a, b) == hsh.get_hash(c, d);
	};

	auto good = [&](int l, int r) {
		int len = r - l + 1;
		for(int i = 1; i * i <= len; i++) {
			if(len % i == 0) {
				if(cmp(l, r - i, l + i, r))
					return false;
				if(cmp(l, r - len / i, l + len / i, r))
					return false;
			}
		}
		return true;
	};

	if(good(0, n - 1)) cout << "1\n1\n";
	else if(str == string(n, str[0])) cout << n << "\n1\n";
	else {
		int cnt = 0;
		FOR(i, 1, n - 1) 
			if(good(0, i - 1) && good(i, n - 1))
				cnt++;
		cout << "2\n" << cnt << "\n";
	}
}

