typedef long long ll;
const int MN = 500500;
const ll P = 53;
const ll MA = 1e9+7,MB = 1e9+9;
ll sa[MN],sb[MN];
ll ra[MN],rb[MN];
char st[MN];
ll n;
ll hs(ll s, ll l) {
	ll ha = ra[s+l]-sa[l]*ra[s];
	ll hb = rb[s+l]-sb[l]*rb[s];
	ha = ((ha%MA)+MA)%MA;
	hb = ((hb%MB)+MB)%MB;
	return (ha*MB)+hb;
}
bitset<MN> pr,su;
int main() {
	int N;
	scanf("%d ",&N);
	while(N--) {
		scanf("%s",st);
		n = strlen(st);
		bool ol = true;
		for(int i=0;i<n;i++) {
			if(st[i] != st[0]) {ol = false;break;}
		}
		if(ol) {
			printf("%d\n1\n",n);
			continue;
		}
		sa[0] = sb[0] = 1;
		ra[0] = rb[0] = 0;
		for(int i=0;i<n;i++) {
			sa[i+1] = (sa[i]*P)%MA;
			sb[i+1] = (sb[i]*P)%MB;
			ra[i+1] = (P*ra[i]+st[i]-'a'+1)%MA;
			rb[i+1] = (P*rb[i]+st[i]-'a'+1)%MB;
		}
		pr.set();su.set();
		for(int i=1;i<=n;i++) {
			ll val = hs(0,i);
			for(int j=1;i*(j+1)<=n;j++) {
				if(val != hs(i*j,i)) {
					break;
				}
				pr.reset(i*(j+1));
			}
			val = hs(n-i,i);
			for(int j=1;i*(j+1)<=n;j++) {
				if(val != hs(n-i*(j+1),i)) {
					break;
				}
				su.reset(n-i*(j+1));
			}
		}
		if(pr[n]) {
			printf("1\n1\n");
			continue;
		}
		/*
		   for(int i=1;i<n;i++) {
		   printf("%d",pr[i]?1:0);
		   }
		   printf("\n");
		   for(int i=1;i<n;i++) {
		   printf("%d",su[i]?1:0);
		   }
		   printf("\n");
		   */
		ll tot = 0;
		for(int i=1;i<n;i++) {
			tot += pr[i]*su[i];
		}
		printf("2\n");
		printf("%lld\n",tot);
	}
}

