const int MAX = 500000;

class Z {
	private:
		vector<int> z;
	public:
		Z(string S);
		int get(int n);
};

Z::Z(string S) {
	int i = 1, j = 0, k, n = S.size();
	z.resize(n);
	z[0] = n; // 最初は当然だが全一致
	while(i < n) {
		while (i + j < n && S[j] == S[i + j]) ++ j; // 順に先頭一致か確認して進めていく
		z[i] = j; // とりあえず結果を入れる
		if (j == 0) { // j=0、つまり開幕から文字が違うならもう再利用できないので次のiは愚直
			++ i;
			continue;
		}
		k = 1;
		while (i + k < n && k + z[k] < j) { // 一致している文字列に対して再利用できるよ
			z[i + k] = z[k];
			++ k;
		}
		i += k; // 再利用した分も求まっているのでカット
		j -= k; // その個数だけ前の分は再利用できなくなってるので消しておく
	}
}

int Z::get(int n) {
	return z[n];
}

int main() {
	string w, w2;
	cin >> w;
	w2 = w;
	reverse(w2.begin(), w2.end());
	Z z1(w), z2(w2);

	int N = w.size();
	int ans = N;
	static bool G[MAX];
	for (int i = 0;i <= N;i ++) G[i] = true;
	for (int p = 1;p < N;p ++) {
		if (!G[p - 1]) continue;
		for (int k = 2;(k - 1) * p <= z1.get(p) && k * p <= N;k ++) {
			G[k * p - 1] = false;
			-- ans;
		}
		for (int k = 2;(k - 1) * p <= z2.get(p) && N - k * p > 0;k ++) {
			G[N - k * p] = false;
			-- ans;
		}
	}

	if (G[N - 1]) cout << 1 << endl << 1;
	else if (ans == 0) cout << N << endl << 1;
	else cout << 2 << endl << ans;

	return 0;
}
