  for (int i = 1; i < n; ++i) hv[i] = (1LL * hv[i - 1] * kQ + s[i]) % kP;

  vector<set<int>> is_cyclic(n);

  auto GetHash = [&](int p, int k) {
    if (p == 0) return hv[p + k - 1];
    return (int)((hv[p + k - 1] + kP - 1LL * pw[k] * hv[p - 1] % kP) % kP);
  };

  for (int k = 1; k <= n; ++k) {
    int h = hv[k - 1]; 
    for (int j = k; j <= n; j += k) {
      is_cyclic[j - 1].insert(k);
      if (j + k <= n && GetHash(j, k) != h) break;
    }
  }

  if (is_cyclic[n - 1].size() == 1) {
    cout << "1\n";
    cout << "1\n";
    return 0;
  }

  vector<set<int>> suffix(n);
  for (int k = 1; k <= n; ++k) {
    int h = GetHash(n - k, k);
    for (int j = n - k; j >= 0; j -= k) {
      suffix[j].insert(k);
      if (j >= k && GetHash(j - k, k) != h) break;
    }
  }
  int ans = 0;
  for (int i = 0; i + 1 < n; ++i) {
    if (is_cyclic[i].size() == 1 && suffix[i + 1].size() == 1) ans++;
  }
  assert(ans > 0);
  cout << "2\n";
  cout << ans << "\n";
  return 0;
}

