long long modexp(int x, long long e, int m) {
    long long ans = 1, p = x % m;
    while (e > 0) {
        if (e % 2 != 0) ans = (ans * p) % m;
        p = (p * p) % m;
        e >>= 1;
    }
    return ans;
}

class Hash {
    constexpr static int N = 6;
    const int base = 987654321;
    const int primes[N] = {
        1000000007, 1000000009, 1000000021,
        1000000033, 1000000087, 1000000093,
    };
public:
    class Value {
        friend Hash;
        long long val[N];
    public:
        bool operator==(Value &other) {
            for (int i = 0; i < N; i++)
                if (val[i] != other.val[i]) return false;
            return true;
        }
    };
    vector<long long> hash_values[N];
    vector<long long> inverse_pow[N];
    Hash(string &s) {
        const int n = s.size();
        for (int j = 0; j < N; j++) {
            const int p = primes[j];
            hash_values[j].resize(n+1, 0);
            for (int i = 0, pw = 1; i < n; i++) {
                hash_values[j][i+1] = (hash_values[j][i] + s[i] * (long long)pw) % p;
                pw = (long long)pw * base % p;
            }
            inverse_pow[j].resize(n+1, 1);
            inverse_pow[j][n] = modexp(base, p - 1 - n, p);
            for (int i = n-1; i >= 0; i--)
                inverse_pow[j][i] = inverse_pow[j][i+1] * base % p;
        }
    }
    Value get(int l, int r) {
        Value ret;
        for (int i = 0; i < N; i++) {
            const int p = primes[i];
            const long long diff = (hash_values[i][r] - hash_values[i][l]);
            ret.val[i] = diff * inverse_pow[i][l] % p;
            if (ret.val[i] < 0) ret.val[i] += p;
        }
        return ret;
    }
};

int main() {
    string w; cin >> w;
    const int n = w.size();
    Hash h(w);
    vector<bool> p(n+1, false), s(n+1, false);
    vector<bool> skip(n+1, false);
    for (int i = 1; i <= n/2; i++) {
        if (skip[i]) continue;
        Hash::Value v = h.get(0, i);
        for (int j = i; j + i <= n; j += i) {
            if (h.get(j, j + i) == v) {
                p[j + i] = true;
                skip[j + i] = true;
            }
            else break;
        }
    }
    fill(skip.begin(), skip.end(), false);
    for (int i = 1; i <= n/2; i++) {
        if (skip[i]) continue;
        Hash::Value v = h.get(n - i, n);
        for (int j = n - i; j - i >= 0; j -= i) {
            if (h.get(j - i, j) == v) {
                s[j - i] = true;
                skip[n - (j - i)] = true;
            }
            else break;
        }
    }

    if (!p[n]) cout << "1\n1\n";
    else {
        int ans = n - 1;
        for (int i = 1; i < n; i++)
            if (p[i] || s[i]) ans--;
        if (ans > 0) cout << "2\n" << ans << endl;
        else cout << n << "\n1\n";
    }
}

