int f[2][maxn];
bool good[2][maxn];
void kmp(string s, int* f, bool* good) {
	f[0] = -1;
	for (int i = 1, j = -1; i < (int)s.size(); i++) {
		while (j != -1 && s[i] != s[j + 1])	j = f[j];
		if (s[i] == s[j + 1])	j++;
		f[i] = j;
	}
	good[0] = true;
	for (int i = 1; i < (int)s.size(); i++)
		if (f[i] == -1 || (i + 1) % (i - f[i]) != 0)
			good[i] = true;
}
