void KMP(char *P, int n) {
	f[1] = 0;
	for (int i = 1, j = 0; i < n; i++) {
		while (j && P[i] != P[j]) j = f[j];
		if (P[i] == P[j]) j++;
		f[i+1] = j;
	}
}

void kmp(char *P, int n) {
	g[1] = 0;
	for (int i = 1, j = 0; i < n; i++) {
		while (j && P[i] != P[j]) j = g[j];
		if (P[i] == P[j]) j++;
		g[i+1] = j;
	}
}

bool ok(int st, int en) {
	int len = en - st + 1;
	if (st == 0) {
		if (f[en + 1] == 0) return 1;
		if (len % (len - f[en + 1]) == 0) return 0;
		return 1;
	} else {
		if (g[len - st] == 0) return 1;
		if (len % (len - g[len - st]) == 0) return 0;
		return 1;
	}
	return 1;
}

