void init(){
	for(int i=2;i<N;++i){
		if(!l[i]){
			for(int j=i;j<N;j+=i){
				if(l[j] == 0 || l[j] > i) l[j] = i;
			}
		}
	}
	for(int i=1;i<N;++i){
		d[i].pb(1);
		int n = i;
		while(n > 1){
			int m = sz(d[i]);
			fdj(m, 0) d[i].pb(d[i][j] * l[n]);
			n /= l[n];
		}
	}
}

namespace Hash{
	ull h[N], d[N];
	static ull const P = 41;

	void build(){
		d[0] = 1;
		fi(1, sz(str)) d[i] = d[i-1] * P;
		fi(0, sz(str)){
			h[i] = (i ? h[i-1] : 0) * P;
			h[i] += (str[i] - 'a' + 1);
		}
	}

	ull gethash(int l, int r){
		ull res = h[r];
		if(l) res -= h[l-1] * d[r-l+1];
		return res;
	}
};

bool checkone(){
	fi(1, n){
		if(n % i == 0){
			ull h = Hash::gethash(0, i-1);
			bool ok = true;
			for(int j=0;j<n;j+=i){
				if(Hash::gethash(j, j+i-1) != h){
					ok = false;
					break;
				}
			}
			if(ok) return false;
		}
	}	
	return true;
}

int p[N], s[N];

bool checkpref(int q, int mn){
	ull h = Hash::gethash(0, mn-1);
	fi(1, q+1){
		int l = (i - 1) * mn;
		int r = l + mn - 1;
		ull h0 = Hash::gethash(l, r);
		if(h != h0) return false;
	}
	return true;
}

bool checksuf(int q, int mn){
	ull h = Hash::gethash(n-mn, n-1);
	fi(1, q+1){
		int l = n - i * mn;
		int r = l + mn - 1;
		ull h0 = Hash::gethash(l, r);
		if(h0 != h) return false;
	}
	return true;
}

void build(){
	memset(p, 0, sizeof(p));
	memset(s, 0, sizeof(s));
	fi(0, n){
		int f = 0;
		for(int x : d[i+1]){
			if(x == i + 1) continue;
			f |= checkpref( (i + 1) / x, x);
		}
		p[i] = (1 - f);
	}
	fi(0, n){
		int f = 0;
		for(int x : d[n-i]){
			if(x == n - i) continue;
			f |= checksuf( (n-i) / x, x);
		}
		s[i] = (1 - f);
	}
}

bool checkstring(string &s){
	bool res = false;
	int n = sz(s);
	fi(1, sz(s)){
		if(n % i != 0) continue;
		string s0;
		while(sz(s0) < sz(s)){
			s0 += s.substr(0, i);
		}
		if(s0 == s) return true;
	}
	return false;
}

int checktwo(){
	int res = 0;
	fi(0, n-1){
		res += (p[i] && s[i+1]);
	}
	return res;
}

bool checkall(){
