long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

using mi = modint;

mi mod_pow(mi a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

vector<int> kmp(string s) {
    int n = (int)s.size();
    vector<int> ret(n, 0);
    REP(i, n - 1) {
        int pos = i;
        while(1) {
            if(ret[pos] == 0) {
                if(s[i + 1] == s[0]) ret[i + 1] = 1;
                else ret[i + 1] = 0;
                break;
            }
            if(s[ret[pos]] == s[i + 1]) {
                ret[i + 1] = ret[pos] + 1;
                break;
            } else {
                pos = ret[pos - 1];
            }
        }
    }
    return ret;
}

