vector<int> get_pf(const string& s) {
    int n = (int) s.length();
    vector<int> pi (n);
    for (int i=0; i<n; ++i)
        for (int k=0; k<=i; ++k)
            if (s.substr(0,k) == s.substr(i-k+1,k))
                pi[i] = k;
    return pi;
}

vector<int> get_goodness(const string& s) {
    vector<int> result(s.size() + 1, 0);
    auto pf = get_pf(s);
    for (int i = 2; i <= s.size(); ++i) {
        result[i] = int(pf[i - 1] > 0 && (i % (i - pf[i - 1])) == 0);
    }
    return result;
}

