struct Node{
    int y;
    int cnt;
    Hash we;
    Hash h;
    Node * L, * R;
};

inline void create(Node * N, char c)
{
    N->y = (rand() << 15) + rand();
    (N->h).x = c;
    (N->we).x = c;
    N->cnt = 1;
}

inline int get_cnt(Node * N)
{
    if (N != nullptr) return N->cnt;
    return 0;
}

inline Hash get_hash(Node * N)
{
    if (N == nullptr) return 0;
    return N->h;
}

inline Hash build(Node * N)
{
    Hash a = get_hash(N->L);
    Hash b = Flen[1 + get_cnt(N->R)];
    Hash c = N->we;
    Hash d = Flen[get_cnt(N->R)];
    Hash e = get_hash(N->R);
    Hash f = a * b + c * d + e;
    return f;
}

inline void update(Node * N)
{
    int x = 1 + get_cnt(N->L) + get_cnt(N->R);
    Hash y = build(N);
    N->h = y;
    N->cnt = x;
}

Node * Merge(Node * L, Node * R)
{
    if (!L) return R;
    if (!R) return L;
    if (L->y < R->y)
    {
        L->R = Merge(L->R, R);
        update(L);
        return L;
    }
    else
    {
        R->L = Merge(L, R->L);
        update(R);
        return R;
    }
}

pair<Node *, Node *> Split_size(Node * Scope, int k)
{
    if (!Scope) return {nullptr, nullptr};
    int left = get_cnt(Scope->L);
    if (k <= left)
    {
        pair<Node *, Node *> kek = Split_size(Scope->L, k);
        Scope->L = kek.second;
        update(Scope);
        return {kek.first, Scope};
    }
    else
    {
        k -= left + 1;
        pair<Node *, Node *> kek = Split_size(Scope->R, k);
        Scope->R = kek.first;
        update(Scope);
        return {Scope, kek.second};
    }
}

void Insert(Node *& Root, char c, int k)
{
    Node * Nd = new Node();
    create(Nd, c);
    pair<Node *, Node *> kek = Split_size(Root, k);
    kek.first = Merge(kek.first, Nd);
    Root = Merge(kek.first, kek.second);
    return;
}

void Delete(Node *& Root, int k)
{
    pair<Node *, Node *> kek = Split_size(Root, k);
    kek.second = Split_size(kek.second, 1).second;
    Root = Merge(kek.first, kek.second);
    return;
}

void get_hash(Node * Scope, int l, int r, int lefter, vector<pair<Hash, pair<int, int> > > & vect)
{
    if (!Scope) return;
    int L = lefter;
    int R = lefter + Scope->cnt;
    int s1 = lefter + get_cnt(Scope->L) + 1;
    if (l <= L && R <= r)
    {
        Hash H = Scope->h;
        vect.push_back({H, {L, R}});
        return;
    }
    if (R <= l || r <= L)
    {
        return;
    }
    get_hash(Scope->L, l, r, lefter, vect);
    if (l <= s1 - 1 && s1 <= r)
    {
        vect.push_back({Scope->we, {s1 - 1, s1}});
    }
    get_hash(Scope->R, l, r, s1, vect);
    return;
}

bool comp(pair<Hash, pair<int, int> > A, pair<Hash, pair<int, int> > B)
{
    return A.second.first < B.second.first;
}

Hash TakeHash(Node * Scope, int l, int r)
{
    vector<pair<Hash, pair<int, int> > > vect;
    get_hash(Scope, l, r, 0, vect);
    sort(vect.begin(), vect.end(), comp);
    Hash res;
    for (int i = 0; i < vect.size(); i++)
    {
        res = res * Flen[vect[i].second.second - vect[i].second.first] + vect[i].first;
    }
    return res;
}

bool check_period(Node * Root, int l, int r, int k)
{
    if (k > r - l) return 0;
    Hash A = TakeHash(Root, l, r - k);
    Hash B = TakeHash(Root, l + k, r);
    return A == B;
}

