    REP(i,n){
      FORE(j,1,n){
	for(int k=i+j; k+j<=n; k+=j){
	  if(rh.hash(i,i+j) == rh.hash(k,k+j)){
	    is_good[i][k+j] = false;
	  }else{
	    break;
	  }
	}
      }
      //dump(is_good[i]);
