vector<int> z_func(string &s) {
  vector<int> z(len(s), 0);
  int l = 0, r = 1;
  rep(i, 1, sz(z) - 1) {
    if (i < r)
      z[i] = min(z[i - l], r - i);
    while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]])
      z[i]++;
    if (i + z[i] > r)
      l = i, r = i + z[i]; 
  }
  return z;
}

void solve() {
  string s;
  cin >> s;

  auto z = z_func(s);
  bool can_divide = false;

  rep(i, 1, len(s) / 2) {
    can_divide = len(s) % i == 0 && z[i] == i * (len(s) / i - 1);
    if (!can_divide) continue;

    if (i == 1) {
      cout << len(s) << nl << 1;
      return;
    }

    break;
  }

  if (!can_divide) {
    cout << 1 << nl << 1;
    return;
  }

  string rev_s = s;
  reverse(all(rev_s));
  auto rev_z = z_func(rev_s);

  vector<bool> can_divide_left(sz(z), true);
  can_divide_left[0] = false;
  rep(j, 1, sz(z) - 1) {
    if (z[j] >= j) {
      for (int k = j; k < j + z[j]; k += j)
        if (k + j < sz(z) && z[k] >= j)
          can_divide_left[k + j] = false;
        else
          break;
    }
  }

  vector<bool> can_divide_right(sz(z), true);
  can_divide_right[sz(z) - 1] = false;
  per(j, sz(z) - 2, 0) {
    int l = len(s) - j - 1;
    if (rev_z[l] >= l) {
      for (int k = j; k > j - rev_z[l]; k -= l)
        if (k - l >= 0 && rev_z[len(s) - k - 1] >= l)
          can_divide_right[k - l] = false;
        else
          break;
    }
  }

  int res = 0;
  rep(j, 1, len(s) - 1) {
    if (can_divide_left[j] && can_divide_right[j - 1]) {
      res++;
    }
  }

  cout << 2 << nl << res;
}

