struct SA : public vi{
  int n, k;
  vi rank, tmp;

  bool compare( int i , int j ){
    if( rank[i] != rank[j] ) return rank[i] < rank[j];

    int ri = i + k <= n ? rank[i+k] : -1;
    int rj = j + k <= n ? rank[j+k] : -1;
    return ri < rj;
  }

  struct Compare_SA{
    SA *sa;
    Compare_SA( SA *s ) : sa(s) {}
    bool operator() ( const int &i , const int &j ){
      return sa->compare( i , j );
    }
  };

  void init( string S ){
    n = S.length();

    resize( n+1 );
    rank = tmp = vi( n+1 );
    REP( i , n+1 ){
      at(i) = i;
      rank[i] = i < n ? S[i] : -1;
    }

    for( k = 1; k <= n; k *= 2 ){
      sort( begin() , end() , Compare_SA(this) );

      tmp[at(0)] = 0;
      FOR( i , 1 , n+1 )
	tmp[at(i)] = tmp[at(i-1)] + (compare(at(i-1),at(i))?1:0);

      REP( i , n+1 ) rank[i] = tmp[i];
    }
  }
};

struct LCP : public vi{
  void init( string S , const SA &sa ){
    int n = S.length();

    vi rank(n+1);
    REP( i , n+1 ) rank[sa[i]] = i;

    int h = 0;
    resize( n , 0 );
    REP( i , n ){
      int j = sa[rank[i]-1];

      if( h > 0 ) h--;
      for( ; j+h < n && i+h < n; h++ ) if( S[j+h] != S[i+h] ) break;

      at(rank[i]-1) = h;
    }
  }
};

