	for (int i=1;i<=n;i++)
	{
		ss=s.substr(i);
		zz(ss);
		dp[i+1]=min(dp[i+1],dp[i]+1);
		kp[i][i+1]=1;
		memset(used,0,sizeof(used));
		for (int j=1;j<=n-i-1;j++)
		{
			if (z[j]>=j && z[j]%j==0) 
			{
				for (int k=i+j*2;k<=i+j+z[j];k+=j) used[k]=1;
			}
		}
		for (int j=i+2;j<=n;j++)
		{
			if (!used[j]) 
			{
				kp[i][j]=1;
				dp[j]=min(dp[j],dp[i]+1);
			}
		}
	}
	bool f=0;
	for (int i=0;i<n;i++)
	{
		if (s[i]!=s[0]) f=1;
	}
	if (!f) cout<<n<<endl;
	else if (dp[n]==1) printf("%lld\n",1);
	else printf("%lld\n",2);
	num[0]=1;
	for (int i=1;i<=n;i++)
	{
		for (int j=0;j<i;j++)
		{
			if (kp[j][i] && dp[i]==dp[j]+1) num[i]=(num[i]+num[j])%mod;
		}
	}
	printf("%lld\n",num[n]);
	return 0;
}

