bool f[MAXN] , e[MAXN];
int main(){
	memset(f , 0 , sizeof f);
	cin >> s + 1;
	l = strlen(s + 1);
	bool same = 1;
	for(int i = 2 ; i <= l ; ++ i)
		if(s[i] != s[1]){
			same = 0;
			break;
		}
	if(same){
		cout << l << endl << 1 << endl;
		return 0;
	}
	nt[1] = 0;
	for(int i = 2 ; i <= l ; ++ i){
		int tmp = nt[i - 1];
		while(tmp && s[tmp + 1] != s[i])
			tmp = nt[tmp];
		if(s[tmp + 1] == s[i])
			tmp ++;
		nt[i] = tmp;
		int ll = i - nt[i];
		if(nt[i] && i % ll == 0)
			f[i] = 1;
	}
	nt[l] = 0;
	for(int i = l - 1 ; i >= 1 ; -- i){
		int tmp = nt[i + 1];
		while(tmp && s[l - tmp] != s[i])
			tmp = nt[l - tmp + 1];
		if(s[l - tmp] == s[i])
			tmp ++;
		nt[i] = tmp;
		int ll = l - i + 1 - nt[i];
		if(nt[i] && (l - i + 1) % ll == 0)
			e[i] = 1;
	}
	if(!f[l]){
		cout << 1 << endl << 1 << endl;
		return 0;
	}
	int ans = 0;
	for(int i = 1 ; i < l ; ++ i)
		if(!f[i] && !e[i + 1])
			ans ++;
	cout << 2 << endl << ans << endl;
	return 0;
}

