				for (int k = 2 * prefixsz; k <= SZ(s) ; k += prefixsz) {
					if (rh.LCP(rh, 0, SZ(s), prefixsz, SZ(s)) >= k - prefixsz) {
						noDivide[k-1] = 1;
						int noid = k - 1;
