					}
				}
			}
		}
		// 後ろから
		{
			string t = s;
			reverse(ALL(t));
			RollingHash < 1'000'000'007> revrh(t);
			FOR(prefixsz, 1, SZ(s)) {
				for (int k = 2 * prefixsz; k <= SZ(s) ; k += prefixsz) {
					if (revrh.LCP(revrh, 0, SZ(s), prefixsz, SZ(s)) >= k - prefixsz) {
						int noid = SZ(s) - 1 - (k - 1) -1;
						if (noid >= 0)noDivide[noid] = 1;
