vector<int> z_algorithm(const string &s) {
  vector<int> res(s.size());
  res[0] = s.size();
  int i = 1, j = 0;
  while (i < s.size()) {
    while (i + j < s.size() && s[j] == s[i + j]) ++j;
    res[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i + k < s.size() && k + res[k] < j) res[i + k] = res[k], ++k;
    i += k;
    j -= k;
  }

  return res;
}

signed main(int argc, char *argv[]) {
  string w;
  cin >> w;

  int n = w.size();

  vector<int> o = z_algorithm(w);

  int t = w.size();
  for (int i = 1; i < n; ++i) {
    if (o[i] + i == n) {
      t = i;
      break;
    }
  }

  if (t == 1) {
    cout << n << "\n" << 1 << endl;
  } else if (t == n) {
    cout << 1 << "\n" << 1 << endl;
  } else {
    reverse(all(w));
    vector<int> r = z_algorithm(w);
    vector<int> a(n, 1), b(n, 1);

    auto f = [&](const vector<int> &v, vector<int> &use) {
      for (int i = 1; i < n; ++i) {
        if (v[i] + i == n && use[i]) {
          for (int j = 2 * i; j < n; j += i) {
            use[j] = 0;
          }
        }
      }
    };

    f(o, a);
    f(r, b);
    reverse(all(b));
    int cnt = 0;
    for (int i = 1; i < n; ++i) {
      if (a[i] && b[i - 1]) cnt++;
    }

    cout << 2 << "\n" << cnt << endl;
  }
}

