vector <int> v[500001];

bool check(int x, int y, Hash &h1, Hash &h2) {
    int c = y - x, i, j;

    if (c == 1) return true;

    for (i = 0; i < v[c].size(); i++) {
        int z = (y - x) / v[c][i];

        for (j = 1; j * 2 <= v[c][i]; j *= 2) {
            if (h1.get(x, z * j) != h1.get(x + z * j, z * j)) break;
        }

        if (j * 2 <= v[c][i]) continue;

        if (h1.get(x, z * j) != h1.get(y - z * j, z * j)) continue;

        for (j = 1; j * 2 <= v[c][i]; j *= 2) {
            if (h2.get(x, z * j) != h2.get(x + z * j, z * j)) break;
        }

        if (j * 2 <= v[c][i]) continue;

        if (h2.get(x, z * j) != h2.get(y - z * j, z * j)) continue;

        return false;
    }

    return true;
}

