// s[0, z[i]) == s[i, i + z[i])
vector<int> getZ(const string& s) {
	vector<int> z = {int(s.size())};
	int l = 0, r = 0;
	for (int i = 1; i < int(s.size()); i++) {
		int cur = (i >= r ? 0 : min(r - i, z[i - l]));
		while (i + cur < int(s.size()) && s[cur] == s[i + cur]) {
			cur++;
		}
		if (i + cur > r) {
			l = i;
			r = i + cur;
		}
		z.push_back(cur);
	}
	return z;
}

