      res.pb( i );
      x /= i;
    }
  }
  if( x > 1 ) res.pb( x );
  return res;
}

bool check( int x ){
  vl v = fact( x );
  SORT( v );
  UNIQUE( v );
  YYS( u , v ){
    int w = x / u;
    if( w == x ){
      continue;
    }
    int a = sa.rank[0];
    int b = sa.rank[w];
    if( a > b ){
      swap( a , b );
    }
    if( sgq[w] >= x-w ){
      return true;
    }
  }

  v = fact( n-x );
  SORT( v );
  UNIQUE( v );
  YYS( u , v ){
    int w = ( n-x ) / u;
    if( w == n-x ){
      continue;
