ull fsp(ull x,int y){
	ull res=1;
	while(y){
		if(y&1)
			res=res*x;
		x=x*x;
		y>>=1;	
	}
	return res;
}
void check(int x,int flag){
	if(flag==0){
		prel[x]=x;
		for(int i=1;i<=sqrt(x);i++)
			if(x%i==0){
				if(prel[x-i]==i&&pre[x-1]==pre[x-i-1]*fsp(131ull,i)+pre[i-1]){
					prel[x]=min(prel[x],i);	
				}
				if(prel[x-x/i]==x/i&&pre[x-1]==pre[x-x/i-1]*fsp(131ull,x/i)+pre[x/i-1]){
					prel[x]=min(prel[x],x/i);	
				}
			}
	}
	else{
		lasl[x]=x;
		for(int i=1;i<=sqrt(x);i++)
			if(x%i==0){
				if(lasl[x-i]==i&&las[x-1]==las[x-i-1]*fsp(131ull,i)+las[i-1]){
					lasl[x]=min(lasl[x],i);	
				}
				if(lasl[x-x/i]==x/i&&las[x-1]==las[x-x/i-1]*fsp(131ull,x/i)+las[x/i-1]){
					lasl[x]=min(lasl[x],x/i);	
				}
			}
	}
}
