vector<int> prefix_function (string s) {
	int n = (int) s.length();
	vector<int> pi (n);
	for (int i=1; i<n; ++i) {
		int j = pi[i-1];
		while (j > 0 && s[i] != s[j]) j = pi[j-1];
		if (s[i] == s[j])  ++j;
		pi[i] = j;
	}
	return pi;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

    string s; cin >> s;
    int n = si(s);
    auto pi = prefix_function(s);
    int d = si(s) - pi.back();
    //for (int x : pi) cerr << x << ' ';
    //D(d);

    if (d == n || n%d != 0) cout << "1\n1\n";
    else if (d == 1) cout << n << endl << 1 << endl;
    else {
        cout << 2 << endl;
        int ways = 0;
        forsn(i,1,n) {
            if (i%d) ways++;
            else if (i == d && n-i == d) ways++;
        }
        cout << ways << endl;
    }

    return 0;
}

