void buildFail(int *fail, int len, char *s) {
	int j = fail[0] = -1;
	for (int i = 1; i <= len; ++ i) {
		while (j >= 0 && s[j] != s[i - 1]) j = fail[j];
		fail[i] = ++ j;
	}
}
