	char buf[Maxn], cnts = 0;
	int fail[Maxn] = {};
	int a[Maxn], b[Maxn];
	scanf("%s", buf); int n = strlen(buf);
	memset(fail, 0, sizeof fail);
	buildFail(fail, n, buf);
	for (int i = 1; i <= n; ++ i)
		if (!fail[i] || i % (i - fail[i])) a[i] = 1;
	if (a[n]) return puts("1\n1") & 0;
	for (int i = 0; i < n / 2; ++ i)
		buf[i] ^= buf[n - i - 1] ^= buf[i] ^= buf[n - i - 1];
	memset(fail, 0, sizeof fail);
	buildFail(fail, n, buf);
	for (int i = 1; i <= n; ++ i)
		if (!fail[i] || i % (i - fail[i])) b[i] = 1;
