#include <bits/stdc++.h>
using namespace std;

vector < int > Z_algorithm(string &W) {
    int i = 1, j = 0;
    vector < int > Z(W.size());
    Z[0] = W.size();
    while (i < W.size()) {
        while (i + j < W.size() && W[i + j] == W[j]) j++;
        Z[i] = j; 
        if (j == 0) { i++; continue; }
        int k = 1;
        while (Z[k] + k < j) {
            Z[i + k] = Z[k];
            k++;
        }
        i += k, j -= k;
    }
    return (Z);
}

vector < bool > isgood(string &W) {
    vector < int > Z;
    vector < bool > ret(W.size() + 1, true);
    Z = Z_algorithm(W);

    for (int p = 1; p < W.size(); p++) {
        if (!ret[p]) continue;
        for (int k = 2; (k - 1) * p <= Z[p]; k++) {
            ret[k * p] = false;
        }
    }
    return (ret); 
}

int main() {
    string W, RW;
    cin >> W;

    RW = W;
    reverse(begin(RW), end(RW));

    vector < bool > ans1, ans2;

    ans1 = isgood(W); //prefix
    ans2 = isgood(RW);
    reverse(begin(ans2), end(ans2)); //suffix

    int ans = 0;
    for (int i = 0; i <= W.size(); i++) {
        ans += (ans1[i] && ans2[i]);
    }
    if (ans == 0) cout << W.size() << endl << 1 << endl;
    else if (ans1[W.size()]) cout << 1 << endl << 1 << endl;
    else cout << 2 << endl << ans << endl;

    return (0);
}

#include <bits/stdc++.h>

int n, L, Q, lg;
std::vector <int> a;
std::vector <std::pair<int,int>> query;
std::vector <std::vector<int>> reach;

int main () {
	std::cin >> n;
	a.resize (n+1);
	for (int i = 1; i <= n; ++i)
		std::cin >> a[i];
	std::cin >> L >> Q;
	query.resize (Q);
	for (int i = 0; i < Q; ++i)
		std::cin >> query[i].first >> query[i].second;
	lg = std::__lg (n);
	if ((1<<lg) < n) ++lg;
	std::cerr << "lg = " << lg << "\n";
	reach.assign (n+1, std::vector<int> (lg+1, 0));
	for (int i = 1; i <= n; ++i) {
		int l = i, r = n, mid;
		while (l <= r) {
			mid = l + r >> 1;
			if (a[mid]-a[i] <= L)
				reach[i][0] = std::max(mid,reach[i][0]), l = mid+1;
			else
				r = mid-1;
		}
	}

	for (int j = 1; j <= lg; ++j)
		for (int i = 1; i <= n; ++i)
			reach[i][j] = reach[reach[i][j-1]][j-1];

	for (int i = 0; i < Q; ++i) {
		int go, st = query[i].first, ed = query[i].second;
		if (st > ed) std::swap (st, ed);
		for (go = 0; go <= lg; ++go)
			if (reach[st][go] >= ed) break;
		int ans = 0;
		for (; go >= 0 and st < ed; --go)
			if (reach[st][go] <= ed)
				st = reach[st][go], ans += (1<<go);
		if (st < ed) ans++;
		std::cout << ans << "\n";
	}
	return 0;
}

