int chk0(int r) {
	int len = r, now = len % (len - p[r]);
	if(!now) return len / (len - p[r]) == 1;
	return 1;
}

int chk1(int l) {
	int len = n - l + 1, now = len % (len - s[l]);
	if(!now) return len / (len - s[l]) == 1;
	return 1;
}

