vector<int> prefix_function (string s) {
	int n = (int) s.length();
	vector<int> pi (n);
	for (int i=1; i<n; ++i) {
		int j = pi[i-1];
		while (j > 0 && s[i] != s[j]) j = pi[j-1];
		if (s[i] == s[j])  ++j;
		pi[i] = j;
	}
	return pi;
}

bool good(vi &pi, int l) {
    int d = l - pi[l-1];
    return d == l || l%d != 0;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

    string s; cin >> s;
    int n = si(s);
    auto pi = prefix_function(s);

    string t = s;
    reverse(all(t));
    auto pi2 = prefix_function(t);

    int d = si(s) - pi.back();
    if (d == n || n%d != 0) cout << "1\n1\n";
    else if (d == 1) cout << n << endl << 1 << endl;
    else {
        cout << 2 << endl;
        int ways = 0;
        forsn(x,1,n) {
            int y = n-x;
            ways += good(pi,x) && good(pi2,y);
        }
        cout << ways << endl;
    }

    return 0;
}

