vector<int> make_primes(int MAX_NUM){
	vector<bool> flag(MAX_NUM+1, true);
	vector<int> res;
	for(int i=2;i<=MAX_NUM;++i){
		if(flag[i]){
			res.push_back(i);
			for(int j=i*2;j<=MAX_NUM;j+=i){
				flag[j] = false;
			}
		}
	}
	return res;
}
class z_algorithm {
public:
	vector< int > prefix;

	void build(const string &s)
	{
		prefix.assign(s.size(), 0);
		for(int i = 1, j = 0; i < (int)s.size(); i++) {
			if(i + prefix[i - j] < j + prefix[j]) {
				prefix[i] = prefix[i - j];
			} else {
				int k = max(0, j + prefix[j] - i);
				while(i + k < (int)s.size() && s[k] == s[i + k]) ++k;
				prefix[i] = k;
				j = i;
			}
		}
		prefix[0] = (int) s.size();
	}

	int operator[](const int k) const
	{
		return (prefix[k]);
	}

	size_t size()
	{
		return(prefix.size());
	}
};
