bool isGood(LCP& lcp, string& s, int l, int r) {
    int len = r - l + 1;
    t(l, r, len);
    for(auto div : divisor[len]) {
        int st = min(Index[l], Index[l+div]);
        int en = max(Index[l], Index[l + div]) - 1;
        t(st, en);
        int minn = lcp.query(st, en);
        t(div, l, len, div, minn);
        if(minn >= (len - div)) {
            return 0;
        }
    }
    return 1;
}

void solve(string s, int n)
{
    LCP lcp(s);
    lcp.buildLCP();
    lcp.buildRMQ();
    t(lcp.lcp);
    t(lcp.suffix);
    divisor.resize(n+1);
    for (auto i = 1; i <= n; ++i)
    {
        for (auto j = 2; i * j <= n; ++j)
        {
            divisor[i * j].push_back(i);
        }
    }
    for(int i = 0; i < n; i ++) {
        suff[s[i]-'a'] ++;
    }
    Index.assign(n+1, 0);
    for(int i = 0; i < (int)lcp.suffix.size(); i ++) Index[lcp.suffix[i]] = i; 
    t(Index);
    if(get(suff) == 1) {
        cout << n << endl << 1 << endl;
        return ;
    }
    if(isGood(lcp, s, 0, n-1)) {
        cout << 1 << endl << 1 << endl;
        return ; 
    }
    t("ans=2");
    int ans = 0;
    for(int i = 0; i < n-1; i ++) {
        if(isGood(lcp, s, 0, i) && isGood(lcp, s, i+1, n-1)) {
            t("Good", i);
            ans ++;
        }
    }
    cout << 2 << endl << ans << endl;
}  

