std::vector<int> z_algorithm(const std::string &s)
{
    int sz = s.length();
    std::vector<int> z(sz, 0);
    int i = 1, j = 0;
    while (i < sz)
    {
        while (i + j < sz && s[j] == s[i + j])
            j++;
        z[i] = j;
        if (j == 0)
        {
            i++;
            continue;
        }
        int k = 1;
        while (i + k < sz && k + z[k] < j)
        {
            z[i + k] = z[k];
            k++;
        }
        i += k;
        j -= k;
    }
    return z;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    string s;
    cin >> s;
    int n = s.size();
    bool same = true;
    for (int i = 1; i < n; i++)
    {
        if (s[i] != s[i - 1])
        {
            same = false;
        }
    }
    if (same)
    {
        cout << n << endl;
        cout << 1 << endl;
        return 0;
    }
    auto z = z_algorithm(s);
    bool dif = true;
    for (int len = 2; 2 * len <= n; len++)
    {
        if (n % len)
        {
            continue;
        }
        bool f = true; // len の部分文字列がすべて一致?
        for (int i = len; i < n; i += len)
        {
            if (z[i] < len)
            {
                f = false;
            }
        }
        if (f)
            dif = false;
    }
    if (dif)
    {
        cout << 1 << endl;
        cout << 1 << endl;
        return 0;
    }
    int ret = 0;
    reverse(s.begin(), s.end());
    auto rz = z_algorithm(s);
    for (int i = 1; i < n; i++)
    {
        // s[0, i-1], s[i, n-1] = rs[0, n-i-1] に分割できるか
        bool good = true;
        for (int l = 2; l * l <= i; l++)
        {
            int len = l;
            if (i % len)
                continue;
            bool f = true; //部分文字列全部一致?
            for (int j = len; j < i; j += len)
            {
                if (z[j] < len)
                    f = false;
            }
            len = i / l;
            for (int j = len; j < i; j += len)
            {
                if (z[j] < len)
                    f = false;
            }
            if (f)
            {
                good = false;
                break;
            }
        }
        if (!good)
            continue;
        for (int l = 2; l * l <= n - i; l++)
        {
            int len = l;
            if ((n - i) % len)
                continue;
            bool f = true; //部分文字列全部一致?
            for (int j = len; j < (n - i); j += len)
            {
                if (rz[j] < len)
                    f = false;
            }
            len = (n - i) / l;
            for (int j = len; j < (n - i); j += len)
            {
                if (rz[j] < len)
                    f = false;
            }
            if (f)
            {
                good = false;
                break;
            }
        }
        if (good)
            ret++;
    }
    cout << 2 << endl;
    cout << ret << endl;
}

