struct Hash {
  random_device rnd;
  mt19937 mt;
  uniform_int_distribution<LL> dist;
  vector<long long> prime, base;
  vector<vector<long long>> value;
  int n;
  Hash(const vector<long long> &primes) : mt(rnd()), dist(1000, 1e7), prime(primes), n(primes.size()) {
    for (int i = 0; i < n; ++i) base.push_back(dist(mt));
    value.push_back({0LL, 0LL, 0LL});
  };
  Hash() : Hash({999999937LL, 1000000007LL}){};
  void push_back(long long x) {
    int l = value.size();
    value.push_back(vector<long long>(n));
    for (int i = 0; i < n; ++i) {
      value[l][i] = (value[l - 1][i] * base[i] + x) % prime[i];
    }
  }
  vector<long long> get(int l, int r) {
    //get the hash of inteval [l,r)
    auto R = value[r];
    auto L = value[l];
    DBG(l, r, L, R)
    for (int i = 0; i < n; ++i) {
      L[i] = L[i] * modpow(base[i], (r - l), prime[i]) % prime[i];
      R[i] = ((R[i] - L[i]) % prime[i] + prime[i]) % prime[i];
      //R[i] *= modpow(base[i], (r - l) * (prime[i] - 2) % (prime[i] - 1), prime[i]);
    }
    return R;
  }
  bool equals(int l, int r, int l2, int r2) {
    DBG(l, r, l2, r2, get(l, r), get(l2, r2))
    return get(l, r) == get(l2, r2);
  }

 private:
  long long modpow(long long a, long long n, long long mod = MOD) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) ret = (ret * p) % mod;
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
};
