struct node{
	ull hs; int ms;
	node(){}
	node(ull hs,int ms):hs(hs),ms(ms){}
	friend bool operator<(node a,node b){
		return a.hs<b.hs||(a.hs==b.hs&&a.ms<b.ms);
	}
	friend bool operator==(node a,node b){
		return a.hs==b.hs&&a.ms==b.ms;
	}
	friend node operator*(node a,node b){
		return node(a.hs*b.hs,1ll*a.ms*b.ms%mod);
	}
	friend node operator+(node a,node b){
		return node(a.hs+b.hs,(a.ms+b.ms)%mod);
	}
	friend node operator-(node a,node b){
		return node(a.hs-b.hs,(a.ms-b.ms+mod)%mod);
	}
}p[N],hs[N];
int n,l,r,mid,tag,ans;
bool b1[N],b2[N];
char s[N];

node geths(int l,int r){
	return hs[r]-hs[l-1]*p[r-l+1];
}

void init(){
	int i,j;
	p[0]=node(1,1); for (i=1;i<=n;i++) p[i]=p[i-1]*node(P,M);
	for (i=1;i<=n;i++) hs[i]=hs[i-1]*node(P,M)+node(s[i],s[i]);
	for (i=1;i<=n;i++)
		for (j=i+i;j<=n;j+=i)
			if (geths(j-i+1,j)==geths(1,i)) b1[j]=1;
		else break;
	for (i=1;i<=n;i++)
		for (j=n-i-i+1;j>0;j-=i)
			if (geths(j,j+i-1)==geths(n-i+1,n)) b2[j]=1;
		else break;
}

