auto z_algorithm(const string &s) {
	int n = s.size(), i = 1, j = 0, k;
	vector<int> z(n, n);
	while (i < n) {
		while (i + j < n && s[i + j] == s[j]) j++;
		z[i] = j, k = !!j;
		while (i + k < n && k + z[k] < j) z[i + k] = z[k], k++;
		i += k + !j, j -= k;
	}
	return z;
}

int main(void){
	string s;
	cin >> s;
	const int n = s.size();

	bool all_same = true;
	rep(i,n) if(s[0] != s[i]) all_same = false;

	if (all_same) {
		cout << n << endl;
		cout << 1 << endl;
		return 0;
	}

	vector<int> z = z_algorithm(s);

	int dp = n;
	rep(p,2,n){
		if (n % p) continue;
		if(p + z[p] == n) chmin(dp,p);
	}

	if(dp == n) {
		cout << 1 << endl;
		cout << 1 << endl;
	} else {
		cout << 2 << endl;
		cout << (n - 1) - (n / dp - 1) + (dp * 2 == n) << endl;		
	}

	return 0;
}

