VI Z_algorithm(string s){
    int n = s.length();
    VI a(n);
    a[0] = n;
    for (int i = 1, j = 0; i < n;){
        while (i + j < n && s[j] == s[i + j]) j++;
        a[i] = j;
        if (j == 0){
            i++;
            continue;
        }
        int k = 1;
        while (i + k < n && k + a[k] < j) a[i + k] = a[k], k++;
        i += k;
        j -= k;
    }
    return a;
}

VI calc(string s){
    int n = s.length();
    VI ret(n, 1);
    VI z = Z_algorithm(s);
    FOR(x,1,n-1){
        int i = x;
        while (i < n){
            if (z[i] < x) break;
            i += x;
            ret[i - 1] = 0;
        }
    }
    return ret;
}

