#define llint unsigned long long
#define H 998244353

using namespace std;

string s;
llint Hash[500005];
llint bekiH[500005];
vector<int> vec[500005];

llint get(llint l, llint r)
{
	return Hash[r] - Hash[l-1]*bekiH[r-l+1];
}

bool check2(int l, int r, int p)
{
	return get(l, r-p) == get(l+p, r);
}

bool check(int l, int r)
{
	int len = r-l+1;
	if(len == 1) return true;
	for(int i = 0; i < vec[len].size(); i++){
		int d = vec[len][i];
		if(d == len) continue;
		if(check2(l, r, d)) return false;
	}
	return true;
}

int main(void)
{
	cin >> s;
	int n = s.size();
	s = "#" + s;

	bekiH[0] = 1;
	for(int i = 1; i <= n; i++) bekiH[i] = bekiH[i-1] * H;
	for(int i = 1; i <= n; i++) Hash[i] = Hash[i-1] * H + s[i];

	int cyc = n;
	for(int i = 1; i < n; i++){
		if(n % i == 0 && check2(1, n, i)){
			cyc = i;
			break;
		}
	}
	if(cyc == 1){
		cout << n << endl;
		cout << 1 << endl;
		return 0;
	}
	if(cyc == n){
		cout << 1 << endl;
		cout << 1 << endl;
		return 0;
	}

	for(int i = 1; i <= n; i++){
		for(int j = 1; i*j <= n; j++) vec[i*j].push_back(i);
	}

	for(int i = 2; i <= n; i++) cout << check(1, i-1) << " " << check(i, n) << endl;
	cout << check(1, 2) << endl;

	cout << 2 << endl;
	int ans = 0;
	for(int i = 2; i <= n; i++) if(check(1, i-1) && check(i, n)) ans++;
	if(ans == 0) while(1);
	cout << ans << endl;

	return 0;
}

