void kmp(char s[],int arr[]){
  int i,j,l;
  l=strlen(s);
  i=0;
  arr[0]=-1;
  j=-1;
  while(i<l){
    while(j>=0 && s[i]!=s[j]){j=arr[j];}
    i++;
    j++;
    if(s[i]==s[j]){arr[i]=arr[j];}
    else{arr[i]=j;}
  }
  for(i=1;i<=l;i++){
    if(arr[i]==-1){arr[i]=0;}
  }
}

