        int f = 0;
        int sub = -1;
        for(int i = 1; i < z.length; i++){
            // out.println(z[i]);
            if(z[i]==z.length-i){
                sub = i-f;
                if((z.length-i)%sub!=0){
                    out.println(1);
                    out.println(1);
                    return;
                }
                else break;
            }
        }
        if(sub==-1){
            out.println(1);
            out.println(1);
            return;
        }
        if(sub==1){
            out.println(z.length);
            out.println(1);
            return;
        }
        int ans = z.length-z.length/sub;
        if(2*sub==z.length) ans++;
        for(int i = 0; i < z.length; i++){
            if(c[i]==c[i+1]) ans--;
            else break;
        }
        for(int i = z.length-1; i >= 0; i--){
            if(c[i]==c[i-1]) ans--;
            else break;
        }
        out.println(2);
        out.println(ans);

    }

    int[] zalgo(String s) {
        int n = s.length();
        int[] ret = new int[n];
        ret[0] = n;
        int i = 1, j = 0;
        while (i < n) {
            while (i + j < n && s.charAt(j) == s.charAt(i + j))
                ++j;
            ret[i] = j;
            if (j == 0) {
                ++i;
                continue;
            }
            int k = 1;
            while (i + k < n && k + ret[k] < j) {
                ret[i + k] = ret[k];
                ++k;
            }
            i += k;
            j -= k;
        }
        return ret;
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
