	static void solve()
	{
		char[] s = ns().toCharArray();
		int n = s.length;
		outer:
		for(int pe = 1;pe < n;pe++){
			if(n % pe == 0){
				for(int i = 0, j = pe;j < n;i++,j++){
					if(s[i] != s[j])continue outer;
				}
				if(pe == 1){
					out.println(n);
					out.println(1);
					return;
				}

				out.println(2);
				int[] z = Z(s);
				int[] dead = new int[n+1];
				for(int j = 1;j < n;j++){
					for(int k = 2*j;k <= n;k+=j){
						if(k <= j+z[j]){
							dead[k-1]++;
						}
					}
				}

				char[] rs = rev(s);
				z = Z(rs);
				for(int j = 1;j < n;j++){
					for(int k = 2*j;k <= n;k+=j){
						if(k <= j+z[j]){
							if(n-2-(k-1) >= 0)dead[n-2-(k-1)]++;
						}
					}
				}

				int ct = 0;
				for(int j = 0;j < n-1;j++){
					if(dead[j] == 0){
						ct++;
					}
				}
				out.println(ct);
				return;
			}
		}

		out.println(1);
		out.println(1);
	}

	public static char[] rev(char[] a)
	{
		for(int i = 0, j = a.length-1;i < j;i++,j--){
			char c = a[i]; a[i] = a[j]; a[j] = c;
		}
		return a;
	}

	public static int[] Z(char[] str)
	{
		int n = str.length;
		int[] z = new int[n];
		if(n == 0)return z;
		z[0] = n;
		int l = 0, r = 0;
		for(int i = 1;i < n;i++){
			if(i > r){
				l = r = i;
				while(r < n && str[r-l] == str[r])r++;
				z[i] = r-l; r--;
			}else{
				if(z[i-l] < r-i+1){
					z[i] = z[i-l];
				}else{
					l = i;
					while(r < n && str[r-l] == str[r])r++;
					z[i] = r-l; r--;
				}
			}
		}

		return z;
	}


