    public static void solve(ExtendedScanner sc, Out out) {
        char[] s = sc.nextChars();
        int n = s.length;
        boolean uni = true;
        for (int i = 0; i < n - 1; i++) {
            uni &= s[i] == s[i + 1];
        }
        if (uni) {
            out.writeln(n).writeln(1);
            return;
