        int[] z = new Zalgorithm(s).getZ();
        boolean[] rep = new boolean[n];
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    boolean isRep = true;
                    for (int k = 0; k < i; k += j) {
                        if (z[k] < j) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rep[i - 1] = true;
                        break;
                    }
                    if (j != 1) {
                        isRep = true;
                        int d = i / j;
                        for (int k = 0; k < i; k += d) {
                            if (z[k] < d) {
                                isRep = false;
                                break;
                            }
                        }
                        if (isRep) {
                            rep[i - 1] = true;
                            break;
                        }
                    }
                }
            }
        }
        if (!rep[n - 1]) {
            out.writeln(1).writeln(1);
            return;
        }
        CharArrays.reverse(s);
        z = new Zalgorithm(s).getZ();
        int cnt = !rep[n - 2] ? 1 : 0;
        for (int i = 2; i < n; i++) {
            if (rep[n - i - 1]) continue;
            boolean rrep = false;
            for (int j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    boolean isRep = true;
                    for (int k = 0; k < i; k += j) {
                        if (z[k] < j) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rrep = true;
                        break;
                    }
                    if (j != 1) {
                        isRep = true;
                        int d = i / j;
                        for (int k = 0; k < i; k += d) {
                            if (z[k] < d) {
                                isRep = false;
                                break;
                            }
                        }
                        if (isRep) {
                            rrep = true;
                            break;
                        }
                    }
                }
            }
            if (rrep) continue;
            cnt++;
        }
        out.writeln(2).writeln(cnt);
