            div[i] = new IntArrayList();
            div[i].add(1);
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    div[i].add(j);
                    int d = i / j;
                    if (d != j) div[i].add(d);
                }
            }
        }
        int[] z = new Zalgorithm(s).getZ();
        boolean[] rep = new boolean[n];
        for (int i = 2; i <= n; i++) {
            for (var it = div[i].iterator(); it.hasNext();) {
                int j = it.nextInt();
                boolean isRep = true;
                if (j == 1) {
                    isRep = uni >= i;
                } else {
                    int l = j;
                    for (int k = l << 1; k <= i; k <<= 1, l <<= 1) {
                        if (z[l] < l) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        if (z[i - l] < l) {
                            isRep = false;
                        }
                    }
                }
                if (isRep) {
                    rep[i - 1] = true;
                    break;
                }
            }
        }
        // for (boolean b : rep) System.err.println(b);
        if (!rep[n - 1]) {
            out.writeln(1).writeln(1);
            return;
        }
        CharArrays.reverse(s);
        uni = 1;
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == s[i + 1]) uni++;
            else break;
        }
        z = new Zalgorithm(s).getZ();
        int cnt = !rep[n - 2] ? 1 : 0;
        L2:for (int i = 2; i < n; i++) {
            if (rep[n - i - 1]) continue;
            for (var it = div[i].iterator(); it.hasNext();) {
                int j = it.nextInt();
                boolean isRep = true;
                if (j == 1) {
                    isRep = uni >= i;
                } else {
                    int l = j;
                    for (int k = l << 1; k <= i; k <<= 1, l <<= 1) {
                        if (z[l] < l) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        if (z[i - l] < l) {
                            isRep = false;
                        }
                    }
                }
                if (isRep) continue L2;
            }
            cnt++;
        }
        out.writeln(2).writeln(cnt);
    }
