import java.util.ArrayList;
import java.util.Arrays;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	void solver(char[] w) {
		boolean all = true;
		for (int i = 1; i < w.length; i++) {
			if (w[i] != w[i - 1]) {
				all = false;
				break;
			}
		}
		if (all) {
			out.println(w.length + "\n" + 1);
			return;
		}
		n = w.length;
		long b = 29;
		long[] mod = { 1000000007 };
		hash = new long[mod.length][n];
		pow = new long[mod.length][n];
		for (int i = 0; i < 1; i++) {
			for (int j = 0; j < n; j++) {
				if (j == 0)
					pow[i][j] = 1;
				else {
					pow[i][j] = pow[i][j - 1] * b;
					if (pow[i][j] >= mod[i])
						pow[i][j] %= mod[i];
				}
			}
		}

		for (int i = 0; i < 1; i++) {
			for (int j = n - 1; j >= 0; j--) {
				hash[i][j] = (w[j] - 'a') + (j == n - 1 ? 0 : hash[i][j + 1] * b);
				if (hash[i][j] >= mod[i])
					hash[i][j] %= mod[i];
			}
		}
		div = new ArrayList[n + 1];
		for (int i = 0; i <= n; i++) {
			div[i] = new ArrayList<>();
			if (i > 1)
				div[i].add(1);
		}
		for (int i = n - 1; i >= 2; i--) {
			for (int j = 2 * i; j <= n; j += i) {
				div[j].add(i);
			}
		}
		for (int i = 0; i < 1; i++) {
			if (isGood(0, n, mod[i], i)) {
				out.println("1\n1");
				return;
			}
		}
		long ret = 0;
		ok = new boolean[n];
		Arrays.fill(ok, true);
		for (int i = 1; i < n; i++) {
			boolean f = true;
			for (int j = 0; j < 1; j++) {
				if (!ok[i] || !isGood(i, n, mod[j], j) || !isGood(0, i, mod[j], j)) {
					f = false;
					break;
				}
			}
			if (f) {
				ret++;
			}
		}
		out.println(2 + "\n" + ret);
	}

	ArrayList<Integer>[] div;
	boolean[] ok;
	long[][] hash;
	long[][] pow;
	int n;

	boolean isGood(int s, int t, long mod, int mode) {
		for (int period : div[t - s]) {
			long v1 = (hash[mode][s] - hash[mode][t - period] * pow[mode][t - s - period] % mod + mod) % mod;
			long v2 = (hash[mode][s + period]
					- (t == hash[mode].length ? 0 : hash[mode][t] * pow[mode][t - s - period] % mod) + mod) % mod;
			if (v1 == v2) {
				if (s != 0 || (s == 0 && t == n)) {
					for (int j = s + period; j + 2 * period <= t && j < n; j += period) {
						ok[j] = false;
					}
				}
				return false;
			}
		}
		return true;
	}

	void run() {
