        }
        return a;
    }
    static boolean[] vs(String s){
        int sa[]=suffixArray(s);
        int lcp[]=lcp(sa,s);
        int n=s.length();
        SegmentTree st=new SegmentTree(lcp);
        int rm[]=new int[n];
        for(int i=0;i<n;i++){
            rm[sa[i]]=i;
        }
        boolean vs[]=new boolean[n];
        Arrays.fill(vs,true);
        for(int i=1;i<=n;i++){
