import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;



public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        char[] s = sc.nextChars();
        int n = s.length;
        boolean uni = true;
        for (int i = 0; i < n - 1; i++) uni &= s[i] == s[i + 1];
        if (uni) {
            out.writeln(n).writeln(1);
            return;
        }
        IntArrayList[] div = new IntArrayList[n + 1];
        for (int i = 2; i <= n; i++) {
            div[i] = new IntArrayList();
            div[i].add(1);
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    div[i].add(j);
                    int d = i / j;
                    if (d != j) div[i].add(d);
                }
            }
        }
        int[] z = new Zalgorithm(s).getZ();
        boolean[] rep = new boolean[n];
        for (int i = 2; i <= n; i++) {
            for (var it = div[i].iterator(); it.hasNext();) {
                int j = it.nextInt();
                boolean isRep = true;
                int l = j;
                for (int k = l << 1; k <= i; k <<= 1, l <<= 1) {
                    if (z[l] < l) {
                        isRep = false;
                        break;
                    }
                }
                if (isRep && z[i - l] < l) {
                    isRep = false;
                }
                if (isRep) {
                    rep[i - 1] = true;
                    break;
                }
            }
        }
        if (!rep[n - 1]) {
            out.writeln(1).writeln(1);
            return;
        }
        CharArrays.reverse(s);
        z = new Zalgorithm(s).getZ();
        int cnt = !rep[n - 2] ? 1 : 0;
        L2:for (int i = 2; i < n; i++) {
            if (rep[n - i - 1]) continue;
            for (var it = div[i].iterator(); it.hasNext();) {
                int j = it.nextInt();
                boolean isRep = true;
                int l = j;
                for (int k = l << 1; k <= i; k <<= 1, l <<= 1) {
                    if (z[l] < l) {
                        isRep = false;
                        break;
                    }
                }
                if (isRep && z[i - l] < l) {
                    isRep = false;
                }
                if (isRep) continue L2;
            }
            cnt++;
        }
        out.writeln(2).writeln(cnt);
    }
}


