		out.flush();
	}

	void rand() {
		while (true) {
			int n = (1 + (int) (Math.random() * 500000));
			if (n % 8 == 0)
				n = 1;
			int d = (1 + (int) (Math.random() * (500000 / n)));
			char[] c = new char[n * d];
			for (int i = 0; i < n; i++) {
				c[i] = (char) ('a' + (int) (Math.random() * 100) % 26);
				for (int j = 1; j < d; j++) {
					c[i + n * j] = c[i];
				}
			}
			if (n % 7 == 0) {
				Arrays.fill(c, (char) ('a' + (int) (Math.random() * 100) % 26));
			}
			int[] ret1 = solver(c);
			int[] ret2 = correct(c);
			if (ret1[0] != ret2[0] || ret1[1] != ret2[1]) {
				tr(ret1);
				tr(ret2);
				tr(c);
			}
		}
	}

	int[] correct(char[] s) {
		int n = s.length;
		outer: for (int pe = 1; pe < n; pe++) {
			if (n % pe == 0) {
				for (int i = 0, j = pe; j < n; i++, j++) {
					if (s[i] != s[j])
						continue outer;
				}
				if (pe == 1) {
					return new int[] { n, 1 };
				}

				int[] z = Z(s);
				int[] dead = new int[n + 1];
				for (int j = 1; j < n; j++) {
					for (int k = 2 * j; k <= n; k += j) {
						if (k <= j + z[j]) {
							dead[k - 1]++;
						}
					}
				}

				char[] rs = rev(s);
				z = Z(rs);
				for (int j = 1; j < n; j++) {
					for (int k = 2 * j; k <= n; k += j) {
						if (k <= j + z[j]) {
							if (n - 2 - (k - 1) >= 0)
								dead[n - 2 - (k - 1)]++;
						}
					}
				}

				int ct = 0;
				for (int j = 0; j < n - 1; j++) {
					if (dead[j] == 0) {
						ct++;
					}
				}
				return new int[] { 2, ct };
			}
