    public static void solve(ExtendedScanner sc, Out out) {
        char[] s = sc.nextChars();
        int n = s.length;
        int uni = 1;
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == s[i + 1]) uni++;
            else break;
        }
        if (uni == n) {
            out.writeln(n).writeln(1);
            return;
        }
        IntArrayList[] div = new IntArrayList[n + 1];
        for (int i = 2; i <= n; i++) {
            div[i] = new IntArrayList();
            div[i].add(1);
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    div[i].add(j);
                    int d = i / j;
                    if (d != j) div[i].add(d);
                }
            }
        }
        int[] z = new Zalgorithm(s).getZ();
        boolean[] rep = new boolean[n];
        for (int i = 2; i <= n; i++) {
            for (var it = div[i].iterator(); it.hasNext();) {
                int j = it.nextInt();
                boolean isRep = true;
                if (j == 1) {
                    isRep = uni >= i;
                } else {
                    int l = j;
                    for (int k = j; k <= i; k += k, l <<= 1) {
                        if (z[k - l] < l) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        l >>= 1;
                        if (z[i - l] < l) {
                            isRep = false;
                        }
                    }
                }
                if (isRep) {
                    rep[i - 1] = true;
                    break;
                }
            }
        }
        if (!rep[n - 1]) {
            out.writeln(1).writeln(1);
            return;
        }
        CharArrays.reverse(s);
        uni = 1;
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == s[i + 1]) uni++;
            else break;
        }
        z = new Zalgorithm(s).getZ();
        int cnt = !rep[n - 2] ? 1 : 0;
        L2:for (int i = 2; i < n; i++) {
            if (rep[n - i - 1]) continue;
            for (var it = div[i].iterator(); it.hasNext();) {
