import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        char[] s = sc.nextChars();
        int n = s.length;
        boolean uni = true;
        for (int i = 0; i < n - 1; i++) {
            uni &= s[i] == s[i + 1];
        }
        if (uni) {
            out.writeln(n).writeln(1);
            return;
        }
        int[] z = new Zalgorithm(s).getZ();
        boolean[] rep = new boolean[n];
        for (int i = 1; i <= n; i++) {
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    boolean isRep = true;
                    for (int k = 0; k < i; k += j) {
                        if (z[k] < j) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rep[i - 1] = true;
                        break;
                    }
                    isRep = true;
                    int d = i / j;
                    for (int k = 0; k < i; k += d) {
                        if (z[k] < d) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rep[i - 1] = true;
                        break;
                    }
                }
            }
        }
        if (!rep[n - 1]) {
            out.writeln(1).writeln(1);
            return;
        }
        CharArrays.reverse(s);
        z = new Zalgorithm(s).getZ();
        int cnt = 0;
        for (int i = 1; i < n; i++) {
            if (rep[n - i - 1]) continue;
            boolean rrep = false;
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    boolean isRep = true;
                    for (int k = 0; k < i; k += j) {
                        if (z[k] < j) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rrep = true;
                        break;
                    }
                    isRep = true;
                    int d = i / j;
                    for (int k = 0; k < i; k += d) {
                        if (z[k] < d) {
                            isRep = false;
                            break;
                        }
                    }
                    if (isRep) {
                        rrep = true;
                        break;
                    }
                }
            }
            if (rrep) continue;
            cnt++;
        }
        out.writeln(2).writeln(cnt);
    }
}


