/**
 * @author https://atcoder.jp/users/suisen
 * 
 * Z-algorithm.
 * 
 * S[i:j] := substring of s from i-th character to (j-1)-th character.
 * 
 * z[i] := the longest length of prefix of S s.t. S[0:z[i]] == S[i:i+z[i]].
 */
final class Zalgorithm {
    private final int n;
    private final int[] z;
    public Zalgorithm(final char[] s) {
        this.n = s.length;
        this.z = new int[n];
        build(s);
    }
    public Zalgorithm(final String s) {this(s.toCharArray());}
    private void build(final char[] s) {
        int c = 0;
        for (int i = 1; i < n; i++){
            if (i + z[i - c] < c + z[c]) {
                z[i] = z[i - c];
            } else {
                int j = Math.max(0, c + z[c] - i);
                while (i + j < n && s[j] == s[i + j]) j++;
                z[i] = j;
                c = i;
            }
        }
        z[0] = n;
    }
