        Scanner in=new Scanner(System.in);
        PrintWriter out=new PrintWriter(System.out);
        String s=in.next();
        if(s.length()==1){
            System.out.println("1\n1");
            return;
        }
        boolean vp[]=vp(s);
        if(vp[s.length()-1]){
            out.println(1);
            out.println(1);
        }
        else{
            int cnt=0;
            for(int i=1;i<s.length();i++){
                if(s.charAt(i)==s.charAt(i-1)){
                    cnt++;
                }
            }
            if(cnt==s.length()-1){
                out.println(s.length());
                out.println(1);
            }else{
                String sr=reverse(s);
                boolean vs[]=reverse(vp(sr));
                cnt=0;
                for(int i=1;i<s.length();i++){
                    if(vs[i]&&vp[i-1])
                        cnt++;
                }
                out.println(2);
