		long[] mod = { 1000000007, 1000000009 };
		long[][] hash = new long[2][n];
		long[][] pow = new long[2][n];
		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < n; j++) {
				if (j == 0)
					pow[i][j] = 1;
				else {
					pow[i][j] = pow[i][j - 1] * b;
					if (pow[i][j] >= mod[i])
						pow[i][j] %= mod[i];
				}
			}
		}

		for (int i = 0; i < 2; i++) {
			for (int j = n - 1; j >= 0; j--) {
				hash[i][j] = (w[j] - 'a') + (j == n - 1 ? 0 : hash[i][j + 1] * b);
				if (hash[i][j] >= mod[i])
					hash[i][j] %= mod[i];
			}
		}
		ArrayList<Integer>[] div = new ArrayList[n + 1];
		for (int i = 0; i <= n; i++) {
			div[i] = new ArrayList<>();
			if (i > 1)
				div[i].add(1);
		}
		for (int i = n - 1; i >= 2; i--) {
			for (long j = 2L * i; j <= n; j += i) {
				div[(int) j].add(i);
			}
		}
		for (int i = 0; i < 2; i++) {
			if (isGood(0, n, hash[i], mod[i], pow[i], div)) {
				out.println("1\n1");
				return;
