		long[][] hash = new long[2][n];
		long[][] pow = new long[2][n];
		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < n; j++) {
				if (j == 0)
					pow[i][j] = 1;
				else {
					pow[i][j] = pow[i][j - 1] * b;
					if (pow[i][j] >= mod[i])
						pow[i][j] %= mod[i];
				}
			}
		}

		for (int i = 0; i < 2; i++) {
			for (int j = n - 1; j >= 0; j--) {
				hash[i][j] = (w[j] - 'a') + (j == n - 1 ? 0 : hash[i][j + 1] * b);
				if (hash[i][j] >= mod[i])
