		}
		ArrayList<Integer>[] div = new ArrayList[n + 1];
		for (int i = 0; i <= n; i++)
			div[i] = new ArrayList<>();
		for (int i = n - 1; i >= 2; i--) {
			for (long j = 2L * i; j <= n; j += i) {
				div[(int) j].add(i);
			}
