	static void solve()
	{
		char[] s = ns().toCharArray();
		int n = s.length;
		outer:
		for(int pe = 1;pe < n;pe++){
			if(n % pe == 0){
				for(int i = 0, j = pe;j < n;i++,j++){
					if(s[i] != s[j])continue outer;
				}
				if(pe == 1){
					out.println(n);
					out.println(1);
					return;
				}

				out.println(2);
				if(n/pe == 2){
					out.println(n-1);
				}else{
					out.println(n-n/pe);
				}
				return;
			}
		}

		out.println(1);
		out.println(1);
	}

