public class Solver
{
    int[] KMP(string s)
    {
        int n = s.Length;
        var pi = new int[n];
        for (int i = 1; i < n; ++i)
        {
            int j = pi[i - 1];
            while (j > 0 && s[i] != s[j])
                j = pi[j - 1];
            if (s[i] == s[j])
                j++;
            pi[i] = j;
        }
        return pi;
    }

    public void Solve()
    {
        string s = ReadToken();

        int n = s.Length;
        bool f = true;
        for (int i = 1; i < n; i++)
            if (s[i] != s[0])
                f = false;
        if (f)
        {
            Write(n);
            Write(1);
            return;
        }

        var p = KMP(s);
        if (p[n - 1] == 0 || n % (n - p[n - 1]) > 0)
        {
            Write(1);
            Write(1);
            return;
        }
        var rp = KMP(new string(s.Reverse().ToArray()));

        int ans = 0;
        for (int i = 0; i + 1 < n; i++)
        {
            int j = n - i - 2;
            if ((p[i] == 0 || (i + 1) % (i + 1 - p[i]) > 0) && (rp[j] == 0 || (n - i - 1) % (n - i - 1 - rp[j]) > 0))
                ans++;
        }

        Write(2);
        Write(ans);
    }

