int[] Z_algorithm(string s) {
    auto A = new int[](s.length);
    A[0] = s.length.to!int;

    for (int i = 1, j = 0; i < s.length; ) {
        while (i + j < s.length && s[j] == s[i+j]) ++j;
        A[i] = j;
        if (j == 0) { ++i; continue; }
        int k = 1;
        while (i + k < s.length && k + A[k] < j) A[i+k] = A[k], ++k;
        i += k; j -= k;
    }

    return A;
}

