    auto z2 = Z_algorithm(T);
    auto ng1 = new bool[](N + 1);
    auto ng2 = new bool[](N + 1);

    for (int i = 0; i < N; i++) {
        if (i > 0 && i - z1[i] <= 0) {
            int len = min(i, z1[i]);
