    	while (j!=0 && s[i]!=s[j+1]) j=nxt[j];
    	if (s[i]==s[j+1]) j++;
    	nxt[i]=j;
    }

    for (int i=1; i<=n; i++)
	    if (nxt[i]==0 || i%(i-nxt[i])!=0)
		    f[x][i]=true;
}
