{
	prepare();
	scanf("%s",str+1);
	n=strlen(str+1);
	for(int i=1;i<=n;i++)
		Hash[i]=(1LL*Hash[i-1]*P+1LL*str[i])%MO;
	for(int i=1;i<=n;i++)
	{
		int val=Hash[i];
		for(int totlen=i*2;totlen<=n;totlen+=i)
		{
			val=(1LL*val*Pow[i]%MO+1LL*Hash[i])%MO;
			if(Hash[totlen]==val)
				l[totlen]=true;
			else
				break;
		}
	}
	reverse(str+1,str+1+n);
	memset(Hash,0,sizeof(Hash));
	for(int i=1;i<=n;i++)
		Hash[i]=(1LL*Hash[i-1]*P+1LL*str[i])%MO;
	for(int i=1;i<=n;i++)
	{
		int val=Hash[i];
		for(int totlen=i*2;totlen<=n;totlen+=i)
		{
			val=(1LL*val*Pow[i]%MO+1LL*Hash[i])%MO;
			if(Hash[totlen]==val)
				r[totlen]=true;
			else
				break;
		}
	}

	if(l[n]==false)
	{
		printf("1\n1\n");
		return 0;
	}
