	for(int i=1;i<n;i++)
		if(str[i]!=str[i+1])
		{
			same=false;
			break;
		}
	if(same==true)
	{
		printf("%d\n1\n",n);
		return 0;
	}
	int ans=0;
	for(int i=1;i<=n;i++)
		if(l[i]==false&&r[n-i]==false)
			ans++;
	printf("2\n%d\n",ans);
	return 0;
}

