fn main() {
    let stdin = std::io::stdin();
    let mut w = stdin.lock().gets().into_bytes();
    let mut badsp = vec![false; w.len() + 1];
    check_from_left(&w, &mut badsp);
    w.reverse();
    badsp.reverse();
    check_from_left(&w, &mut badsp);
    if !badsp[0] && !badsp[w.len()] {
        println!("1");
        println!("1");
    } else {
        let count = badsp[1..w.len()].into_iter().filter(|&x| !x).count();
        if count == 0 {
            println!("{}", w.len());
            println!("1");
        } else {
            println!("2");
            println!("{}", count);
        }
    }
}

fn check_from_left(w: &[u8], badsp: &mut [bool]) {
    let mut done = vec![false; w.len() / 2 + 1];
    for len in 1..w.len() / 2 + 1 {
        if done[len] {
            continue;
        }
        let mut start = len;
        while start + len <= w.len() && w[..len] == w[start..start + len] {
            badsp[start + len] = true;
            start += len;
        }
        let mut mul = len * 2;
        while mul <= std::cmp::min(w.len() / 2, start) {
            done[mul] = true;
            mul += len;
        }
    }
}

